INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X04','kor',4,'u4',ARRAY['K4-1-u4-C4']::text[],'중심 생각을 글에 나온 사실 하나나 글이 다루는 소재로 여긴다','전하고 싶은 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
