INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X08','kor',4,'u4',ARRAY['K4-1-u4-C8']::text[],'글자 모양이나 소리가 같은지로 동형이의어와 다의어를 가를 수 있다고 여긴다','뜻이 이어졌나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X09','kor',4,'u4',ARRAY['K4-1-u4-C8']::text[],'뜻이 이어지면 동형이의어, 이어지지 않으면 다의어라고 거꾸로 짚는다','이어지면 다의어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X10','kor',4,'u4',ARRAY['K4-1-u4-C10','K4-1-u4-C18']::text[],'동형이의어를 사전에서 한 낱말 안에 「1」 「2」로 싣는다고 여긴다','번호를 붙여 따로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X11','kor',4,'u4',ARRAY['K4-1-u4-C11','K4-1-u4-C18']::text[],'다의어를 사전에서 번호를 붙여 따로 싣는다고 여긴다','한 낱말 안에 이어서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X12','kor',4,'u4',ARRAY['K4-1-u4-C12']::text[],'한 낱말은 늘 동형이의어이거나 늘 다의어라고 단정한다','견주는 뜻에 따라') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X13','kor',4,'u4',ARRAY['K4-1-u4-C13','K4-1-u4-C22']::text[],'뜻이 다른 문장을 만든다면서 같은 뜻으로 두 문장을 만든다','두 뜻이 달라야 해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X14','kor',4,'u4',ARRAY['K4-1-u4-C15']::text[],'낱말 자리에 대신할 말을 넣어 볼 때 문장의 뜻이 달라지는 말을 넣는다','뜻이 그대로인 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X15','kor',4,'u4',ARRAY['K4-1-u4-C16']::text[],'사전에서 글에 쓰인 모양 그대로(열자 · 무거워서) 찾는다','기본형으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X16','kor',4,'u4',ARRAY['K4-1-u4-C17']::text[],'사전에 실린 첫 번째 뜻이 언제나 문장 속 뜻이라고 여긴다','문장에 맞는 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X17','kor',4,'u4',ARRAY['K4-1-u4-C19']::text[],'한 글 안에서는 같은 낱말이 늘 같은 뜻이라고 여긴다','자리마다 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X18','kor',4,'u4',ARRAY['K4-1-u4-C20']::text[],'광고나 표어 속 여러 뜻 낱말을 잘못 쓴 말로 여기거나 한 가지 뜻만 전한다고 여긴다','두 뜻을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X19','kor',4,'u4',ARRAY['K4-1-u4-C21']::text[],'광고에 여러 뜻 낱말을 쓰는 까닭을 뜻을 없애거나 헷갈리게 하려는 것으로 여긴다','재미 · 전달 · 기억') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X20','kor',4,'u4',ARRAY['K4-1-u4-C23']::text[],'가리키는 말을 물건이나 사람의 이름 그 자체로 여긴다','집어서 가리키는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X21','kor',4,'u4',ARRAY['K4-1-u4-C24','K4-1-u4-C25','K4-1-u4-C26']::text[],'이것 · 그것 · 저것이 가리키는 거리(말하는 사람 · 듣는 사람 · 둘 모두에게서 멂)를 엇갈리게 쓴다','누구에게 가까운가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X22','kor',4,'u4',ARRAY['K4-1-u4-C27']::text[],'가리키는 말은 바로 앞에 보이는 물건에만 쓰고, 글에서 앞에 나온 내용은 가리킬 수 없다고 여긴다','앞 내용도 가리켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X23','kor',4,'u4',ARRAY['K4-1-u4-C28']::text[],'가리키는 내용을 앞뒤 문장이 아닌 엉뚱한 곳(제목 · 맨 끝 · 다른 낱말)에서 찾는다','바로 앞을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X24','kor',4,'u4',ARRAY['K4-1-u4-C29']::text[],'가리키는 말이 늘 낱말 하나만 가리킨다고 여겨 앞 내용의 일부만 고른다','여럿을 함께 가리켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X25','kor',4,'u4',ARRAY['K4-1-u4-C30']::text[],'가리키는 말을 쓰면 글의 내용이 바뀌거나 길어진다고 여기는 등 좋은 점을 엇갈리게 안다','되풀이 없이 짧고 깔끔하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X26','kor',4,'u4',ARRAY['K4-1-u4-C31']::text[],'처음 나오는 말부터 가리키는 말로 바꾸거나, 엉뚱한 낱말을 가리키는 말로 바꾼다','처음은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X27','kor',4,'u4',ARRAY['K4-1-u4-C32','K4-1-u4-C36']::text[],'이야기의 중심 생각을 제목 · 줄거리 · 인물의 말과 행동 가운데 하나만 보고 정한다','모두 모아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X28','kor',4,'u4',ARRAY['K4-1-u4-C33']::text[],'제목을 그대로 중심 생각으로 여기거나, 제목은 중심 생각과 상관없다고 여긴다','제목은 실마리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X29','kor',4,'u4',ARRAY['K4-1-u4-C34']::text[],'줄거리에 이야기에 없던 일을 넣거나 작은 일까지 모두 늘어놓는다','있었던 주요 장면만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X30','kor',4,'u4',ARRAY['K4-1-u4-C35']::text[],'인물의 생각을 말과 행동이 아니라 생김새 · 이름 · 키로 찾는다','말과 행동을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X31','kor',4,'u4',ARRAY['K4-1-u4-C37']::text[],'글에 없는 내 경험이나 상상으로 중심 생각을 정한다','글 안에서 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X32','kor',4,'u4',ARRAY['K4-1-u4-C38']::text[],'줄거리(있었던 일)를 중심 생각으로 고른다','그 일로 전하려는 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X33','kor',4,'u4',ARRAY['K4-1-u4-C39']::text[],'한 장면의 작은 일에서 엉뚱한 생각을 끌어내 중심 생각으로 고른다','작은 장면 하나로는 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X34','kor',4,'u4',ARRAY['K4-1-u4-C40']::text[],'중심 생각을 정리할 때 이야기를 길게 모두 옮겨 적는다','한 문장으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X35','kor',4,'u4',ARRAY['K4-1-u4-C41']::text[],'중심 생각이 같으려면 다루는 소재까지 같아야 한다고 여긴다','소재가 달라도 같은 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X36','kor',4,'u4',ARRAY['K4-1-u4-C43']::text[],'한 번만 나온 낱말이나 길고 어려운 낱말을 중요한 낱말로 고른다','제목 · 여러 번') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X37','kor',4,'u4',ARRAY['K4-1-u4-C44']::text[],'한 문단에 중심 내용이 여럿이라고 여기거나 문단과 중심 내용을 엇갈리게 잇는다','한 문단에 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X38','kor',4,'u4',ARRAY['K4-1-u4-C45']::text[],'중심 문장과 뒷받침 문장을 거꾸로 짚는다','하고 싶은 말 · 받쳐 주는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X39','kor',4,'u4',ARRAY['K4-1-u4-C46']::text[],'중심 생각은 늘 글에 한 문장으로 쓰여 있다고 여겨, 그 문장이 없으면 찾을 수 없다고 한다','모아서 정리해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X40','kor',4,'u4',ARRAY['K4-1-u4-C47']::text[],'글쓴이의 생각은 가운데 문단에만 드러난다고 여긴다','첫 문단 · 마지막 문단') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X41','kor',4,'u4',ARRAY['K4-1-u4-C48']::text[],'까닭 하나(몸이 튼튼해진다)를 글 전체의 중심 생각으로 고른다','까닭은 받쳐 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X42','kor',4,'u4',ARRAY['K4-1-u4-C49']::text[],'이야기와 주장하는 글을 똑같은 자리에서만 살피거나, 한쪽에는 중심 생각이 없다고 여긴다','글의 종류에 따라') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X43','kor',4,'u4',ARRAY['K4-1-u4-C42']::text[],'주장하는 글의 중심 생각을 찾는 방법이 아닌 것(글자 수 세기 · 그림 색깔 보기)을 방법으로 고른다','낱말 · 문단 · 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X44','kor',4,'u4',ARRAY['K4-1-u4-C50']::text[],'중심 생각과 상관없는 일을 읽고 정한 실천으로 고른다','중심 생각에서 나온 다짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X45','kor',4,'u4',ARRAY['K4-1-u4-C51']::text[],'낱말 알아맞히기 놀이에서 한 빈칸에만 맞는 낱말을 답으로 고른다','두 빈칸 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X46','kor',4,'u4',ARRAY['K4-1-u4-C52']::text[],'기사에 나온 작은 사실(날짜 · 숫자 · 재료)을 기사가 전하려는 생각으로 고른다','전하려는 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X47','kor',4,'u4',ARRAY['K4-1-u4-C53']::text[],'된소리로 소리 나는 대로 적는다(학꾜)','적을 때는 원래대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X48','kor',4,'u4',ARRAY['K4-1-u4-C53']::text[],'된소리로 소리 나지 않는 낱말을 된소리로 고르거나, 된소리로 나는 낱말을 그대로 읽는다','받침 뒤 소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X49','kor',4,'u4',ARRAY['K4-1-u4-C54']::text[],'소리가 비슷하면 모두 바른 말이라고 여긴다(설겆이)','바른 말인지 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u4-X50','kor',4,'u4',ARRAY['K4-1-u4-C54']::text[],'함께 쓰는 바른 말 가운데 하나만 바른 말이라고 여긴다','둘 다 바른 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#1','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C6',1,'mc','auto','「병에 물을 가득 담았다.」와 「병이 나아 학교에 왔다.」의 「병」처럼 형태만 같고 뜻이 전혀 다른 낱말을 무엇이라고 하나요?',ARRAY['K4-1-u4-X09','K4-1-u4-X06','K4-1-u4-X08']::text[],false,'{"seq":1,"concept":"K4-1-u4-C6","difficulty":1,"kind":"mc","stem":"「병에 물을 가득 담았다.」와 「병이 나아 학교에 왔다.」의 「병」처럼 형태만 같고 뜻이 전혀 다른 낱말을 무엇이라고 하나요?","options":[{"t":"동형이의어","correct":true},{"t":"다의어","mis":"K4-1-u4-X09"},{"t":"뜻이 서로 이어진 한 낱말","mis":"K4-1-u4-X06"},{"t":"글자 모양이 다른 두 낱말","mis":"K4-1-u4-X08"}],"explanation":["두 「병」은 무엇을 뜻하나요?","그릇과 앓는 것 — 이어지지 않아요.","동형이의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#2','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C7',1,'mc','auto','「가방이 무겁다.」, 「마음이 무겁다.」, 「입이 무겁다.」처럼 원래 뜻을 넓혀 여러 뜻으로 쓰는 낱말을 무엇이라고 하나요?',ARRAY['K4-1-u4-X09','K4-1-u4-X07','K4-1-u4-X08']::text[],false,'{"seq":2,"concept":"K4-1-u4-C7","difficulty":1,"kind":"mc","stem":"「가방이 무겁다.」, 「마음이 무겁다.」, 「입이 무겁다.」처럼 원래 뜻을 넓혀 여러 뜻으로 쓰는 낱말을 무엇이라고 하나요?","options":[{"t":"다의어","correct":true},{"t":"동형이의어","mis":"K4-1-u4-X09"},{"t":"뜻이 서로 상관없는 세 낱말","mis":"K4-1-u4-X07"},{"t":"글자가 서로 다른 낱말","mis":"K4-1-u4-X08"}],"explanation":["무게에서 마음으로, 말로","뜻이 넓어졌어요.","다의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#3','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C3',1,'mc','auto','동생과 나눈 말에서 동생이 말한 「김」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X03','K4-1-u4-X02']::text[],false,'{"seq":3,"concept":"K4-1-u4-C3","difficulty":1,"kind":"mc","stem":"동생과 나눈 말에서 동생이 말한 「김」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"바다에서 나는, 얇게 말린 먹을거리","correct":true},{"t":"뜨거운 것에서 나는 흰 기운","mis":"K4-1-u4-X03"},{"t":"유리에 서린 작은 물방울","mis":"K4-1-u4-X03"},{"t":"「김」은 어디에 쓰여도 뜻이 하나라 고를 수 없다","mis":"K4-1-u4-X02"}],"explanation":["「밥에 올려 줘」를 봐요.","밥에 올리는 것은?","먹는 김이에요."],"asset":{"type":"speech","turns":[{"who":"동생","text":"밥에 김 좀 올려 줘."},{"who":"나","text":"밥에서 김이 나는데 어떻게 올려?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#4','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C9',1,'match','auto','「무겁다」가 쓰인 문장과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K4-1-u4-C9","difficulty":1,"kind":"match","stem":"「무겁다」가 쓰인 문장과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"가방이 무겁다.","r":"무게가 많이 나가다"},{"l":"마음이 무겁다.","r":"걱정이 있어 답답하다"},{"l":"입이 무겁다.","r":"말이 적고 조심스럽다"}],"mis":"K4-1-u4-X07","explanation":["처음 뜻은 무게예요.","마음 · 말로 넓어졌어요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#5','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C4',2,'mc','auto','「남는 우산」에서 글쓴이가 글로 전하고 싶은 생각은 무엇인가요?',ARRAY['K4-1-u4-X04']::text[],false,'{"seq":5,"concept":"K4-1-u4-C4","difficulty":2,"kind":"mc","stem":"「남는 우산」에서 글쓴이가 글로 전하고 싶은 생각은 무엇인가요?","options":[{"t":"남는 우산을 함께 쓰자","correct":true},{"t":"우리 반에는 남는 우산이 두 개 있다","mis":"K4-1-u4-X04"},{"t":"지난주에 비가 왔다","mis":"K4-1-u4-X04"},{"t":"우산은 비 오는 날에 쓴다","mis":"K4-1-u4-X04"}],"explanation":["글쓴이가 바라는 것은?","마지막 문장을 봐요.","함께 쓰자는 생각이에요."],"asset":{"type":"passage","lines":["비 오는 날, 우리 반에는 남는 우산이 두 개 있다.","지난주에 우산이 없어 젖은 채로 집에 간 친구가 있었다.","그 모습을 보니 마음이 무거웠다.","남는 우산을 함께 쓰는 자리에 두면 좋겠다."],"title":"남는 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#6','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C5',2,'mc','auto','중심 생각을 파악하며 읽으면 좋은 점이 아닌 것은 무엇인가요?',ARRAY['K4-1-u4-X05']::text[],false,'{"seq":6,"concept":"K4-1-u4-C5","difficulty":2,"kind":"mc","stem":"중심 생각을 파악하며 읽으면 좋은 점이 아닌 것은 무엇인가요?","options":[{"t":"글을 더 빨리 넘길 수 있다","correct":true},{"t":"글 전체 내용을 더 잘 이해할 수 있다","mis":"K4-1-u4-X05"},{"t":"읽은 내용을 더 오래 기억할 수 있다","mis":"K4-1-u4-X05"},{"t":"글쓴이의 생각에 내 생각을 견주어 볼 수 있다","mis":"K4-1-u4-X05"}],"explanation":["이해 · 기억 · 견주기","빨리 넘기려는 걸까요?","빨리 넘기기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#7','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C8',2,'mc','auto','동형이의어와 다의어를 가르는 갈림길은 무엇인가요?',ARRAY['K4-1-u4-X08']::text[],false,'{"seq":7,"concept":"K4-1-u4-C8","difficulty":2,"kind":"mc","stem":"동형이의어와 다의어를 가르는 갈림길은 무엇인가요?","options":[{"t":"두 뜻 사이에 이어짐이 있는가","correct":true},{"t":"글자 모양이 같은가","mis":"K4-1-u4-X08"},{"t":"소리가 같은가","mis":"K4-1-u4-X08"},{"t":"글자 수가 몇 개인가","mis":"K4-1-u4-X08"}],"explanation":["둘 다 글자 모양은 같아요.","뜻이 이어졌나요?","이어짐이 갈림길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#8','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C10',2,'mc','auto','국어사전에서 「병」 같은 동형이의어를 싣는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X10']::text[],false,'{"seq":8,"concept":"K4-1-u4-C10","difficulty":2,"kind":"mc","stem":"국어사전에서 「병」 같은 동형이의어를 싣는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"병¹, 병²처럼 번호를 붙여 따로 싣는다","correct":true},{"t":"한 낱말 안에 「1」, 「2」로 이어 싣는다","mis":"K4-1-u4-X10"},{"t":"둘 가운데 하나만 싣는다","mis":"K4-1-u4-X10"},{"t":"사전에는 싣지 않는다","mis":"K4-1-u4-X10"}],"explanation":["서로 다른 낱말이에요.","따로 실어요.","번호를 붙여요."],"asset":{"type":"passage","lines":["병¹ 몸에 이상이 생겨 앓는 것. 예 병이 낫다.","병² 액체를 담는 목이 좁은 그릇. 예 병에 물을 담다.","무겁다 「1」 무게가 많이 나가다. 「2」 마음이 답답하다. 「3」 말이 적고 조심스럽다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#9','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C11',2,'mc','auto','국어사전에 「무겁다」가 실린 모양을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X11','K4-1-u4-X02']::text[],false,'{"seq":9,"concept":"K4-1-u4-C11","difficulty":2,"kind":"mc","stem":"국어사전에 「무겁다」가 실린 모양을 바르게 말한 것은 무엇인가요?","options":[{"t":"한 낱말 안에 「1」, 「2」, 「3」으로 뜻이 이어져 실려 있다","correct":true},{"t":"무겁다¹, 무겁다², 무겁다³으로 따로 실려 있다","mis":"K4-1-u4-X11"},{"t":"뜻이 하나만 실려 있다","mis":"K4-1-u4-X02"},{"t":"번호 없이 아무렇게나 실려 있다","mis":"K4-1-u4-X11"}],"explanation":["사전을 봐요.","한 낱말 아래 뜻 셋","다의어의 모양이에요."],"asset":{"type":"passage","lines":["병¹ 몸에 이상이 생겨 앓는 것. 예 병이 낫다.","병² 액체를 담는 목이 좁은 그릇. 예 병에 물을 담다.","무겁다 「1」 무게가 많이 나가다. 「2」 마음이 답답하다. 「3」 말이 적고 조심스럽다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_basic#10','kor',4,1,'u4','L02','g4_1_kor_u4_L02_basic','lesson_basic','K4-1-u4-C12',3,'mc','auto','「김」을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X12','K4-1-u4-X02']::text[],false,'{"seq":10,"concept":"K4-1-u4-C12","difficulty":3,"kind":"mc","stem":"「김」을 바르게 말한 것은 무엇인가요?","options":[{"t":"「먹는 김 — 오르는 김」은 동형이의어지만, 「오르는 김 — 유리에 서린 김」은 뜻이 이어져 있다","correct":true},{"t":"「김」은 언제나 동형이의어이다","mis":"K4-1-u4-X12"},{"t":"「김」은 언제나 다의어이다","mis":"K4-1-u4-X12"},{"t":"글자가 같으니 모든 「김」은 뜻이 같다","mis":"K4-1-u4-X02"}],"explanation":["어떤 뜻끼리 견주나요?","오르는 김과 서린 김은 이어져요.","늘 한쪽은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#1','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C1',2,'mc','auto','「뜻을 파악하며 읽어요」 단원에서 배우지 않는 것은 무엇인가요?',ARRAY['K4-1-u4-X01']::text[],false,'{"seq":1,"concept":"K4-1-u4-C1","difficulty":2,"kind":"mc","stem":"「뜻을 파악하며 읽어요」 단원에서 배우지 않는 것은 무엇인가요?","options":[{"t":"인물이 되어 인형극 하기","correct":true},{"t":"여러 가지로 해석되는 낱말 구분하기","mis":"K4-1-u4-X01"},{"t":"글의 중심 생각 파악하며 읽기","mis":"K4-1-u4-X01"},{"t":"가리키는 말이 가리키는 내용 찾기","mis":"K4-1-u4-X01"}],"explanation":["단원 안내를 떠올려요.","낱말의 뜻 · 중심 생각","인형극은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#2','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C2',2,'mc','auto','「길」이 「사람이 다니는 곳」이라는 뜻으로 쓰인 문장은 무엇인가요?',ARRAY['K4-1-u4-X03','K4-1-u4-X02']::text[],false,'{"seq":2,"concept":"K4-1-u4-C2","difficulty":2,"kind":"mc","stem":"「길」이 「사람이 다니는 곳」이라는 뜻으로 쓰인 문장은 무엇인가요?","options":[{"t":"학교로 가는 길이 좁다.","correct":true},{"t":"좋은 길을 찾아냈다.","mis":"K4-1-u4-X03"},{"t":"집으로 돌아오는 길에 친구를 만났다.","mis":"K4-1-u4-X03"},{"t":"「길」은 어느 문장에서나 뜻이 같다.","mis":"K4-1-u4-X02"}],"explanation":["걸어 다니는 곳은?","좁다 · 넓다","학교로 가는 길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#3','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C6',3,'mc','auto','다음 가운데 동형이의어끼리 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u4-X09']::text[],false,'{"seq":3,"concept":"K4-1-u4-C6","difficulty":3,"kind":"mc","stem":"다음 가운데 동형이의어끼리 짝 지은 것은 무엇인가요?","options":[{"t":"풀을 뽑다 / 풀로 붙이다","correct":true},{"t":"물이 깊다 / 생각이 깊다","mis":"K4-1-u4-X09"},{"t":"운동장이 넓다 / 마음이 넓다","mis":"K4-1-u4-X09"},{"t":"산이 높다 / 소리가 높다","mis":"K4-1-u4-X09"}],"explanation":["뜻이 이어지지 않는 짝은?","땅의 풀과 붙이는 풀","풀이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#4','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C7',3,'mc','auto','다음 가운데 다의어끼리 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u4-X06']::text[],false,'{"seq":4,"concept":"K4-1-u4-C7","difficulty":3,"kind":"mc","stem":"다음 가운데 다의어끼리 짝 지은 것은 무엇인가요?","options":[{"t":"물이 맑다 / 목소리가 맑다","correct":true},{"t":"비가 오다 / 비로 쓸다","mis":"K4-1-u4-X06"},{"t":"말을 타다 / 말을 하다","mis":"K4-1-u4-X06"},{"t":"빨래를 말리다 / 싸움을 말리다","mis":"K4-1-u4-X06"}],"explanation":["뜻이 이어진 짝은?","깨끗한 물 → 깨끗한 소리","맑다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#5','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C9',3,'mc','auto','「물이 깊다」의 「깊다」가 「생각이 깊다」로 쓰인 것을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X07','K4-1-u4-X02','K4-1-u4-X08']::text[],false,'{"seq":5,"concept":"K4-1-u4-C9","difficulty":3,"kind":"mc","stem":"「물이 깊다」의 「깊다」가 「생각이 깊다」로 쓰인 것을 바르게 말한 것은 무엇인가요?","options":[{"t":"밑바닥까지 멀다는 처음 뜻이 생각에까지 넓어져 이어져 있다","correct":true},{"t":"두 뜻은 서로 아무 상관이 없다","mis":"K4-1-u4-X07"},{"t":"「생각이 깊다」도 물속처럼 밑바닥이 멀다는 뜻이다","mis":"K4-1-u4-X02"},{"t":"글자가 같아서 다의어일 뿐이다","mis":"K4-1-u4-X08"}],"explanation":["처음 뜻은?","넓어진 뜻은?","이어져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#6','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C13',3,'mc','auto','「풀다」로 뜻이 서로 다른 문장 두 개를 바르게 만든 것은 무엇인가요?',ARRAY['K4-1-u4-X13','K4-1-u4-X02']::text[],false,'{"seq":6,"concept":"K4-1-u4-C13","difficulty":3,"kind":"mc","stem":"「풀다」로 뜻이 서로 다른 문장 두 개를 바르게 만든 것은 무엇인가요?","options":[{"t":"「신발 끈을 풀다.」 / 「수학 문제를 풀다.」","correct":true},{"t":"「신발 끈을 풀다.」 / 「운동화 끈을 풀다.」","mis":"K4-1-u4-X13"},{"t":"「매듭을 풀다.」 / 「묶은 끈을 풀다.」","mis":"K4-1-u4-X13"},{"t":"「풀다」는 뜻이 하나뿐이라 만들 수 없다","mis":"K4-1-u4-X02"}],"explanation":["두 문장의 뜻이 달라야 해요.","끈과 문제","뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#7','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C12',3,'mc','auto','친구가 「말」은 늘 동형이의어라고 말했어요. 가장 알맞게 대답한 것은 무엇인가요?',ARRAY['K4-1-u4-X12','K4-1-u4-X08']::text[],false,'{"seq":7,"concept":"K4-1-u4-C12","difficulty":3,"kind":"mc","stem":"친구가 「말」은 늘 동형이의어라고 말했어요. 가장 알맞게 대답한 것은 무엇인가요?","options":[{"t":"「어떤 뜻끼리 견주는지에 따라 다르니, 문장에서 어떤 뜻으로 썼는지 살펴야 해.」","correct":true},{"t":"「맞아. 「말」이라는 글자는 늘 동형이의어야.」","mis":"K4-1-u4-X12"},{"t":"「아니야. 「말」은 늘 다의어야.」","mis":"K4-1-u4-X12"},{"t":"「글자가 한 개라서 둘 다 아니야.」","mis":"K4-1-u4-X08"}],"explanation":["늘 한쪽일까요?","견주는 뜻에 따라","문장에서 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#8','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C8',4,'essay','teacher','「병에 물을 담다 — 병이 낫다」와 「가방이 무겁다 — 마음이 무겁다」가 각각 동형이의어인지 다의어인지 쓰고, 그렇게 가른 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u4-C8","difficulty":4,"kind":"essay","stem":"「병에 물을 담다 — 병이 낫다」와 「가방이 무겁다 — 마음이 무겁다」가 각각 동형이의어인지 다의어인지 쓰고, 그렇게 가른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「병」 짝은 동형이의어이다. 물을 담는 그릇과 몸이 앓는 것은 뜻이 서로 이어지지 않기 때문이다. 「무겁다」 짝은 다의어이다. 무게가 많이 나간다는 뜻이 마음이 답답하다는 뜻으로 넓어져 서로 이어져 있기 때문이다.","scoring_points":["「병」 짝을 동형이의어라고 썼는가","「무겁다」 짝을 다의어라고 썼는가","뜻의 이어짐으로 까닭을 썼는가"]},"explanation":["그릇과 앓는 것","무게와 마음","이어졌나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#9','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C13',4,'essay','teacher','「넓다」로 뜻이 서로 다른 문장 두 개를 만들고, 두 문장에서 「넓다」가 어떤 뜻인지 각각 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u4-C13","difficulty":4,"kind":"essay","stem":"「넓다」로 뜻이 서로 다른 문장 두 개를 만들고, 두 문장에서 「넓다」가 어떤 뜻인지 각각 쓰세요.","answer_guide":{"answer":"예: 「운동장이 넓다.」 — 차지한 자리가 크다. 「짝은 마음이 넓다.」 — 남을 너그럽게 이해하는 마음이 크다.","scoring_points":["뜻이 다른 문장 두 개를 만들었는가","첫째 문장의 뜻을 썼는가","둘째 문장의 뜻을 썼는가"]},"explanation":["자리가 넓다","마음이 넓다","뜻을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L02_challenge#10','kor',4,1,'u4','L02','g4_1_kor_u4_L02_challenge','lesson_challenge','K4-1-u4-C4',4,'essay','teacher','「남는 우산」의 중심 생각을 쓰고, 그렇게 생각한 까닭을 글에서 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u4-C4","difficulty":4,"kind":"essay","stem":"「남는 우산」의 중심 생각을 쓰고, 그렇게 생각한 까닭을 글에서 찾아 쓰세요.","answer_guide":{"answer":"예: 중심 생각은 「남는 우산을 함께 쓰자.」이다. 우산이 없어 젖은 채 집에 간 친구를 보고 마음이 무거웠다고 했고, 마지막에 남는 우산을 함께 쓰는 자리에 두자고 했기 때문이다.","scoring_points":["중심 생각을 바르게 썼는가","글에서 까닭을 찾았는가","중심 생각과 까닭을 이었는가"]},"explanation":["글쓴이가 바라는 것","마음이 무거웠던 까닭","글에서 찾아요."],"asset":{"type":"passage","lines":["비 오는 날, 우리 반에는 남는 우산이 두 개 있다.","지난주에 우산이 없어 젖은 채로 집에 간 친구가 있었다.","그 모습을 보니 마음이 무거웠다.","남는 우산을 함께 쓰는 자리에 두면 좋겠다."],"title":"남는 우산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#1','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C14',1,'mc','auto','「빵집에 가는 길」 ①의 「빵집에 가는 길이었다」에서 「길」의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X03']::text[],false,'{"seq":1,"concept":"K4-1-u4-C14","difficulty":1,"kind":"mc","stem":"「빵집에 가는 길」 ①의 「빵집에 가는 길이었다」에서 「길」의 뜻은 무엇인가요?","options":[{"t":"어떤 일을 하는 도중","correct":true},{"t":"사람이 다니는 곳","mis":"K4-1-u4-X03"},{"t":"일을 해내는 방법","mis":"K4-1-u4-X03"},{"t":"빵을 담는 봉지","mis":"K4-1-u4-X03"}],"explanation":["가는 「중」이었어요.","앞뒤를 읽어요.","도중이에요."],"asset":{"type":"passage","lines":["① 학교가 끝나고 할머니와 빵집에 가는 길이었다.","② 골목이 좁은 길이라 우리는 나란히 걷지 못했다.","③ 빵집 문을 열자 따뜻한 김이 확 끼쳤다.","④ \"갓 구운 빵이라 아직 김이 나네.\" 주인아저씨가 웃으셨다.","⑤ 할머니는 빵과 함께 김 한 봉지도 담으셨다.","⑥ \"이 빵집을 어떻게 아셨어요?\" \"좋은 길은 물어물어 찾는 거란다.\"","⑦ 집으로 돌아오는 길에 나는 빵 봉지를 꼭 안았다."],"title":"빵집에 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#2','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C16',1,'mc','auto','국어사전에서 「열자」의 뜻을 찾으려면 어떤 모양으로 찾아야 하나요?',ARRAY['K4-1-u4-X15']::text[],false,'{"seq":2,"concept":"K4-1-u4-C16","difficulty":1,"kind":"mc","stem":"국어사전에서 「열자」의 뜻을 찾으려면 어떤 모양으로 찾아야 하나요?","options":[{"t":"열다","correct":true},{"t":"열자","mis":"K4-1-u4-X15"},{"t":"열고","mis":"K4-1-u4-X15"},{"t":"열어","mis":"K4-1-u4-X15"}],"explanation":["사전에는 기본형이 실려요.","「-다」로 끝나요.","열다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#3','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C18',1,'mc','auto','「빵집에 가는 길」의 「따뜻한 김」과 「김 한 봉지」의 「김」은 무엇인가요?',ARRAY['K4-1-u4-X11','K4-1-u4-X10','K4-1-u4-X08']::text[],false,'{"seq":3,"concept":"K4-1-u4-C18","difficulty":1,"kind":"mc","stem":"「빵집에 가는 길」의 「따뜻한 김」과 「김 한 봉지」의 「김」은 무엇인가요?","options":[{"t":"동형이의어","correct":true},{"t":"다의어","mis":"K4-1-u4-X11"},{"t":"뜻이 이어진 한 낱말","mis":"K4-1-u4-X10"},{"t":"둘 다 아니다","mis":"K4-1-u4-X08"}],"explanation":["사전에 김¹ · 김²","번호를 붙여 따로","동형이의어예요."],"asset":{"type":"passage","lines":["김¹ 물이 끓을 때 생기는 흰 기운. 예 김이 오르다.","김² 바다에서 나는, 얇게 말려 먹는 것. 예 김을 굽다.","길 「1」 사람이 다니는 곳. 「2」 일을 해내는 방법. 「3」 어떤 일을 하는 도중."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#4','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C17',1,'match','auto','「빵집에 가는 길」 속 문장과 사전의 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K4-1-u4-C17","difficulty":1,"kind":"match","stem":"「빵집에 가는 길」 속 문장과 사전의 뜻을 알맞게 이으세요.","pairs":[{"l":"골목이 좁은 길","r":"사람이 다니는 곳"},{"l":"좋은 길은 물어물어","r":"일을 해내는 방법"},{"l":"돌아오는 길에","r":"어떤 일을 하는 도중"}],"mis":"K4-1-u4-X16","explanation":["다른 말로 바꿔 읽어요.","곳 · 방법 · 도중","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#5','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C15',2,'mc','auto','⑥ 「좋은 길은 물어물어 찾는 거란다.」에서 「길」 자리에 넣어도 뜻이 그대로인 말은 무엇인가요?',ARRAY['K4-1-u4-X14']::text[],false,'{"seq":5,"concept":"K4-1-u4-C15","difficulty":2,"kind":"mc","stem":"⑥ 「좋은 길은 물어물어 찾는 거란다.」에서 「길」 자리에 넣어도 뜻이 그대로인 말은 무엇인가요?","options":[{"t":"방법","correct":true},{"t":"골목","mis":"K4-1-u4-X14"},{"t":"도중","mis":"K4-1-u4-X14"},{"t":"봉지","mis":"K4-1-u4-X14"}],"explanation":["넣어서 읽어 봐요.","좋은 방법은 물어물어","방법이에요."],"asset":{"type":"passage","lines":["① 학교가 끝나고 할머니와 빵집에 가는 길이었다.","② 골목이 좁은 길이라 우리는 나란히 걷지 못했다.","③ 빵집 문을 열자 따뜻한 김이 확 끼쳤다.","④ \"갓 구운 빵이라 아직 김이 나네.\" 주인아저씨가 웃으셨다.","⑤ 할머니는 빵과 함께 김 한 봉지도 담으셨다.","⑥ \"이 빵집을 어떻게 아셨어요?\" \"좋은 길은 물어물어 찾는 거란다.\"","⑦ 집으로 돌아오는 길에 나는 빵 봉지를 꼭 안았다."],"title":"빵집에 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#6','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C19',2,'mc','auto','「빵집에 가는 길」에 「길」이 여러 번 나온 것을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X17','K4-1-u4-X16','K4-1-u4-X07']::text[],false,'{"seq":6,"concept":"K4-1-u4-C19","difficulty":2,"kind":"mc","stem":"「빵집에 가는 길」에 「길」이 여러 번 나온 것을 바르게 말한 것은 무엇인가요?","options":[{"t":"글자는 같지만 자리마다 뜻이 다르게 쓰였다","correct":true},{"t":"한 이야기 안이라 모두 뜻이 같다","mis":"K4-1-u4-X17"},{"t":"첫 번째 뜻만 맞고 나머지는 잘못 쓴 말이다","mis":"K4-1-u4-X16"},{"t":"여러 「길」은 서로 아무 상관이 없는 낱말이다","mis":"K4-1-u4-X07"}],"explanation":["①, ②, ⑥, ⑦을 봐요.","도중 · 곳 · 방법","자리마다 달라요."],"asset":{"type":"passage","lines":["① 학교가 끝나고 할머니와 빵집에 가는 길이었다.","② 골목이 좁은 길이라 우리는 나란히 걷지 못했다.","③ 빵집 문을 열자 따뜻한 김이 확 끼쳤다.","④ \"갓 구운 빵이라 아직 김이 나네.\" 주인아저씨가 웃으셨다.","⑤ 할머니는 빵과 함께 김 한 봉지도 담으셨다.","⑥ \"이 빵집을 어떻게 아셨어요?\" \"좋은 길은 물어물어 찾는 거란다.\"","⑦ 집으로 돌아오는 길에 나는 빵 봉지를 꼭 안았다."],"title":"빵집에 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#7','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C21',2,'mc','auto','광고에 여러 가지로 해석되는 낱말을 쓰는 까닭이 아닌 것은 무엇인가요?',ARRAY['K4-1-u4-X19']::text[],false,'{"seq":7,"concept":"K4-1-u4-C21","difficulty":2,"kind":"mc","stem":"광고에 여러 가지로 해석되는 낱말을 쓰는 까닭이 아닌 것은 무엇인가요?","options":[{"t":"낱말의 뜻을 없앨 수 있어서","correct":true},{"t":"읽는 사람에게 재미와 호기심을 주어서","mis":"K4-1-u4-X19"},{"t":"짧은 말로 두 가지를 함께 전해서","mis":"K4-1-u4-X19"},{"t":"한 번 보면 오래 기억에 남아서","mis":"K4-1-u4-X19"}],"explanation":["재미 · 전달 · 기억","뜻이 없어질까요?","뜻은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#8','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C20',2,'mc','auto','「도서관 광고」에서 「길」이 전하는 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X18','K4-1-u4-X03']::text[],false,'{"seq":8,"concept":"K4-1-u4-C20","difficulty":2,"kind":"mc","stem":"「도서관 광고」에서 「길」이 전하는 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"다니는 곳이면서 앞으로 살아갈 방법이라는 뜻을 함께 전한다","correct":true},{"t":"다니는 곳이라는 뜻만 전한다","mis":"K4-1-u4-X18"},{"t":"잘못 쓴 낱말이라 뜻이 없다","mis":"K4-1-u4-X18"},{"t":"도서관 앞 골목을 넓힌다는 소식이다","mis":"K4-1-u4-X03"}],"explanation":["책을 열면 무엇이 열릴까요?","두 뜻을 함께","곳이면서 방법"],"asset":{"type":"passage","lines":["한 권을 열면","새로운 길이 열립니다","— 우리 동네 도서관"],"title":"도서관 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#9','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C17',2,'mc','auto','「화단 정리하는 날」 ④ 「색종이에 풀을 바르고」의 「풀」에 알맞은 사전의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X16','K4-1-u4-X02','K4-1-u4-X03']::text[],false,'{"seq":9,"concept":"K4-1-u4-C17","difficulty":2,"kind":"mc","stem":"「화단 정리하는 날」 ④ 「색종이에 풀을 바르고」의 「풀」에 알맞은 사전의 뜻은 무엇인가요?","options":[{"t":"풀² 종이 같은 것을 붙이는 데 쓰는 끈끈한 것","correct":true},{"t":"풀¹ 땅에서 자라는, 줄기가 연한 작은 식물","mis":"K4-1-u4-X16"},{"t":"「풀」은 뜻이 하나라 고를 필요가 없다","mis":"K4-1-u4-X02"},{"t":"뽑은 풀을 종이에 바른 것이다","mis":"K4-1-u4-X03"}],"explanation":["바르고 붙였어요.","사전의 두 뜻","풀²예요."],"asset":{"type":"passage","lines":["① 토요일에 지안이는 아빠와 화단의 풀을 뽑았다.","② 뽑은 풀은 바구니에 담아 담장 옆에 두었다.","③ 오후에는 화단에 꽂을 이름표를 만들려고 풀을 꺼냈다.","④ 색종이에 풀을 바르고 나무 막대에 붙였다.","⑤ 막대를 묶은 끈은 매듭이 단단해 아빠가 풀어 주셨다.","⑥ 일을 다 마치고 나니 마음이 가벼웠다."],"title":"화단 정리하는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_basic#10','kor',4,1,'u4','L04','g4_1_kor_u4_L04_basic','lesson_basic','K4-1-u4-C22',3,'mc','auto','여러 가지로 해석되는 낱말을 살려 지은 문구로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X13','K4-1-u4-X18','K4-1-u4-X19']::text[],false,'{"seq":10,"concept":"K4-1-u4-C22","difficulty":3,"kind":"mc","stem":"여러 가지로 해석되는 낱말을 살려 지은 문구로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「무거운 가방은 내려놓고, 무거운 마음은 함께 나누어요.」","correct":true},{"t":"「무거운 가방도 무거운 짐도 함께 들어요.」","mis":"K4-1-u4-X13"},{"t":"「가방을 바르게 메요.」","mis":"K4-1-u4-X18"},{"t":"「무겁다는 말은 쓰지 말아요.」","mis":"K4-1-u4-X19"}],"explanation":["두 뜻이 함께 있나요?","무게와 마음","첫째 문구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#1','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C14',2,'mc','auto','「화단 정리하는 날」 ①의 「풀」과 ③의 「풀」을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X03','K4-1-u4-X17']::text[],false,'{"seq":1,"concept":"K4-1-u4-C14","difficulty":2,"kind":"mc","stem":"「화단 정리하는 날」 ①의 「풀」과 ③의 「풀」을 바르게 말한 것은 무엇인가요?","options":[{"t":"①은 땅에서 자라는 식물이고, ③은 붙이는 데 쓰는 것이다","correct":true},{"t":"둘 다 땅에서 자라는 식물이다","mis":"K4-1-u4-X03"},{"t":"둘 다 붙이는 데 쓰는 것이다","mis":"K4-1-u4-X03"},{"t":"한 글 안이라 두 「풀」의 뜻은 같다","mis":"K4-1-u4-X17"}],"explanation":["뽑은 풀","이름표를 만들 풀","뜻이 달라요."],"asset":{"type":"passage","lines":["① 토요일에 지안이는 아빠와 화단의 풀을 뽑았다.","② 뽑은 풀은 바구니에 담아 담장 옆에 두었다.","③ 오후에는 화단에 꽂을 이름표를 만들려고 풀을 꺼냈다.","④ 색종이에 풀을 바르고 나무 막대에 붙였다.","⑤ 막대를 묶은 끈은 매듭이 단단해 아빠가 풀어 주셨다.","⑥ 일을 다 마치고 나니 마음이 가벼웠다."],"title":"화단 정리하는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#2','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C16',2,'mc','auto','「무거워서」의 뜻을 국어사전에서 찾을 때 찾아야 할 낱말은 무엇인가요?',ARRAY['K4-1-u4-X15']::text[],false,'{"seq":2,"concept":"K4-1-u4-C16","difficulty":2,"kind":"mc","stem":"「무거워서」의 뜻을 국어사전에서 찾을 때 찾아야 할 낱말은 무엇인가요?","options":[{"t":"무겁다","correct":true},{"t":"무거워서","mis":"K4-1-u4-X15"},{"t":"무거워","mis":"K4-1-u4-X15"},{"t":"무거","mis":"K4-1-u4-X15"}],"explanation":["기본형은?","「-다」로 끝나요.","무겁다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#3','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C18',3,'mc','auto','사전에 실린 모양을 보고 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X09','K4-1-u4-X08','K4-1-u4-X11']::text[],false,'{"seq":3,"concept":"K4-1-u4-C18","difficulty":3,"kind":"mc","stem":"사전에 실린 모양을 보고 바르게 말한 것은 무엇인가요?","options":[{"t":"「풀」은 번호를 붙여 따로 실었으니 동형이의어이고, 「가볍다」는 한 낱말 안에 이어 실었으니 다의어이다","correct":true},{"t":"「풀」은 다의어이고 「가볍다」는 동형이의어이다","mis":"K4-1-u4-X09"},{"t":"둘 다 글자가 같은 낱말이 있으니 동형이의어이다","mis":"K4-1-u4-X08"},{"t":"「가볍다」는 가볍다¹, 가볍다²로 따로 실어야 한다","mis":"K4-1-u4-X11"}],"explanation":["번호가 붙었나요?","「1」 「2」로 이었나요?","실린 모양으로 가려요."],"asset":{"type":"passage","lines":["풀¹ 땅에서 자라는, 줄기가 연한 작은 식물. 예 풀을 뽑다.","풀² 종이 같은 것을 붙이는 데 쓰는 끈끈한 것. 예 풀로 붙이다.","가볍다 「1」 무게가 적다. 「2」 마음이 홀가분하다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#4','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C17',3,'mc','auto','「화단 정리하는 날」 ⑥ 「마음이 가벼웠다」의 「가볍다」에 알맞은 사전의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X16','K4-1-u4-X03','K4-1-u4-X02']::text[],false,'{"seq":4,"concept":"K4-1-u4-C17","difficulty":3,"kind":"mc","stem":"「화단 정리하는 날」 ⑥ 「마음이 가벼웠다」의 「가볍다」에 알맞은 사전의 뜻은 무엇인가요?","options":[{"t":"「2」 마음이 홀가분하다","correct":true},{"t":"「1」 무게가 적다","mis":"K4-1-u4-X16"},{"t":"바구니에 담은 풀이 적었다는 뜻이다","mis":"K4-1-u4-X03"},{"t":"「가볍다」는 뜻이 하나뿐이다","mis":"K4-1-u4-X02"}],"explanation":["무엇이 가벼웠나요?","마음","「2」예요."],"asset":{"type":"passage","lines":["풀¹ 땅에서 자라는, 줄기가 연한 작은 식물. 예 풀을 뽑다.","풀² 종이 같은 것을 붙이는 데 쓰는 끈끈한 것. 예 풀로 붙이다.","가볍다 「1」 무게가 적다. 「2」 마음이 홀가분하다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#5','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C15',3,'mc','auto','「수학 문제를 풀다.」의 「풀다」 자리에 넣어도 뜻이 그대로인 말은 무엇인가요?',ARRAY['K4-1-u4-X14']::text[],false,'{"seq":5,"concept":"K4-1-u4-C15","difficulty":3,"kind":"mc","stem":"「수학 문제를 풀다.」의 「풀다」 자리에 넣어도 뜻이 그대로인 말은 무엇인가요?","options":[{"t":"답을 찾다","correct":true},{"t":"묶다","mis":"K4-1-u4-X14"},{"t":"자르다","mis":"K4-1-u4-X14"},{"t":"붙이다","mis":"K4-1-u4-X14"}],"explanation":["넣어서 읽어 봐요.","문제의 답을 찾다","답을 찾다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#6','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C19',3,'mc','auto','「화단 정리하는 날」을 읽은 친구의 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X17','K4-1-u4-X18','K4-1-u4-X16']::text[],false,'{"seq":6,"concept":"K4-1-u4-C19","difficulty":3,"kind":"mc","stem":"「화단 정리하는 날」을 읽은 친구의 말로 알맞은 것은 무엇인가요?","options":[{"t":"「풀이라는 낱말이 네 번 나오는데 앞의 두 번과 뒤의 두 번은 뜻이 달라.」","correct":true},{"t":"「한 글에 나왔으니 네 번 모두 같은 뜻이야.」","mis":"K4-1-u4-X17"},{"t":"「같은 낱말이 여러 번 나오면 잘못 쓴 거야.」","mis":"K4-1-u4-X18"},{"t":"「사전의 첫 번째 뜻으로만 읽으면 돼.」","mis":"K4-1-u4-X16"}],"explanation":["①②와 ③④","뽑는 풀 · 바르는 풀","뜻이 달라요."],"asset":{"type":"passage","lines":["① 토요일에 지안이는 아빠와 화단의 풀을 뽑았다.","② 뽑은 풀은 바구니에 담아 담장 옆에 두었다.","③ 오후에는 화단에 꽂을 이름표를 만들려고 풀을 꺼냈다.","④ 색종이에 풀을 바르고 나무 막대에 붙였다.","⑤ 막대를 묶은 끈은 매듭이 단단해 아빠가 풀어 주셨다.","⑥ 일을 다 마치고 나니 마음이 가벼웠다."],"title":"화단 정리하는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#7','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C21',3,'mc','auto','「도서관 광고」를 본 친구의 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X18','K4-1-u4-X03','K4-1-u4-X19']::text[],false,'{"seq":7,"concept":"K4-1-u4-C21","difficulty":3,"kind":"mc","stem":"「도서관 광고」를 본 친구의 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「책을 펴면 앞으로 나아갈 방법이 생긴다는 말이구나. 짧은데 오래 기억나.」","correct":true},{"t":"「길이라는 낱말을 잘못 써서 뜻을 알 수 없어.」","mis":"K4-1-u4-X18"},{"t":"「도서관 앞에 새 길을 낸다는 소식이야.」","mis":"K4-1-u4-X03"},{"t":"「여러 뜻 낱말을 쓰면 뜻이 없어져서 재미없어.」","mis":"K4-1-u4-X19"}],"explanation":["두 뜻을 함께 전해요.","짧고 오래 남아요.","첫째 말이에요."],"asset":{"type":"passage","lines":["한 권을 열면","새로운 길이 열립니다","— 우리 동네 도서관"],"title":"도서관 광고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#8','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C18',4,'essay','teacher','「빵집에 가는 길」에서 「김」이 쓰인 두 문장을 찾아 각각 어떤 뜻인지 쓰고, 두 「김」이 동형이의어인지 다의어인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u4-C18","difficulty":4,"kind":"essay","stem":"「빵집에 가는 길」에서 「김」이 쓰인 두 문장을 찾아 각각 어떤 뜻인지 쓰고, 두 「김」이 동형이의어인지 다의어인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「따뜻한 김이 확 끼쳤다」의 김은 뜨거운 것에서 나는 흰 기운이고, 「김 한 봉지」의 김은 바다에서 나는, 얇게 말린 먹을거리이다. 두 뜻은 서로 이어지지 않으므로 동형이의어이다. 사전에도 김¹, 김²로 따로 실려 있다.","scoring_points":["두 문장을 찾아 뜻을 썼는가","동형이의어라고 썼는가","뜻이 이어지지 않는다는 까닭을 썼는가"]},"explanation":["③과 ⑤","흰 기운 · 먹을거리","이어지나요?"],"asset":{"type":"passage","lines":["① 학교가 끝나고 할머니와 빵집에 가는 길이었다.","② 골목이 좁은 길이라 우리는 나란히 걷지 못했다.","③ 빵집 문을 열자 따뜻한 김이 확 끼쳤다.","④ \"갓 구운 빵이라 아직 김이 나네.\" 주인아저씨가 웃으셨다.","⑤ 할머니는 빵과 함께 김 한 봉지도 담으셨다.","⑥ \"이 빵집을 어떻게 아셨어요?\" \"좋은 길은 물어물어 찾는 거란다.\"","⑦ 집으로 돌아오는 길에 나는 빵 봉지를 꼭 안았다."],"title":"빵집에 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#9','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C22',4,'essay','teacher','「가볍다」나 「깊다」 가운데 하나를 골라 여러 가지 뜻이 함께 드러나는 짧은 광고 문구를 짓고, 문구에 담긴 두 가지 뜻을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u4-C22","difficulty":4,"kind":"essay","stem":"「가볍다」나 「깊다」 가운데 하나를 골라 여러 가지 뜻이 함께 드러나는 짧은 광고 문구를 짓고, 문구에 담긴 두 가지 뜻을 쓰세요.","answer_guide":{"answer":"예: 「깊은 바다처럼, 생각도 깊게!」 — 물의 밑바닥까지 멀다는 뜻과 생각이 신중하다는 뜻을 함께 전한다.","scoring_points":["한 낱말을 골라 문구를 지었는가","두 가지 뜻을 썼는가","두 뜻이 문구에 함께 드러나는가"]},"explanation":["낱말 고르기","두 뜻 담기","짧게 지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L04_challenge#10','kor',4,1,'u4','L04','g4_1_kor_u4_L04_challenge','lesson_challenge','K4-1-u4-C14',4,'essay','teacher','「화단 정리하는 날」 ⑤ 「아빠가 풀어 주셨다」에서 「풀다」의 뜻을 앞뒤 내용으로 짐작해 쓰고, 그렇게 짐작한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u4-C14","difficulty":4,"kind":"essay","stem":"「화단 정리하는 날」 ⑤ 「아빠가 풀어 주셨다」에서 「풀다」의 뜻을 앞뒤 내용으로 짐작해 쓰고, 그렇게 짐작한 까닭을 쓰세요.","answer_guide":{"answer":"예: 묶인 것을 끌러 놓는다는 뜻이다. 앞에 「막대를 묶은 끈은 매듭이 단단해」라는 말이 있어서 묶인 매듭을 끌렀다는 것을 알 수 있다.","scoring_points":["「풀다」의 뜻을 바르게 짐작했는가","앞뒤 내용에서 까닭을 찾았는가","까닭과 뜻을 이었는가"]},"explanation":["무엇을 풀었나요?","매듭이 단단해","앞뒤를 봐요."],"asset":{"type":"passage","lines":["① 토요일에 지안이는 아빠와 화단의 풀을 뽑았다.","② 뽑은 풀은 바구니에 담아 담장 옆에 두었다.","③ 오후에는 화단에 꽂을 이름표를 만들려고 풀을 꺼냈다.","④ 색종이에 풀을 바르고 나무 막대에 붙였다.","⑤ 막대를 묶은 끈은 매듭이 단단해 아빠가 풀어 주셨다.","⑥ 일을 다 마치고 나니 마음이 가벼웠다."],"title":"화단 정리하는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#1','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C25',1,'mc','auto','짝의 책상 위에 있는 공책을 가리키며 짝에게 말할 때 알맞은 말은 무엇인가요?',ARRAY['K4-1-u4-X21','K4-1-u4-X20']::text[],false,'{"seq":1,"concept":"K4-1-u4-C25","difficulty":1,"kind":"mc","stem":"짝의 책상 위에 있는 공책을 가리키며 짝에게 말할 때 알맞은 말은 무엇인가요?","options":[{"t":"그것","correct":true},{"t":"이것","mis":"K4-1-u4-X21"},{"t":"저것","mis":"K4-1-u4-X21"},{"t":"공책이라는 이름 말고는 쓸 말이 없다","mis":"K4-1-u4-X20"}],"explanation":["공책은 누구에게 가까운가요?","듣는 사람 쪽","그것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#2','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C24',1,'mc','auto','내가 들고 있는 편지를 가리키며 말할 때 알맞은 말은 무엇인가요?',ARRAY['K4-1-u4-X21','K4-1-u4-X20']::text[],false,'{"seq":2,"concept":"K4-1-u4-C24","difficulty":1,"kind":"mc","stem":"내가 들고 있는 편지를 가리키며 말할 때 알맞은 말은 무엇인가요?","options":[{"t":"이것","correct":true},{"t":"그것","mis":"K4-1-u4-X21"},{"t":"저것","mis":"K4-1-u4-X21"},{"t":"편지","mis":"K4-1-u4-X20"}],"explanation":["말하는 나에게 가까워요.","이 · 그 · 저","이것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#3','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C26',1,'mc','auto','교실 맨 뒤 게시판의 그림을 나와 짝이 함께 바라보며 가리킬 때 알맞은 말은 무엇인가요?',ARRAY['K4-1-u4-X21','K4-1-u4-X20']::text[],false,'{"seq":3,"concept":"K4-1-u4-C26","difficulty":1,"kind":"mc","stem":"교실 맨 뒤 게시판의 그림을 나와 짝이 함께 바라보며 가리킬 때 알맞은 말은 무엇인가요?","options":[{"t":"저것","correct":true},{"t":"이것","mis":"K4-1-u4-X21"},{"t":"그것","mis":"K4-1-u4-X21"},{"t":"그림","mis":"K4-1-u4-X20"}],"explanation":["둘 다에게서 멀어요.","멀리 있는 것","저것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#4','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C28',1,'match','auto','문장과 가리키는 말이 가리키는 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K4-1-u4-C28","difficulty":1,"kind":"match","stem":"문장과 가리키는 말이 가리키는 내용을 알맞게 이으세요.","pairs":[{"l":"복도에서 공을 주웠다. 그것을 선생님께 드렸다.","r":"공"},{"l":"교실 뒤에 시계가 있다. 저것은 오 분 빠르다.","r":"시계"},{"l":"내가 들고 있는 것은 쪽지야. 이것을 짝에게 전해 줘.","r":"쪽지"}],"mis":"K4-1-u4-X23","explanation":["바로 앞을 봐요.","무엇을 가리키나요?","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#5','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C23',2,'mc','auto','가리키는 말을 바르게 설명한 것은 무엇인가요?',ARRAY['K4-1-u4-X20','K4-1-u4-X22']::text[],false,'{"seq":5,"concept":"K4-1-u4-C23","difficulty":2,"kind":"mc","stem":"가리키는 말을 바르게 설명한 것은 무엇인가요?","options":[{"t":"사람 · 물건 · 장소를 집어서 가리키는 말이다","correct":true},{"t":"물건의 이름을 부르는 말이다","mis":"K4-1-u4-X20"},{"t":"바로 앞에 보이는 물건에만 쓰는 말이다","mis":"K4-1-u4-X22"},{"t":"글의 중심 생각을 알려 주는 말이다","mis":"K4-1-u4-X20"}],"explanation":["이것 · 그것 · 저것","집어서 가리켜요.","첫째 설명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#6','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C29',2,'mc','auto','「자전거가 주는 도움」에서 「이것」이 가리키는 내용은 무엇인가요?',ARRAY['K4-1-u4-X24','K4-1-u4-X23']::text[],false,'{"seq":6,"concept":"K4-1-u4-C29","difficulty":2,"kind":"mc","stem":"「자전거가 주는 도움」에서 「이것」이 가리키는 내용은 무엇인가요?","options":[{"t":"몸이 튼튼해지고 가까운 곳을 빠르게 다녀올 수 있는 것","correct":true},{"t":"몸이 튼튼해지는 것 하나","mis":"K4-1-u4-X24"},{"t":"매연이 나오지 않는 것","mis":"K4-1-u4-X23"},{"t":"자전거를 고치는 방법","mis":"K4-1-u4-X23"}],"explanation":["「이것」 바로 앞 문장들","두 가지를 함께","첫째예요."],"asset":{"type":"passage","lines":["자전거는 우리에게 여러 가지 도움을 준다.","자전거를 타면 몸이 튼튼해진다.","가까운 곳은 빠르게 다녀올 수도 있다.","자전거가 주는 도움은 이것만이 아니다.","매연이 나오지 않아 공기도 맑게 지켜 준다."],"title":"자전거가 주는 도움"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#7','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C30',2,'mc','auto','가리키는 말을 쓰면 좋은 점이 아닌 것은 무엇인가요?',ARRAY['K4-1-u4-X25']::text[],false,'{"seq":7,"concept":"K4-1-u4-C30","difficulty":2,"kind":"mc","stem":"가리키는 말을 쓰면 좋은 점이 아닌 것은 무엇인가요?","options":[{"t":"글의 내용을 바꿀 수 있다","correct":true},{"t":"앞에서 나온 말을 되풀이하지 않아도 된다","mis":"K4-1-u4-X25"},{"t":"문장을 짧고 깔끔하게 쓸 수 있다","mis":"K4-1-u4-X25"},{"t":"읽는 흐름이 매끄러워진다","mis":"K4-1-u4-X25"}],"explanation":["되풀이 · 짧고 깔끔 · 흐름","내용이 바뀔까요?","바뀌지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#8','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C28',2,'mc','auto','가리키는 말이 가리키는 내용을 찾을 때 가장 먼저 살펴볼 곳은 어디인가요?',ARRAY['K4-1-u4-X23']::text[],false,'{"seq":8,"concept":"K4-1-u4-C28","difficulty":2,"kind":"mc","stem":"가리키는 말이 가리키는 내용을 찾을 때 가장 먼저 살펴볼 곳은 어디인가요?","options":[{"t":"가리키는 말의 바로 앞 문장","correct":true},{"t":"글의 맨 마지막 문장","mis":"K4-1-u4-X23"},{"t":"글의 제목","mis":"K4-1-u4-X23"},{"t":"가리키는 말과 상관없이 마음에 드는 문장","mis":"K4-1-u4-X23"}],"explanation":["대부분 바로 앞에 있어요.","앞뒤 문장","바로 앞이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#9','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C27',2,'mc','auto','「우리 모둠 화분」 ④의 「이것」처럼 가리키는 말을 쓰는 까닭은 무엇인가요?',ARRAY['K4-1-u4-X22','K4-1-u4-X23','K4-1-u4-X20']::text[],false,'{"seq":9,"concept":"K4-1-u4-C27","difficulty":2,"kind":"mc","stem":"「우리 모둠 화분」 ④의 「이것」처럼 가리키는 말을 쓰는 까닭은 무엇인가요?","options":[{"t":"앞에서 이미 나온 내용을 다시 말하려고","correct":true},{"t":"바로 앞에 보이는 물건을 가리키려고","mis":"K4-1-u4-X22"},{"t":"새로운 이야기를 시작하려고","mis":"K4-1-u4-X23"},{"t":"서진이의 이름을 숨기려고","mis":"K4-1-u4-X20"}],"explanation":["③을 다시 읽어요.","앞 내용을 가리켜요.","다시 말하려고요."],"asset":{"type":"passage","lines":["① 교실 뒤 선반에 작은 화분이 세 개 놓여 있다.","② 화분마다 우리 모둠이 심은 강낭콩이 자란다.","③ 서진이는 날마다 화분에 물을 주고 흙을 살핀다.","④ 이것은 서진이가 스스로 맡은 일이다.","⑤ 지난주에는 떡잎 사이로 본잎이 나왔다.","⑥ 우리 모둠은 그것을 보고 다 함께 기뻐했다."],"title":"우리 모둠 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_basic#10','kor',4,1,'u4','L07','g4_1_kor_u4_L07_basic','lesson_basic','K4-1-u4-C31',3,'mc','auto','「민서는 필통에 노란 색연필을 늘 넣고 다닌다. 짝이 색을 찾지 못하자 민서는 노란 색연필을 떠올렸다.」를 가리키는 말로 바르게 고치는 방법은 무엇인가요?',ARRAY['K4-1-u4-X26','K4-1-u4-X20']::text[],false,'{"seq":10,"concept":"K4-1-u4-C31","difficulty":3,"kind":"mc","stem":"「민서는 필통에 노란 색연필을 늘 넣고 다닌다. 짝이 색을 찾지 못하자 민서는 노란 색연필을 떠올렸다.」를 가리키는 말로 바르게 고치는 방법은 무엇인가요?","options":[{"t":"둘째 문장의 「노란 색연필」을 「그것」으로 바꾼다","correct":true},{"t":"첫째 문장의 「노란 색연필」을 「그것」으로 바꾼다","mis":"K4-1-u4-X26"},{"t":"두 「노란 색연필」을 모두 「그것」으로 바꾼다","mis":"K4-1-u4-X26"},{"t":"「민서」를 「그것」으로 바꾼다","mis":"K4-1-u4-X20"}],"explanation":["처음 나온 말은 그대로","다시 나올 때 바꿔요.","둘째 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_challenge#1','kor',4,1,'u4','L07','g4_1_kor_u4_L07_challenge','lesson_challenge','K4-1-u4-C24',2,'mc','auto','채아와 지우가 나눈 말에서 지우가 첫째 □에 넣을 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X21','K4-1-u4-X20']::text[],false,'{"seq":1,"concept":"K4-1-u4-C24","difficulty":2,"kind":"mc","stem":"채아와 지우가 나눈 말에서 지우가 첫째 □에 넣을 말로 알맞은 것은 무엇인가요?","options":[{"t":"이것","correct":true},{"t":"그것","mis":"K4-1-u4-X21"},{"t":"저것","mis":"K4-1-u4-X21"},{"t":"가위","mis":"K4-1-u4-X20"}],"explanation":["가위는 지우 옆에 있어요.","말하는 지우에게 가까워요.","이것이에요."],"asset":{"type":"speech","turns":[{"who":"채아","text":"지우야, 네 옆에 있는 가위 좀 빌려줄래?"},{"who":"지우","text":"□ 말이야? 자, 여기 있어."},{"who":"채아","text":"고마워. 그리고 칠판 위에 걸린 시간표 좀 봐."},{"who":"지우","text":"□ 말이야? 오늘은 체육이 있네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
