INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_challenge#3','kor',4,1,'u4','L07','g4_1_kor_u4_L07_challenge','lesson_challenge','K4-1-u4-C28',3,'mc','auto','「우리 모둠 화분」 ⑥의 「그것」이 가리키는 내용은 무엇인가요?',ARRAY['K4-1-u4-X23','K4-1-u4-X24']::text[],false,'{"seq":3,"concept":"K4-1-u4-C28","difficulty":3,"kind":"mc","stem":"「우리 모둠 화분」 ⑥의 「그것」이 가리키는 내용은 무엇인가요?","options":[{"t":"떡잎 사이로 본잎이 나온 것","correct":true},{"t":"교실 뒤 선반","mis":"K4-1-u4-X23"},{"t":"서진이가 물을 주는 일","mis":"K4-1-u4-X23"},{"t":"본잎","mis":"K4-1-u4-X24"}],"explanation":["⑤를 다시 읽어요.","무엇을 보고 기뻐했나요?","본잎이 나온 것이에요."],"asset":{"type":"passage","lines":["① 교실 뒤 선반에 작은 화분이 세 개 놓여 있다.","② 화분마다 우리 모둠이 심은 강낭콩이 자란다.","③ 서진이는 날마다 화분에 물을 주고 흙을 살핀다.","④ 이것은 서진이가 스스로 맡은 일이다.","⑤ 지난주에는 떡잎 사이로 본잎이 나왔다.","⑥ 우리 모둠은 그것을 보고 다 함께 기뻐했다."],"title":"우리 모둠 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
