INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_challenge#5','kor',4,1,'u4','L07','g4_1_kor_u4_L07_challenge','lesson_challenge','K4-1-u4-C30',3,'mc','auto','「자전거는 매연이 나오지 않는다. 자전거는 소리도 조용하다.」의 둘째 문장을 「그것은 소리도 조용하다.」로 고쳤어요. 좋아진 점은 무엇인가요?',ARRAY['K4-1-u4-X25']::text[],false,'{"seq":5,"concept":"K4-1-u4-C30","difficulty":3,"kind":"mc","stem":"「자전거는 매연이 나오지 않는다. 자전거는 소리도 조용하다.」의 둘째 문장을 「그것은 소리도 조용하다.」로 고쳤어요. 좋아진 점은 무엇인가요?","options":[{"t":"같은 말이 되풀이되지 않아 문장이 짧고 깔끔하고 읽기 매끄럽다","correct":true},{"t":"자전거에 대한 내용이 바뀌어 새 글이 된다","mis":"K4-1-u4-X25"},{"t":"무엇을 말하는지 알 수 없게 된다","mis":"K4-1-u4-X25"},{"t":"글자 수가 늘어나 더 자세해진다","mis":"K4-1-u4-X25"}],"explanation":["되풀이가 사라졌어요.","내용은 그대로","짧고 깔끔해졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_challenge#6','kor',4,1,'u4','L07','g4_1_kor_u4_L07_challenge','lesson_challenge','K4-1-u4-C23',3,'mc','auto','가리키는 말이 쓰인 문장은 무엇인가요?',ARRAY['K4-1-u4-X20']::text[],false,'{"seq":6,"concept":"K4-1-u4-C23","difficulty":3,"kind":"mc","stem":"가리키는 말이 쓰인 문장은 무엇인가요?","options":[{"t":"저 건물이 우리 학교 도서관이야.","correct":true},{"t":"우리 학교 도서관은 넓어.","mis":"K4-1-u4-X20"},{"t":"도서관에는 책이 많아.","mis":"K4-1-u4-X20"},{"t":"나는 도서관에 가.","mis":"K4-1-u4-X20"}],"explanation":["이 · 그 · 저","집어서 가리키는 말","「저 건물」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_challenge#7','kor',4,1,'u4','L07','g4_1_kor_u4_L07_challenge','lesson_challenge','K4-1-u4-C31',3,'mc','auto','「책꽂이 맨 위에 그림책이 있다. 책꽂이 맨 위에 있는 그림책은 내가 가장 아끼는 책이다.」를 가리키는 말을 써서 바르게 고친 것은 무엇인가요?',ARRAY['K4-1-u4-X26','K4-1-u4-X23']::text[],false,'{"seq":7,"concept":"K4-1-u4-C31","difficulty":3,"kind":"mc","stem":"「책꽂이 맨 위에 그림책이 있다. 책꽂이 맨 위에 있는 그림책은 내가 가장 아끼는 책이다.」를 가리키는 말을 써서 바르게 고친 것은 무엇인가요?","options":[{"t":"책꽂이 맨 위에 그림책이 있다. 그것은 내가 가장 아끼는 책이다.","correct":true},{"t":"그것 맨 위에 그림책이 있다. 그림책은 내가 가장 아끼는 책이다.","mis":"K4-1-u4-X26"},{"t":"책꽂이 맨 위에 그것이 있다. 그것은 내가 가장 아끼는 책이다.","mis":"K4-1-u4-X26"},{"t":"책꽂이 맨 위에 그림책이 있다. 책꽂이는 내가 가장 아끼는 책이다.","mis":"K4-1-u4-X23"}],"explanation":["처음은 그대로","다시 나올 때 바꿔요.","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_challenge#8','kor',4,1,'u4','L07','g4_1_kor_u4_L07_challenge','lesson_challenge','K4-1-u4-C24',4,'essay','teacher','이것 · 그것 · 저것이 각각 어떤 것을 가리키는지 거리로 설명하고, 교실에서 쓸 수 있는 문장을 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u4-C24","difficulty":4,"kind":"essay","stem":"이것 · 그것 · 저것이 각각 어떤 것을 가리키는지 거리로 설명하고, 교실에서 쓸 수 있는 문장을 하나씩 쓰세요.","answer_guide":{"answer":"예: 이것은 말하는 사람에게 가까운 것 — 「이것은 내 필통이야.」 그것은 듣는 사람에게 가까운 것 — 「네 옆의 그것 좀 줄래?」 저것은 둘 모두에게서 멀리 있는 것 — 「저것은 교실 뒤 시계야.」","scoring_points":["세 말의 거리를 바르게 설명했는가","세 말로 문장을 만들었는가","문장의 상황이 거리에 맞는가"]},"explanation":["누구에게 가까운가요?","이 · 그 · 저","문장을 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_challenge#9','kor',4,1,'u4','L07','g4_1_kor_u4_L07_challenge','lesson_challenge','K4-1-u4-C28',4,'essay','teacher','「자전거가 주는 도움」에서 「이것」이 가리키는 내용을 쓰고, 그 내용을 어떻게 찾았는지 방법을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u4-C28","difficulty":4,"kind":"essay","stem":"「자전거가 주는 도움」에서 「이것」이 가리키는 내용을 쓰고, 그 내용을 어떻게 찾았는지 방법을 쓰세요.","answer_guide":{"answer":"예: 「이것」은 자전거를 타면 몸이 튼튼해지고 가까운 곳을 빠르게 다녀올 수 있는 것을 가리킨다. 「이것」의 바로 앞 문장들을 다시 읽어 앞에서 말한 도움 두 가지를 찾았다.","scoring_points":["가리키는 내용을 빠짐없이 썼는가","바로 앞 문장을 살폈다고 썼는가","내용과 방법을 이었는가"]},"explanation":["바로 앞","도움 두 가지","찾은 방법"],"asset":{"type":"passage","lines":["자전거는 우리에게 여러 가지 도움을 준다.","자전거를 타면 몸이 튼튼해진다.","가까운 곳은 빠르게 다녀올 수도 있다.","자전거가 주는 도움은 이것만이 아니다.","매연이 나오지 않아 공기도 맑게 지켜 준다."],"title":"자전거가 주는 도움"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L07_challenge#10','kor',4,1,'u4','L07','g4_1_kor_u4_L07_challenge','lesson_challenge','K4-1-u4-C30',4,'essay','teacher','「우리 모둠 화분」 ④에서 「이것」 대신 가리키는 내용을 그대로 다시 쓰면 문장이 어떻게 되는지 쓰고, 가리키는 말을 쓰면 좋은 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u4-C30","difficulty":4,"kind":"essay","stem":"「우리 모둠 화분」 ④에서 「이것」 대신 가리키는 내용을 그대로 다시 쓰면 문장이 어떻게 되는지 쓰고, 가리키는 말을 쓰면 좋은 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 「날마다 화분에 물을 주고 흙을 살피는 일은 서진이가 스스로 맡은 일이다.」가 되어 앞 문장의 말이 되풀이된다. 가리키는 말을 쓰면 같은 말을 되풀이하지 않아도 되고, 문장이 짧고 깔끔해져 읽는 흐름이 매끄럽다.","scoring_points":["다시 쓴 문장을 썼는가","되풀이된다는 점을 짚었는가","좋은 점 두 가지를 썼는가"]},"explanation":["그대로 다시 쓰면?","되풀이","짧고 깔끔 · 매끄러움"],"asset":{"type":"passage","lines":["① 교실 뒤 선반에 작은 화분이 세 개 놓여 있다.","② 화분마다 우리 모둠이 심은 강낭콩이 자란다.","③ 서진이는 날마다 화분에 물을 주고 흙을 살핀다.","④ 이것은 서진이가 스스로 맡은 일이다.","⑤ 지난주에는 떡잎 사이로 본잎이 나왔다.","⑥ 우리 모둠은 그것을 보고 다 함께 기뻐했다."],"title":"우리 모둠 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#1','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C32',1,'mc','auto','이야기의 중심 생각을 찾는 방법끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u4-X27','K4-1-u4-X30','K4-1-u4-X31']::text[],false,'{"seq":1,"concept":"K4-1-u4-C32","difficulty":1,"kind":"mc","stem":"이야기의 중심 생각을 찾는 방법끼리 묶은 것은 무엇인가요?","options":[{"t":"제목 보기 · 줄거리 간추리기 · 인물의 말과 행동 살피기","correct":true},{"t":"제목 보기 · 글자 수 세기 · 그림 색깔 보기","mis":"K4-1-u4-X27"},{"t":"인물의 이름 · 생김새 · 옷차림 살피기","mis":"K4-1-u4-X30"},{"t":"내 경험 떠올리기 · 상상하기 · 제목 바꾸기","mis":"K4-1-u4-X31"}],"explanation":["제목","줄거리","인물의 말과 행동"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#2','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C34',1,'mc','auto','「돌아온 도서관 책」에서 실제로 있었던 일이 아닌 것은 무엇인가요?',ARRAY['K4-1-u4-X29']::text[],false,'{"seq":2,"concept":"K4-1-u4-C34","difficulty":1,"kind":"mc","stem":"「돌아온 도서관 책」에서 실제로 있었던 일이 아닌 것은 무엇인가요?","options":[{"t":"준서가 새 책을 사서 도서관에 갚았다","correct":true},{"t":"반납하는 날 책이 없어졌다","mis":"K4-1-u4-X29"},{"t":"은우가 복도에서 주운 책을 반납대에 놓았다","mis":"K4-1-u4-X29"},{"t":"준서는 그 뒤로 빌린 책을 가방 맨 위에 넣었다","mis":"K4-1-u4-X29"}],"explanation":["이야기에 나왔나요?","새 책을 산 일은?","없던 일이에요."],"asset":{"type":"passage","lines":["① 준서는 도서관에서 빌린 그림책을 가방에 넣고 다녔다.","② 반납하는 날 아침, 가방을 아무리 뒤져도 책이 없었다.","③ \"다음 사람이 기다릴 텐데…….\" 준서는 하루 종일 마음이 무거웠다.","④ 다음 날, 도서관 선생님께서 준서를 부르셨다.","⑤ \"어제 누가 이것을 반납대에 놓고 갔단다.\"","⑥ 표지에 은우가 붙인 쪽지가 있었다. \"복도에서 주웠어. 잘 넣어 둘게!\"","⑦ 그날부터 준서는 빌린 책을 늘 가방 맨 위에 넣고 다녔다."],"title":"돌아온 도서관 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#3','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C35',1,'mc','auto','③ 「다음 사람이 기다릴 텐데…….」라는 준서의 말에서 알 수 있는 준서의 생각은 무엇인가요?',ARRAY['K4-1-u4-X03','K4-1-u4-X31']::text[],false,'{"seq":3,"concept":"K4-1-u4-C35","difficulty":1,"kind":"mc","stem":"③ 「다음 사람이 기다릴 텐데…….」라는 준서의 말에서 알 수 있는 준서의 생각은 무엇인가요?","options":[{"t":"빌린 책을 기다리는 다음 사람을 걱정한다","correct":true},{"t":"가방이 무거워 들고 다니기 힘들다","mis":"K4-1-u4-X03"},{"t":"도서관에 가기 귀찮다","mis":"K4-1-u4-X31"},{"t":"은우가 책을 숨겼다고 의심한다","mis":"K4-1-u4-X31"}],"explanation":["누구를 생각하나요?","다음 사람","걱정하는 마음이에요."],"asset":{"type":"passage","lines":["① 준서는 도서관에서 빌린 그림책을 가방에 넣고 다녔다.","② 반납하는 날 아침, 가방을 아무리 뒤져도 책이 없었다.","③ \"다음 사람이 기다릴 텐데…….\" 준서는 하루 종일 마음이 무거웠다.","④ 다음 날, 도서관 선생님께서 준서를 부르셨다.","⑤ \"어제 누가 이것을 반납대에 놓고 갔단다.\"","⑥ 표지에 은우가 붙인 쪽지가 있었다. \"복도에서 주웠어. 잘 넣어 둘게!\"","⑦ 그날부터 준서는 빌린 책을 늘 가방 맨 위에 넣고 다녔다."],"title":"돌아온 도서관 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#4','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C33',1,'mc','auto','제목 「돌아온 도서관 책」에서 짐작할 수 있는 것은 무엇인가요?',ARRAY['K4-1-u4-X28','K4-1-u4-X29']::text[],false,'{"seq":4,"concept":"K4-1-u4-C33","difficulty":1,"kind":"mc","stem":"제목 「돌아온 도서관 책」에서 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"잃어버린 책이 제자리로 돌아온 일이 이야기에서 중요하다","correct":true},{"t":"도서관 책은 모두 새 책이다","mis":"K4-1-u4-X28"},{"t":"제목은 이야기와 상관이 없다","mis":"K4-1-u4-X28"},{"t":"준서가 책을 사서 돌려주었다","mis":"K4-1-u4-X29"}],"explanation":["「돌아온」","무엇이 돌아왔나요?","중요한 일을 알려 줘요."],"asset":{"type":"passage","lines":["① 준서는 도서관에서 빌린 그림책을 가방에 넣고 다녔다.","② 반납하는 날 아침, 가방을 아무리 뒤져도 책이 없었다.","③ \"다음 사람이 기다릴 텐데…….\" 준서는 하루 종일 마음이 무거웠다.","④ 다음 날, 도서관 선생님께서 준서를 부르셨다.","⑤ \"어제 누가 이것을 반납대에 놓고 갔단다.\"","⑥ 표지에 은우가 붙인 쪽지가 있었다. \"복도에서 주웠어. 잘 넣어 둘게!\"","⑦ 그날부터 준서는 빌린 책을 늘 가방 맨 위에 넣고 다녔다."],"title":"돌아온 도서관 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#5','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C36',2,'mc','auto','「돌아온 도서관 책」의 중심 생각을 바르게 고른 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X27','K4-1-u4-X28','K4-1-u4-X31']::text[],false,'{"seq":5,"concept":"K4-1-u4-C36","difficulty":2,"kind":"mc","stem":"「돌아온 도서관 책」의 중심 생각을 바르게 고른 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"제목, 줄거리, 인물의 말과 행동이 모두 같은 생각을 가리켜서","correct":true},{"t":"은우의 말 한마디에 나와 있어서","mis":"K4-1-u4-X27"},{"t":"제목에 그대로 쓰여 있어서","mis":"K4-1-u4-X28"},{"t":"내가 겪은 일과 비슷해서","mis":"K4-1-u4-X31"}],"explanation":["하나만 보았나요?","모두 모아요.","첫째예요."],"asset":{"type":"passage","lines":["① 준서는 도서관에서 빌린 그림책을 가방에 넣고 다녔다.","② 반납하는 날 아침, 가방을 아무리 뒤져도 책이 없었다.","③ \"다음 사람이 기다릴 텐데…….\" 준서는 하루 종일 마음이 무거웠다.","④ 다음 날, 도서관 선생님께서 준서를 부르셨다.","⑤ \"어제 누가 이것을 반납대에 놓고 갔단다.\"","⑥ 표지에 은우가 붙인 쪽지가 있었다. \"복도에서 주웠어. 잘 넣어 둘게!\"","⑦ 그날부터 준서는 빌린 책을 늘 가방 맨 위에 넣고 다녔다."],"title":"돌아온 도서관 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#6','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C38',2,'mc','auto','「돌아온 도서관 책」의 중심 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X32','K4-1-u4-X33']::text[],false,'{"seq":6,"concept":"K4-1-u4-C38","difficulty":2,"kind":"mc","stem":"「돌아온 도서관 책」의 중심 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"여럿이 함께 쓰는 물건은 아끼고 소중히 다루자","correct":true},{"t":"준서가 책을 잃어버렸다가 은우 덕분에 되찾았다","mis":"K4-1-u4-X32"},{"t":"복도에서는 뛰지 말자","mis":"K4-1-u4-X33"},{"t":"가방은 가볍게 들고 다니자","mis":"K4-1-u4-X33"}],"explanation":["있었던 일 말고","그 일로 전하려는 생각","함께 쓰는 물건"],"asset":{"type":"passage","lines":["① 준서는 도서관에서 빌린 그림책을 가방에 넣고 다녔다.","② 반납하는 날 아침, 가방을 아무리 뒤져도 책이 없었다.","③ \"다음 사람이 기다릴 텐데…….\" 준서는 하루 종일 마음이 무거웠다.","④ 다음 날, 도서관 선생님께서 준서를 부르셨다.","⑤ \"어제 누가 이것을 반납대에 놓고 갔단다.\"","⑥ 표지에 은우가 붙인 쪽지가 있었다. \"복도에서 주웠어. 잘 넣어 둘게!\"","⑦ 그날부터 준서는 빌린 책을 늘 가방 맨 위에 넣고 다녔다."],"title":"돌아온 도서관 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#7','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C37',2,'mc','auto','중심 생각을 정할 때 알맞은 태도는 무엇인가요?',ARRAY['K4-1-u4-X31','K4-1-u4-X27']::text[],false,'{"seq":7,"concept":"K4-1-u4-C37","difficulty":2,"kind":"mc","stem":"중심 생각을 정할 때 알맞은 태도는 무엇인가요?","options":[{"t":"글에 나온 내용을 근거로 짐작한다","correct":true},{"t":"글에 없어도 내 경험으로 정한다","mis":"K4-1-u4-X31"},{"t":"가장 짧은 문장 하나를 고른다","mis":"K4-1-u4-X27"},{"t":"마음에 드는 인물의 말만 본다","mis":"K4-1-u4-X27"}],"explanation":["어디에 근거하나요?","글 안의 내용","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#8','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C39',2,'mc','auto','「둘이 그린 하늘」의 중심 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X33','K4-1-u4-X32','K4-1-u4-X04']::text[],false,'{"seq":8,"concept":"K4-1-u4-C39","difficulty":2,"kind":"mc","stem":"「둘이 그린 하늘」의 중심 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"서로 다른 생각을 모으면 더 좋은 것을 만들 수 있다","correct":true},{"t":"하늘은 파랗게 그려야 한다","mis":"K4-1-u4-X33"},{"t":"윤호와 채아가 하늘을 함께 그렸다","mis":"K4-1-u4-X32"},{"t":"노을은 아름답다","mis":"K4-1-u4-X04"}],"explanation":["작은 장면 하나로 정하지 않아요.","윤호의 마지막 말","생각을 모으면"],"asset":{"type":"passage","lines":["① 미술 시간에 윤호와 채아는 커다란 종이에 하늘을 함께 그리게 되었다.","② 윤호는 파란 하늘만 그리자고 했고, 채아는 노을 하늘을 그리고 싶었다.","③ 둘은 한참 동안 붓을 들지 못했다.","④ 채아가 말했다. \"왼쪽은 파란 하늘, 오른쪽은 노을 하늘로 하면 어때?\"","⑤ 윤호가 고개를 끄덕이며 가운데를 두 색이 섞이도록 칠했다.","⑥ 다 그린 그림을 본 친구들은 하루가 다 담긴 하늘이라며 감탄했다.","⑦ 윤호는 \"혼자 그렸으면 이런 하늘은 못 그렸을 거야.\"라고 말했다."],"title":"둘이 그린 하늘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#9','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C40',2,'mc','auto','찾은 중심 생각을 정리하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X34','K4-1-u4-X30','K4-1-u4-X33']::text[],false,'{"seq":9,"concept":"K4-1-u4-C40","difficulty":2,"kind":"mc","stem":"찾은 중심 생각을 정리하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"제목 · 줄거리 · 인물의 말을 떠올려 내 말로 한 문장으로 쓴다","correct":true},{"t":"이야기를 처음부터 끝까지 그대로 옮겨 쓴다","mis":"K4-1-u4-X34"},{"t":"인물의 이름만 쓴다","mis":"K4-1-u4-X30"},{"t":"가장 재미있는 장면 하나를 그대로 옮긴다","mis":"K4-1-u4-X33"}],"explanation":["길게 옮기지 않아요.","내 말로","한 문장으로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_basic#10','kor',4,1,'u4','L08','g4_1_kor_u4_L08_basic','lesson_basic','K4-1-u4-C41',3,'mc','auto','「학급 문고」와 「돌아온 도서관 책」을 견준 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X35','K4-1-u4-X29','K4-1-u4-X42']::text[],false,'{"seq":10,"concept":"K4-1-u4-C41","difficulty":3,"kind":"mc","stem":"「학급 문고」와 「돌아온 도서관 책」을 견준 말로 알맞은 것은 무엇인가요?","options":[{"t":"다루는 이야기는 달라도 함께 쓰는 물건을 소중히 하자는 생각이 같다","correct":true},{"t":"학급 문고와 도서관은 다른 곳이니 생각도 다르다","mis":"K4-1-u4-X35"},{"t":"두 글 모두 책을 잃어버린 이야기이다","mis":"K4-1-u4-X29"},{"t":"「학급 문고」에는 인물이 없어 중심 생각이 없다","mis":"K4-1-u4-X42"}],"explanation":["다루는 것은 달라요.","전하려는 생각은?","같은 생각이에요."],"asset":{"type":"passage","lines":["학급 문고의 책은 우리 반 모두의 책이다.","한 사람이 접어 두면 다음 사람이 접힌 쪽을 본다.","읽은 자리에 그대로 꽂아 두면 다음 사람이 쉽게 찾는다."],"title":"학급 문고"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_challenge#1','kor',4,1,'u4','L08','g4_1_kor_u4_L08_challenge','lesson_challenge','K4-1-u4-C34',2,'mc','auto','「둘이 그린 하늘」의 줄거리를 알맞게 간추린 것은 무엇인가요?',ARRAY['K4-1-u4-X29']::text[],false,'{"seq":1,"concept":"K4-1-u4-C34","difficulty":2,"kind":"mc","stem":"「둘이 그린 하늘」의 줄거리를 알맞게 간추린 것은 무엇인가요?","options":[{"t":"하늘 그림을 두고 생각이 달랐던 윤호와 채아가 두 하늘을 한 종이에 담아 함께 완성했다","correct":true},{"t":"선생님이 둘의 다툼을 말려 주셨다","mis":"K4-1-u4-X29"},{"t":"종이를 받고, 붓을 들고, 고개를 끄덕이고, 색을 칠한 일을 하나도 빼지 않고 늘어놓는다","mis":"K4-1-u4-X29"},{"t":"채아가 혼자 그림을 다 그렸다","mis":"K4-1-u4-X29"}],"explanation":["주요 장면만","있었던 일만","첫째예요."],"asset":{"type":"passage","lines":["① 미술 시간에 윤호와 채아는 커다란 종이에 하늘을 함께 그리게 되었다.","② 윤호는 파란 하늘만 그리자고 했고, 채아는 노을 하늘을 그리고 싶었다.","③ 둘은 한참 동안 붓을 들지 못했다.","④ 채아가 말했다. \"왼쪽은 파란 하늘, 오른쪽은 노을 하늘로 하면 어때?\"","⑤ 윤호가 고개를 끄덕이며 가운데를 두 색이 섞이도록 칠했다.","⑥ 다 그린 그림을 본 친구들은 하루가 다 담긴 하늘이라며 감탄했다.","⑦ 윤호는 \"혼자 그렸으면 이런 하늘은 못 그렸을 거야.\"라고 말했다."],"title":"둘이 그린 하늘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
