INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_challenge#4','kor',4,1,'u4','L08','g4_1_kor_u4_L08_challenge','lesson_challenge','K4-1-u4-C36',3,'mc','auto','「둘이 그린 하늘」의 중심 생각을 찾은 과정으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X27','K4-1-u4-X33','K4-1-u4-X31']::text[],false,'{"seq":4,"concept":"K4-1-u4-C36","difficulty":3,"kind":"mc","stem":"「둘이 그린 하늘」의 중심 생각을 찾은 과정으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"제목의 「둘이」, 두 하늘을 함께 담은 줄거리, 윤호의 마지막 말을 모아 정했다","correct":true},{"t":"②만 읽고 「생각이 다르면 다툰다」로 정했다","mis":"K4-1-u4-X27"},{"t":"친구들의 감탄 한 문장만 보고 「그림은 크게 그려야 한다」로 정했다","mis":"K4-1-u4-X33"},{"t":"내가 다툰 일을 떠올려 「친구와 놀지 말자」로 정했다","mis":"K4-1-u4-X31"}],"explanation":["하나만 보지 않아요.","제목 · 줄거리 · 말","모두 모아요."],"asset":{"type":"passage","lines":["① 미술 시간에 윤호와 채아는 커다란 종이에 하늘을 함께 그리게 되었다.","② 윤호는 파란 하늘만 그리자고 했고, 채아는 노을 하늘을 그리고 싶었다.","③ 둘은 한참 동안 붓을 들지 못했다.","④ 채아가 말했다. \"왼쪽은 파란 하늘, 오른쪽은 노을 하늘로 하면 어때?\"","⑤ 윤호가 고개를 끄덕이며 가운데를 두 색이 섞이도록 칠했다.","⑥ 다 그린 그림을 본 친구들은 하루가 다 담긴 하늘이라며 감탄했다.","⑦ 윤호는 \"혼자 그렸으면 이런 하늘은 못 그렸을 거야.\"라고 말했다."],"title":"둘이 그린 하늘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_challenge#5','kor',4,1,'u4','L08','g4_1_kor_u4_L08_challenge','lesson_challenge','K4-1-u4-C38',3,'mc','auto','친구가 「둘이 그린 하늘」의 중심 생각을 「윤호와 채아가 하늘을 그렸다.」라고 했어요. 알맞게 고쳐 준 말은 무엇인가요?',ARRAY['K4-1-u4-X32','K4-1-u4-X30','K4-1-u4-X34']::text[],false,'{"seq":5,"concept":"K4-1-u4-C38","difficulty":3,"kind":"mc","stem":"친구가 「둘이 그린 하늘」의 중심 생각을 「윤호와 채아가 하늘을 그렸다.」라고 했어요. 알맞게 고쳐 준 말은 무엇인가요?","options":[{"t":"「그건 있었던 일이야. 그 일로 전하려는 생각을 찾아야 해.」","correct":true},{"t":"「맞아. 있었던 일이 곧 중심 생각이야.」","mis":"K4-1-u4-X32"},{"t":"「인물 이름이 빠지면 안 되니 이름을 더 넣어.」","mis":"K4-1-u4-X30"},{"t":"「처음부터 끝까지 다 옮겨 써야 해.」","mis":"K4-1-u4-X34"}],"explanation":["있었던 일","전하려는 생각","둘은 달라요."],"asset":{"type":"passage","lines":["① 미술 시간에 윤호와 채아는 커다란 종이에 하늘을 함께 그리게 되었다.","② 윤호는 파란 하늘만 그리자고 했고, 채아는 노을 하늘을 그리고 싶었다.","③ 둘은 한참 동안 붓을 들지 못했다.","④ 채아가 말했다. \"왼쪽은 파란 하늘, 오른쪽은 노을 하늘로 하면 어때?\"","⑤ 윤호가 고개를 끄덕이며 가운데를 두 색이 섞이도록 칠했다.","⑥ 다 그린 그림을 본 친구들은 하루가 다 담긴 하늘이라며 감탄했다.","⑦ 윤호는 \"혼자 그렸으면 이런 하늘은 못 그렸을 거야.\"라고 말했다."],"title":"둘이 그린 하늘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_challenge#6','kor',4,1,'u4','L08','g4_1_kor_u4_L08_challenge','lesson_challenge','K4-1-u4-C37',3,'mc','auto','「둘이 그린 하늘」의 중심 생각을 말한 친구 가운데 글에 근거한 말은 무엇인가요?',ARRAY['K4-1-u4-X31','K4-1-u4-X33']::text[],false,'{"seq":6,"concept":"K4-1-u4-C37","difficulty":3,"kind":"mc","stem":"「둘이 그린 하늘」의 중심 생각을 말한 친구 가운데 글에 근거한 말은 무엇인가요?","options":[{"t":"서진 — 「윤호가 혼자였으면 못 그렸을 거라고 했으니, 생각을 모으면 더 좋아진다는 거야.」","correct":true},{"t":"지우 — 「나도 동생과 그림을 그렸으니 가족끼리 사이좋게 지내자는 거야.」","mis":"K4-1-u4-X31"},{"t":"지안 — 「노을이 예쁘니 해 질 무렵에 산책하자는 거야.」","mis":"K4-1-u4-X31"},{"t":"민서 — 「붓을 오래 못 들었으니 미술 시간에는 서두르자는 거야.」","mis":"K4-1-u4-X33"}],"explanation":["글에 나온 말인가요?","윤호의 마지막 말","서진이에요."],"asset":{"type":"passage","lines":["① 미술 시간에 윤호와 채아는 커다란 종이에 하늘을 함께 그리게 되었다.","② 윤호는 파란 하늘만 그리자고 했고, 채아는 노을 하늘을 그리고 싶었다.","③ 둘은 한참 동안 붓을 들지 못했다.","④ 채아가 말했다. \"왼쪽은 파란 하늘, 오른쪽은 노을 하늘로 하면 어때?\"","⑤ 윤호가 고개를 끄덕이며 가운데를 두 색이 섞이도록 칠했다.","⑥ 다 그린 그림을 본 친구들은 하루가 다 담긴 하늘이라며 감탄했다.","⑦ 윤호는 \"혼자 그렸으면 이런 하늘은 못 그렸을 거야.\"라고 말했다."],"title":"둘이 그린 하늘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_challenge#7','kor',4,1,'u4','L08','g4_1_kor_u4_L08_challenge','lesson_challenge','K4-1-u4-C41',3,'mc','auto','「둘이 그린 하늘」과 같은 중심 생각을 담은 글로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X35','K4-1-u4-X31']::text[],false,'{"seq":7,"concept":"K4-1-u4-C41","difficulty":3,"kind":"mc","stem":"「둘이 그린 하늘」과 같은 중심 생각을 담은 글로 알맞은 것은 무엇인가요?","options":[{"t":"모둠 친구들이 서로 다른 생각을 모아 더 멋진 발표를 했다는 글","correct":true},{"t":"하늘의 색깔이 왜 바뀌는지 알려 주는 글","mis":"K4-1-u4-X35"},{"t":"혼자 연습해 그림 대회에서 상을 받았다는 글","mis":"K4-1-u4-X31"},{"t":"그림 그리는 붓을 고르는 방법을 알려 주는 글","mis":"K4-1-u4-X35"}],"explanation":["소재가 같아야 할까요?","생각을 모으면","모둠 발표 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_challenge#8','kor',4,1,'u4','L08','g4_1_kor_u4_L08_challenge','lesson_challenge','K4-1-u4-C36',4,'essay','teacher','「돌아온 도서관 책」의 중심 생각을 쓰고, 제목 · 줄거리 · 인물의 말과 행동에서 근거를 하나씩 들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u4-C36","difficulty":4,"kind":"essay","stem":"「돌아온 도서관 책」의 중심 생각을 쓰고, 제목 · 줄거리 · 인물의 말과 행동에서 근거를 하나씩 들어 쓰세요.","answer_guide":{"answer":"예: 중심 생각은 「여럿이 함께 쓰는 물건은 소중히 다루자.」이다. 제목 「돌아온 도서관 책」은 잃어버린 책이 제자리로 돌아온 일을 중요하게 여긴다. 줄거리는 잃어버린 책을 은우가 주워 반납하고 준서가 그 뒤로 책을 조심해서 다닌 이야기이다. 준서는 「다음 사람이 기다릴 텐데」라고 말하며 다음 사람을 걱정했다.","scoring_points":["중심 생각을 바르게 썼는가","제목 · 줄거리 · 인물의 말과 행동에서 근거를 들었는가","근거가 글에 나온 내용인가"]},"explanation":["제목","줄거리","인물의 말과 행동"],"asset":{"type":"passage","lines":["① 준서는 도서관에서 빌린 그림책을 가방에 넣고 다녔다.","② 반납하는 날 아침, 가방을 아무리 뒤져도 책이 없었다.","③ \"다음 사람이 기다릴 텐데…….\" 준서는 하루 종일 마음이 무거웠다.","④ 다음 날, 도서관 선생님께서 준서를 부르셨다.","⑤ \"어제 누가 이것을 반납대에 놓고 갔단다.\"","⑥ 표지에 은우가 붙인 쪽지가 있었다. \"복도에서 주웠어. 잘 넣어 둘게!\"","⑦ 그날부터 준서는 빌린 책을 늘 가방 맨 위에 넣고 다녔다."],"title":"돌아온 도서관 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_challenge#9','kor',4,1,'u4','L08','g4_1_kor_u4_L08_challenge','lesson_challenge','K4-1-u4-C39',4,'essay','teacher','친구가 「둘이 그린 하늘」 ③만 보고 중심 생각을 「미술 시간에는 서두르자.」라고 했어요. 이 생각이 알맞지 않은 까닭을 쓰고, 바른 중심 생각을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u4-C39","difficulty":4,"kind":"essay","stem":"친구가 「둘이 그린 하늘」 ③만 보고 중심 생각을 「미술 시간에는 서두르자.」라고 했어요. 이 생각이 알맞지 않은 까닭을 쓰고, 바른 중심 생각을 쓰세요.","answer_guide":{"answer":"예: ③은 이야기의 한 장면일 뿐이고, 제목과 줄거리, 윤호의 마지막 말은 서두르자는 내용과 이어지지 않는다. 바른 중심 생각은 「서로 다른 생각을 모으면 더 좋은 것을 만들 수 있다.」이다.","scoring_points":["한 장면만 보았다는 점을 짚었는가","제목 · 줄거리 · 인물의 말과 견주었는가","바른 중심 생각을 썼는가"]},"explanation":["한 장면만","모두 모아요.","바른 생각"],"asset":{"type":"passage","lines":["① 미술 시간에 윤호와 채아는 커다란 종이에 하늘을 함께 그리게 되었다.","② 윤호는 파란 하늘만 그리자고 했고, 채아는 노을 하늘을 그리고 싶었다.","③ 둘은 한참 동안 붓을 들지 못했다.","④ 채아가 말했다. \"왼쪽은 파란 하늘, 오른쪽은 노을 하늘로 하면 어때?\"","⑤ 윤호가 고개를 끄덕이며 가운데를 두 색이 섞이도록 칠했다.","⑥ 다 그린 그림을 본 친구들은 하루가 다 담긴 하늘이라며 감탄했다.","⑦ 윤호는 \"혼자 그렸으면 이런 하늘은 못 그렸을 거야.\"라고 말했다."],"title":"둘이 그린 하늘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L08_challenge#10','kor',4,1,'u4','L08','g4_1_kor_u4_L08_challenge','lesson_challenge','K4-1-u4-C40',4,'essay','teacher','「둘이 그린 하늘」의 중심 생각을 내 말로 한 문장으로 쓰고, 이 생각을 내 생활에서 어떻게 살릴 수 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u4-C40","difficulty":4,"kind":"essay","stem":"「둘이 그린 하늘」의 중심 생각을 내 말로 한 문장으로 쓰고, 이 생각을 내 생활에서 어떻게 살릴 수 있는지 쓰세요.","answer_guide":{"answer":"예: 서로 다른 생각을 모으면 혼자일 때보다 더 좋은 것을 만들 수 있다. 모둠 활동에서 친구와 의견이 다르면 한쪽을 고집하지 않고 두 생각을 함께 살릴 방법을 찾겠다.","scoring_points":["중심 생각을 한 문장으로 썼는가","내 말로 썼는가","생활에서 살릴 방법을 썼는가"]},"explanation":["한 문장","내 말로","생활 속으로"],"asset":{"type":"passage","lines":["① 미술 시간에 윤호와 채아는 커다란 종이에 하늘을 함께 그리게 되었다.","② 윤호는 파란 하늘만 그리자고 했고, 채아는 노을 하늘을 그리고 싶었다.","③ 둘은 한참 동안 붓을 들지 못했다.","④ 채아가 말했다. \"왼쪽은 파란 하늘, 오른쪽은 노을 하늘로 하면 어때?\"","⑤ 윤호가 고개를 끄덕이며 가운데를 두 색이 섞이도록 칠했다.","⑥ 다 그린 그림을 본 친구들은 하루가 다 담긴 하늘이라며 감탄했다.","⑦ 윤호는 \"혼자 그렸으면 이런 하늘은 못 그렸을 거야.\"라고 말했다."],"title":"둘이 그린 하늘"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#1','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C43',1,'mc','auto','「걸어서 학교에 가요」에서 중요한 낱말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X36']::text[],false,'{"seq":1,"concept":"K4-1-u4-C43","difficulty":1,"kind":"mc","stem":"「걸어서 학교에 가요」에서 중요한 낱말로 알맞은 것은 무엇인가요?","options":[{"t":"걷기","correct":true},{"t":"준비물","mis":"K4-1-u4-X36"},{"t":"정거장","mis":"K4-1-u4-X36"},{"t":"매연","mis":"K4-1-u4-X36"}],"explanation":["제목에도 있고","글에도 여러 번","걷기예요."],"asset":{"type":"passage","lines":["㉮ 아침마다 자동차를 타고 학교에 오는 친구가 많아요. 걸어서 학교에 가면 어떤 점이 좋을까요?","㉯ 첫째, 걸으면 몸이 튼튼해져요. 걷기는 누구나 할 수 있는 운동이에요.","그것은 따로 준비물도 필요 없어요.","㉰ 둘째, 학교 앞이 안전해져요. 등굣길에 자동차가 줄면 길을 건너기가 편해져요.","㉱ 셋째, 공기가 맑아져요. 자동차의 매연이 줄어 우리가 마시는 공기가 깨끗해져요.","㉲ 걸어서 학교에 가 보세요. 몸도 튼튼해지고, 학교 앞도 안전해지고, 공기도 맑아져요.","내일 아침에는 한 정거장 먼저 내려 걸어 보아요."],"title":"걸어서 학교에 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#2','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C44',1,'match','auto','「걸어서 학교에 가요」의 문단과 중심 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-1-u4-C44","difficulty":1,"kind":"match","stem":"「걸어서 학교에 가요」의 문단과 중심 내용을 알맞게 이으세요.","pairs":[{"l":"㉯ 문단","r":"몸이 튼튼해진다"},{"l":"㉰ 문단","r":"학교 앞이 안전해진다"},{"l":"㉱ 문단","r":"공기가 맑아진다"}],"mis":"K4-1-u4-X37","explanation":["문단의 첫 문장","첫째 · 둘째 · 셋째","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#3','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C47',1,'mc','auto','「걸어서 학교에 가요」에서 글쓴이의 생각이 가장 잘 드러난 문단은 무엇인가요?',ARRAY['K4-1-u4-X40']::text[],false,'{"seq":3,"concept":"K4-1-u4-C47","difficulty":1,"kind":"mc","stem":"「걸어서 학교에 가요」에서 글쓴이의 생각이 가장 잘 드러난 문단은 무엇인가요?","options":[{"t":"㉲","correct":true},{"t":"㉯","mis":"K4-1-u4-X40"},{"t":"㉰","mis":"K4-1-u4-X40"},{"t":"㉱","mis":"K4-1-u4-X40"}],"explanation":["첫 문단과 마지막 문단","「가 보세요」","㉲예요."],"asset":{"type":"passage","lines":["㉮ 아침마다 자동차를 타고 학교에 오는 친구가 많아요. 걸어서 학교에 가면 어떤 점이 좋을까요?","㉯ 첫째, 걸으면 몸이 튼튼해져요. 걷기는 누구나 할 수 있는 운동이에요.","그것은 따로 준비물도 필요 없어요.","㉰ 둘째, 학교 앞이 안전해져요. 등굣길에 자동차가 줄면 길을 건너기가 편해져요.","㉱ 셋째, 공기가 맑아져요. 자동차의 매연이 줄어 우리가 마시는 공기가 깨끗해져요.","㉲ 걸어서 학교에 가 보세요. 몸도 튼튼해지고, 학교 앞도 안전해지고, 공기도 맑아져요.","내일 아침에는 한 정거장 먼저 내려 걸어 보아요."],"title":"걸어서 학교에 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#4','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C48',1,'mc','auto','「걸어서 학교에 가요」의 중심 생각은 무엇인가요?',ARRAY['K4-1-u4-X41','K4-1-u4-X31']::text[],false,'{"seq":4,"concept":"K4-1-u4-C48","difficulty":1,"kind":"mc","stem":"「걸어서 학교에 가요」의 중심 생각은 무엇인가요?","options":[{"t":"걸어서 학교에 가자","correct":true},{"t":"걸으면 몸이 튼튼해진다","mis":"K4-1-u4-X41"},{"t":"자동차에서 매연이 나온다","mis":"K4-1-u4-X41"},{"t":"아침마다 달리기를 하자","mis":"K4-1-u4-X31"}],"explanation":["까닭 셋이 받쳐 주는 생각","마지막 문단","걸어서 가자"],"asset":{"type":"passage","lines":["㉮ 아침마다 자동차를 타고 학교에 오는 친구가 많아요. 걸어서 학교에 가면 어떤 점이 좋을까요?","㉯ 첫째, 걸으면 몸이 튼튼해져요. 걷기는 누구나 할 수 있는 운동이에요.","그것은 따로 준비물도 필요 없어요.","㉰ 둘째, 학교 앞이 안전해져요. 등굣길에 자동차가 줄면 길을 건너기가 편해져요.","㉱ 셋째, 공기가 맑아져요. 자동차의 매연이 줄어 우리가 마시는 공기가 깨끗해져요.","㉲ 걸어서 학교에 가 보세요. 몸도 튼튼해지고, 학교 앞도 안전해지고, 공기도 맑아져요.","내일 아침에는 한 정거장 먼저 내려 걸어 보아요."],"title":"걸어서 학교에 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#5','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C45',2,'mc','auto','중심 문장과 뒷받침 문장을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X38','K4-1-u4-X37']::text[],false,'{"seq":5,"concept":"K4-1-u4-C45","difficulty":2,"kind":"mc","stem":"중심 문장과 뒷받침 문장을 바르게 말한 것은 무엇인가요?","options":[{"t":"중심 문장은 문단에서 하고 싶은 말이고, 뒷받침 문장은 그것을 받쳐 주는 말이다","correct":true},{"t":"뒷받침 문장이 문단에서 하고 싶은 말이다","mis":"K4-1-u4-X38"},{"t":"중심 문장과 뒷받침 문장은 하는 일이 같다","mis":"K4-1-u4-X38"},{"t":"한 문단에는 중심 문장이 여러 개 있다","mis":"K4-1-u4-X37"}],"explanation":["하고 싶은 말","받쳐 주는 말","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#6','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C43',2,'mc','auto','「책상 서랍을 정리해요」에서 중요한 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u4-X36']::text[],false,'{"seq":6,"concept":"K4-1-u4-C43","difficulty":2,"kind":"mc","stem":"「책상 서랍을 정리해요」에서 중요한 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"서랍 · 정리","correct":true},{"t":"공부 · 집중","mis":"K4-1-u4-X36"},{"t":"오 분 · 쉬는 시간","mis":"K4-1-u4-X36"},{"t":"뒤죽박죽 · 차분","mis":"K4-1-u4-X36"}],"explanation":["제목에 있나요?","여러 번 나오나요?","서랍 · 정리"],"asset":{"type":"passage","lines":["㉮ 책상 서랍 속이 뒤죽박죽인 친구가 많아요. 서랍을 정리하면 어떤 점이 좋을까요?","㉯ 첫째, 물건을 빨리 찾을 수 있어요. 자리를 정해 두면 찾느라 시간을 쓰지 않아요.","㉰ 둘째, 물건을 잃어버리지 않아요. 서랍이 깔끔하면 없어진 물건이 바로 보여요.","㉱ 셋째, 공부에 집중할 수 있어요. 책상 둘레가 깨끗하면 마음도 차분해져요.","㉲ 오늘부터 책상 서랍을 정리해 보세요. 쉬는 시간 오 분이면 충분해요."],"title":"책상 서랍을 정리해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#7','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C46',2,'mc','auto','「텃밭 소식」처럼 중심 문장이 따로 없는 문단에서 중심 내용을 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X39','K4-1-u4-X37','K4-1-u4-X36']::text[],false,'{"seq":7,"concept":"K4-1-u4-C46","difficulty":2,"kind":"mc","stem":"「텃밭 소식」처럼 중심 문장이 따로 없는 문단에서 중심 내용을 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"문장들의 내용을 모아 「텃밭의 채소가 잘 자란다」처럼 정리한다","correct":true},{"t":"중심 문장이 없으니 중심 내용도 찾을 수 없다","mis":"K4-1-u4-X39"},{"t":"첫 문장 「상추가 잎을 넓게 펼쳤다」를 그대로 중심 내용으로 쓴다","mis":"K4-1-u4-X37"},{"t":"가장 긴 낱말을 중심 내용으로 쓴다","mis":"K4-1-u4-X36"}],"explanation":["한 문장으로 쓰여 있지 않아요.","모아서 정리해요.","첫째예요."],"asset":{"type":"passage","lines":["우리 반 텃밭에서는 상추가 잎을 넓게 펼쳤다.","고추에는 하얀 꽃이 피었다.","방울토마토는 벌써 빨갛게 익었다."],"title":"텃밭 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#8','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C42',2,'mc','auto','주장하는 글의 중심 생각을 찾는 방법이 아닌 것은 무엇인가요?',ARRAY['K4-1-u4-X43']::text[],false,'{"seq":8,"concept":"K4-1-u4-C42","difficulty":2,"kind":"mc","stem":"주장하는 글의 중심 생각을 찾는 방법이 아닌 것은 무엇인가요?","options":[{"t":"글에 실린 그림의 색깔을 살핀다","correct":true},{"t":"제목과 글에서 중요한 낱말을 찾는다","mis":"K4-1-u4-X43"},{"t":"문단별 중심 내용을 정리한다","mis":"K4-1-u4-X43"},{"t":"글쓴이의 생각이 드러난 부분을 찾는다","mis":"K4-1-u4-X43"}],"explanation":["낱말 · 문단 · 생각","그림 색깔은?","방법이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#9','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C44',2,'mc','auto','「책상 서랍을 정리해요」의 ㉰ 문단의 중심 내용은 무엇인가요?',ARRAY['K4-1-u4-X37']::text[],false,'{"seq":9,"concept":"K4-1-u4-C44","difficulty":2,"kind":"mc","stem":"「책상 서랍을 정리해요」의 ㉰ 문단의 중심 내용은 무엇인가요?","options":[{"t":"서랍을 정리하면 물건을 잃어버리지 않는다","correct":true},{"t":"서랍이 깔끔하면 마음이 차분해진다","mis":"K4-1-u4-X37"},{"t":"물건을 빨리 찾을 수 있다","mis":"K4-1-u4-X37"},{"t":"㉰에는 중심 내용이 셋 있다","mis":"K4-1-u4-X37"}],"explanation":["㉰의 첫 문장","둘째 까닭","잃어버리지 않아요."],"asset":{"type":"passage","lines":["㉮ 책상 서랍 속이 뒤죽박죽인 친구가 많아요. 서랍을 정리하면 어떤 점이 좋을까요?","㉯ 첫째, 물건을 빨리 찾을 수 있어요. 자리를 정해 두면 찾느라 시간을 쓰지 않아요.","㉰ 둘째, 물건을 잃어버리지 않아요. 서랍이 깔끔하면 없어진 물건이 바로 보여요.","㉱ 셋째, 공부에 집중할 수 있어요. 책상 둘레가 깨끗하면 마음도 차분해져요.","㉲ 오늘부터 책상 서랍을 정리해 보세요. 쉬는 시간 오 분이면 충분해요."],"title":"책상 서랍을 정리해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_basic#10','kor',4,1,'u4','L10','g4_1_kor_u4_L10_basic','lesson_basic','K4-1-u4-C49',3,'mc','auto','이야기와 주장하는 글의 중심 생각을 찾는 방법을 견준 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X42']::text[],false,'{"seq":10,"concept":"K4-1-u4-C49","difficulty":3,"kind":"mc","stem":"이야기와 주장하는 글의 중심 생각을 찾는 방법을 견준 말로 알맞은 것은 무엇인가요?","options":[{"t":"이야기는 제목 · 줄거리 · 인물의 말과 행동을, 주장하는 글은 목적 · 중요한 낱말 · 문단 중심 내용을 살핀다","correct":true},{"t":"두 글 모두 인물의 말과 행동만 살피면 된다","mis":"K4-1-u4-X42"},{"t":"주장하는 글에는 중심 생각이 없다","mis":"K4-1-u4-X42"},{"t":"이야기는 문단 중심 내용만 살피면 된다","mis":"K4-1-u4-X42"}],"explanation":["글의 종류에 따라","살피는 자리가 달라요.","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#1','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C47',2,'mc','auto','「책상 서랍을 정리해요」에서 글쓴이의 생각이 잘 드러난 문단끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u4-X40']::text[],false,'{"seq":1,"concept":"K4-1-u4-C47","difficulty":2,"kind":"mc","stem":"「책상 서랍을 정리해요」에서 글쓴이의 생각이 잘 드러난 문단끼리 묶은 것은 무엇인가요?","options":[{"t":"㉮와 ㉲","correct":true},{"t":"㉯와 ㉰","mis":"K4-1-u4-X40"},{"t":"㉰와 ㉱","mis":"K4-1-u4-X40"},{"t":"㉱ 하나","mis":"K4-1-u4-X40"}],"explanation":["첫 문단과 마지막 문단","물음과 권유","㉮와 ㉲예요."],"asset":{"type":"passage","lines":["㉮ 책상 서랍 속이 뒤죽박죽인 친구가 많아요. 서랍을 정리하면 어떤 점이 좋을까요?","㉯ 첫째, 물건을 빨리 찾을 수 있어요. 자리를 정해 두면 찾느라 시간을 쓰지 않아요.","㉰ 둘째, 물건을 잃어버리지 않아요. 서랍이 깔끔하면 없어진 물건이 바로 보여요.","㉱ 셋째, 공부에 집중할 수 있어요. 책상 둘레가 깨끗하면 마음도 차분해져요.","㉲ 오늘부터 책상 서랍을 정리해 보세요. 쉬는 시간 오 분이면 충분해요."],"title":"책상 서랍을 정리해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#2','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C50',2,'mc','auto','「걸어서 학교에 가요」를 읽고 정한 실천으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X44']::text[],false,'{"seq":2,"concept":"K4-1-u4-C50","difficulty":2,"kind":"mc","stem":"「걸어서 학교에 가요」를 읽고 정한 실천으로 알맞은 것은 무엇인가요?","options":[{"t":"가까운 거리는 걸어서 다니겠다","correct":true},{"t":"자동차를 타고 더 빨리 등교하겠다","mis":"K4-1-u4-X44"},{"t":"쉬는 시간에 공기놀이를 하겠다","mis":"K4-1-u4-X44"},{"t":"글에 나온 낱말을 모두 외우겠다","mis":"K4-1-u4-X44"}],"explanation":["중심 생각에서 나온 다짐","걸어서","첫째예요."],"asset":{"type":"passage","lines":["㉮ 아침마다 자동차를 타고 학교에 오는 친구가 많아요. 걸어서 학교에 가면 어떤 점이 좋을까요?","㉯ 첫째, 걸으면 몸이 튼튼해져요. 걷기는 누구나 할 수 있는 운동이에요.","그것은 따로 준비물도 필요 없어요.","㉰ 둘째, 학교 앞이 안전해져요. 등굣길에 자동차가 줄면 길을 건너기가 편해져요.","㉱ 셋째, 공기가 맑아져요. 자동차의 매연이 줄어 우리가 마시는 공기가 깨끗해져요.","㉲ 걸어서 학교에 가 보세요. 몸도 튼튼해지고, 학교 앞도 안전해지고, 공기도 맑아져요.","내일 아침에는 한 정거장 먼저 내려 걸어 보아요."],"title":"걸어서 학교에 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#3','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C48',3,'mc','auto','「책상 서랍을 정리해요」의 중심 생각과 그것을 받쳐 주는 까닭을 바르게 나눈 것은 무엇인가요?',ARRAY['K4-1-u4-X41','K4-1-u4-X46']::text[],false,'{"seq":3,"concept":"K4-1-u4-C48","difficulty":3,"kind":"mc","stem":"「책상 서랍을 정리해요」의 중심 생각과 그것을 받쳐 주는 까닭을 바르게 나눈 것은 무엇인가요?","options":[{"t":"중심 생각 — 책상 서랍을 정리하자 / 까닭 — 빨리 찾음 · 잃어버리지 않음 · 집중","correct":true},{"t":"중심 생각 — 물건을 빨리 찾을 수 있다 / 까닭 — 서랍을 정리하자","mis":"K4-1-u4-X41"},{"t":"중심 생각 — 공부에 집중하자 / 까닭 — 서랍을 정리하자","mis":"K4-1-u4-X41"},{"t":"중심 생각 — 쉬는 시간은 오 분이다 / 까닭 — 서랍","mis":"K4-1-u4-X46"}],"explanation":["받쳐 주는 것은?","첫째 · 둘째 · 셋째","정리하자가 중심이에요."],"asset":{"type":"passage","lines":["㉮ 책상 서랍 속이 뒤죽박죽인 친구가 많아요. 서랍을 정리하면 어떤 점이 좋을까요?","㉯ 첫째, 물건을 빨리 찾을 수 있어요. 자리를 정해 두면 찾느라 시간을 쓰지 않아요.","㉰ 둘째, 물건을 잃어버리지 않아요. 서랍이 깔끔하면 없어진 물건이 바로 보여요.","㉱ 셋째, 공부에 집중할 수 있어요. 책상 둘레가 깨끗하면 마음도 차분해져요.","㉲ 오늘부터 책상 서랍을 정리해 보세요. 쉬는 시간 오 분이면 충분해요."],"title":"책상 서랍을 정리해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#4','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C45',3,'mc','auto','「책상 서랍을 정리해요」 ㉯에서 뒷받침 문장은 무엇인가요?',ARRAY['K4-1-u4-X38','K4-1-u4-X37']::text[],false,'{"seq":4,"concept":"K4-1-u4-C45","difficulty":3,"kind":"mc","stem":"「책상 서랍을 정리해요」 ㉯에서 뒷받침 문장은 무엇인가요?","options":[{"t":"자리를 정해 두면 찾느라 시간을 쓰지 않아요.","correct":true},{"t":"첫째, 물건을 빨리 찾을 수 있어요.","mis":"K4-1-u4-X38"},{"t":"두 문장 모두 중심 문장이다","mis":"K4-1-u4-X37"},{"t":"㉯에는 뒷받침 문장이 없다","mis":"K4-1-u4-X38"}],"explanation":["하고 싶은 말은 첫 문장","받쳐 주는 말은?","둘째 문장이에요."],"asset":{"type":"passage","lines":["㉮ 책상 서랍 속이 뒤죽박죽인 친구가 많아요. 서랍을 정리하면 어떤 점이 좋을까요?","㉯ 첫째, 물건을 빨리 찾을 수 있어요. 자리를 정해 두면 찾느라 시간을 쓰지 않아요.","㉰ 둘째, 물건을 잃어버리지 않아요. 서랍이 깔끔하면 없어진 물건이 바로 보여요.","㉱ 셋째, 공부에 집중할 수 있어요. 책상 둘레가 깨끗하면 마음도 차분해져요.","㉲ 오늘부터 책상 서랍을 정리해 보세요. 쉬는 시간 오 분이면 충분해요."],"title":"책상 서랍을 정리해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#5','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C46',3,'mc','auto','중심 생각을 찾는 친구의 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X39','K4-1-u4-X40']::text[],false,'{"seq":5,"concept":"K4-1-u4-C46","difficulty":3,"kind":"mc","stem":"중심 생각을 찾는 친구의 말로 알맞은 것은 무엇인가요?","options":[{"t":"「글에 「~하자」라는 문장이 없어도 문단 내용을 모으면 중심 생각을 정할 수 있어.」","correct":true},{"t":"「중심 생각은 언제나 한 문장으로 쓰여 있으니 그 문장만 찾으면 돼.」","mis":"K4-1-u4-X39"},{"t":"「그런 문장이 없으면 중심 생각이 없는 글이야.」","mis":"K4-1-u4-X39"},{"t":"「가운데 문단 하나만 읽으면 돼.」","mis":"K4-1-u4-X40"}],"explanation":["늘 쓰여 있을까요?","모아서 정리","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#6','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C43',3,'mc','auto','중요한 낱말을 고르는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X36']::text[],false,'{"seq":6,"concept":"K4-1-u4-C43","difficulty":3,"kind":"mc","stem":"중요한 낱말을 고르는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"제목에 있고 글에 여러 번 나오는 낱말","correct":true},{"t":"한 번만 나왔지만 처음 보는 어려운 낱말","mis":"K4-1-u4-X36"},{"t":"글에서 가장 긴 낱말","mis":"K4-1-u4-X36"},{"t":"글의 맨 마지막 낱말","mis":"K4-1-u4-X36"}],"explanation":["제목","여러 번","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#7','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C49',3,'mc','auto','「돌아온 도서관 책」과 「걸어서 학교에 가요」의 중심 생각을 찾을 때 꼭 살필 것을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u4-X42','K4-1-u4-X43']::text[],false,'{"seq":7,"concept":"K4-1-u4-C49","difficulty":3,"kind":"mc","stem":"「돌아온 도서관 책」과 「걸어서 학교에 가요」의 중심 생각을 찾을 때 꼭 살필 것을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"「돌아온 도서관 책」 — 인물의 말과 행동 / 「걸어서 학교에 가요」 — 문단별 중심 내용","correct":true},{"t":"「돌아온 도서관 책」 — 첫째 · 둘째 · 셋째 까닭 / 「걸어서 학교에 가요」 — 인물의 행동","mis":"K4-1-u4-X42"},{"t":"둘 다 인물의 말과 행동만 본다","mis":"K4-1-u4-X42"},{"t":"둘 다 그림만 본다","mis":"K4-1-u4-X43"}],"explanation":["이야기","주장하는 글","살필 자리가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#8','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C44',4,'essay','teacher','「책상 서랍을 정리해요」의 ㉯ · ㉰ · ㉱ 문단의 중심 내용을 한 줄씩 쓰고, 이를 모아 글 전체의 중심 생각을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u4-C44","difficulty":4,"kind":"essay","stem":"「책상 서랍을 정리해요」의 ㉯ · ㉰ · ㉱ 문단의 중심 내용을 한 줄씩 쓰고, 이를 모아 글 전체의 중심 생각을 쓰세요.","answer_guide":{"answer":"예: ㉯ — 서랍을 정리하면 물건을 빨리 찾을 수 있다. ㉰ — 물건을 잃어버리지 않는다. ㉱ — 공부에 집중할 수 있다. 이 세 가지 까닭을 모으면 글 전체의 중심 생각은 「책상 서랍을 정리하자.」이다.","scoring_points":["㉯ · ㉰ · ㉱의 중심 내용을 썼는가","문단마다 하나씩 썼는가","모아서 중심 생각을 썼는가"]},"explanation":["문단마다 하나","까닭 셋","모아서"],"asset":{"type":"passage","lines":["㉮ 책상 서랍 속이 뒤죽박죽인 친구가 많아요. 서랍을 정리하면 어떤 점이 좋을까요?","㉯ 첫째, 물건을 빨리 찾을 수 있어요. 자리를 정해 두면 찾느라 시간을 쓰지 않아요.","㉰ 둘째, 물건을 잃어버리지 않아요. 서랍이 깔끔하면 없어진 물건이 바로 보여요.","㉱ 셋째, 공부에 집중할 수 있어요. 책상 둘레가 깨끗하면 마음도 차분해져요.","㉲ 오늘부터 책상 서랍을 정리해 보세요. 쉬는 시간 오 분이면 충분해요."],"title":"책상 서랍을 정리해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#9','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C48',4,'essay','teacher','친구가 「걸어서 학교에 가요」의 중심 생각을 「걸으면 몸이 튼튼해진다.」라고 했어요. 알맞지 않은 까닭과 바른 중심 생각을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u4-C48","difficulty":4,"kind":"essay","stem":"친구가 「걸어서 학교에 가요」의 중심 생각을 「걸으면 몸이 튼튼해진다.」라고 했어요. 알맞지 않은 까닭과 바른 중심 생각을 쓰세요.","answer_guide":{"answer":"예: 「걸으면 몸이 튼튼해진다」는 ㉯ 문단의 중심 내용으로, 중심 생각을 받쳐 주는 까닭 가운데 하나일 뿐이다. 세 까닭이 함께 받쳐 주고 ㉲ 문단에서 다시 말한 「걸어서 학교에 가자.」가 바른 중심 생각이다.","scoring_points":["까닭 하나라는 점을 짚었는가","세 까닭이 받쳐 준다고 썼는가","바른 중심 생각을 썼는가"]},"explanation":["까닭 하나","세 까닭을 모으면","바른 중심 생각"],"asset":{"type":"passage","lines":["㉮ 아침마다 자동차를 타고 학교에 오는 친구가 많아요. 걸어서 학교에 가면 어떤 점이 좋을까요?","㉯ 첫째, 걸으면 몸이 튼튼해져요. 걷기는 누구나 할 수 있는 운동이에요.","그것은 따로 준비물도 필요 없어요.","㉰ 둘째, 학교 앞이 안전해져요. 등굣길에 자동차가 줄면 길을 건너기가 편해져요.","㉱ 셋째, 공기가 맑아져요. 자동차의 매연이 줄어 우리가 마시는 공기가 깨끗해져요.","㉲ 걸어서 학교에 가 보세요. 몸도 튼튼해지고, 학교 앞도 안전해지고, 공기도 맑아져요.","내일 아침에는 한 정거장 먼저 내려 걸어 보아요."],"title":"걸어서 학교에 가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L10_challenge#10','kor',4,1,'u4','L10','g4_1_kor_u4_L10_challenge','lesson_challenge','K4-1-u4-C50',4,'essay','teacher','「책상 서랍을 정리해요」의 중심 생각을 쓰고, 이 글을 읽고 내가 실천할 일을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u4-C50","difficulty":4,"kind":"essay","stem":"「책상 서랍을 정리해요」의 중심 생각을 쓰고, 이 글을 읽고 내가 실천할 일을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 중심 생각 — 책상 서랍을 정리하자. 실천 — 금요일마다 쉬는 시간에 서랍 속 물건을 제자리에 정리하겠다.","scoring_points":["중심 생각을 바르게 썼는가","중심 생각에서 나온 실천을 썼는가","한 문장으로 또렷하게 썼는가"]},"explanation":["중심 생각","내 실천","한 문장"],"asset":{"type":"passage","lines":["㉮ 책상 서랍 속이 뒤죽박죽인 친구가 많아요. 서랍을 정리하면 어떤 점이 좋을까요?","㉯ 첫째, 물건을 빨리 찾을 수 있어요. 자리를 정해 두면 찾느라 시간을 쓰지 않아요.","㉰ 둘째, 물건을 잃어버리지 않아요. 서랍이 깔끔하면 없어진 물건이 바로 보여요.","㉱ 셋째, 공부에 집중할 수 있어요. 책상 둘레가 깨끗하면 마음도 차분해져요.","㉲ 오늘부터 책상 서랍을 정리해 보세요. 쉬는 시간 오 분이면 충분해요."],"title":"책상 서랍을 정리해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#1','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C51',1,'mc','auto','「벽에 그림을 ○○.」, 「친구에게 전화를 ○○.」 두 빈칸에 함께 들어갈 낱말은 무엇인가요?',ARRAY['K4-1-u4-X45']::text[],false,'{"seq":1,"concept":"K4-1-u4-C51","difficulty":1,"kind":"mc","stem":"「벽에 그림을 ○○.」, 「친구에게 전화를 ○○.」 두 빈칸에 함께 들어갈 낱말은 무엇인가요?","options":[{"t":"걸다","correct":true},{"t":"붙이다","mis":"K4-1-u4-X45"},{"t":"하다","mis":"K4-1-u4-X45"},{"t":"그리다","mis":"K4-1-u4-X45"}],"explanation":["두 문장에 모두 넣어 봐요.","그림을 걸다 · 전화를 걸다","걸다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#2','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C53',1,'mc','auto','된소리로 소리 나는 낱말은 무엇인가요?',ARRAY['K4-1-u4-X48']::text[],false,'{"seq":2,"concept":"K4-1-u4-C53","difficulty":1,"kind":"mc","stem":"된소리로 소리 나는 낱말은 무엇인가요?","options":[{"t":"국자","correct":true},{"t":"노래","mis":"K4-1-u4-X48"},{"t":"오리","mis":"K4-1-u4-X48"},{"t":"하늘","mis":"K4-1-u4-X48"}],"explanation":["소리 내어 읽어요.","[국짜]","국자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#3','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C54',1,'match','auto','뜻이 같아 함께 쓸 수 있는 바른 말끼리 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-1-u4-C54","difficulty":1,"kind":"match","stem":"뜻이 같아 함께 쓸 수 있는 바른 말끼리 이으세요.","pairs":[{"l":"넝쿨","r":"덩굴"},{"l":"소고기","r":"쇠고기"},{"l":"만날","r":"맨날"}],"mis":"K4-1-u4-X50","explanation":["둘 다 바른 말이에요.","소리가 비슷한 짝","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#4','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C52',1,'mc','auto','「학교 앞에 그늘막이 생겼어요」에서 중요한 낱말은 무엇인가요?',ARRAY['K4-1-u4-X46']::text[],false,'{"seq":4,"concept":"K4-1-u4-C52","difficulty":1,"kind":"mc","stem":"「학교 앞에 그늘막이 생겼어요」에서 중요한 낱말은 무엇인가요?","options":[{"t":"그늘막","correct":true},{"t":"지난주","mis":"K4-1-u4-X46"},{"t":"한별초등학교","mis":"K4-1-u4-X46"},{"t":"차례","mis":"K4-1-u4-X46"}],"explanation":["제목에도 있고","본문에도 여러 번","그늘막이에요."],"asset":{"type":"passage","lines":["① 지난주 한별초등학교 앞 횡단보도에 그늘막이 세워졌다.","② 한여름 낮에는 신호를 기다리는 동안 햇볕이 뜨거워 힘들다는 의견이 많았다.","③ 그늘막 아래 온도는 볕이 드는 곳보다 훨씬 낮게 나타났다.","④ 학교에서는 그늘막 안에서 차례를 지켜 기다려 달라고 안내했다."],"title":"학교 앞에 그늘막이 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#5','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C51',2,'mc','auto','낱말 알아맞히기 놀이에서 「○○가 내린다.」, 「○○로 마당을 쓴다.」의 답과 두 낱말의 관계를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X09','K4-1-u4-X45','K4-1-u4-X08']::text[],false,'{"seq":5,"concept":"K4-1-u4-C51","difficulty":2,"kind":"mc","stem":"낱말 알아맞히기 놀이에서 「○○가 내린다.」, 「○○로 마당을 쓴다.」의 답과 두 낱말의 관계를 바르게 말한 것은 무엇인가요?","options":[{"t":"「비」 — 뜻이 이어지지 않으니 동형이의어","correct":true},{"t":"「비」 — 뜻이 이어지니 다의어","mis":"K4-1-u4-X09"},{"t":"「물」 — 동형이의어","mis":"K4-1-u4-X45"},{"t":"「비」 — 글자가 같으니 늘 같은 낱말","mis":"K4-1-u4-X08"}],"explanation":["하늘에서 내리는 비","마당을 쓰는 비","동형이의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#6','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C52',2,'mc','auto','「도서실에 계단 의자가 생겼어요」가 전하려는 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X46','K4-1-u4-X31']::text[],false,'{"seq":6,"concept":"K4-1-u4-C52","difficulty":2,"kind":"mc","stem":"「도서실에 계단 의자가 생겼어요」가 전하려는 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"도서실에 앉을 자리가 늘어 책을 읽으러 오는 학생이 많아졌다","correct":true},{"t":"계단 의자는 나무로 만들었다","mis":"K4-1-u4-X46"},{"t":"기사가 나온 것은 이번 주이다","mis":"K4-1-u4-X46"},{"t":"도서실은 쉬는 시간에만 연다","mis":"K4-1-u4-X31"}],"explanation":["작은 사실 말고","전하려는 생각","첫째예요."],"asset":{"type":"passage","lines":["① 이번 주 은빛초등학교 도서실 한쪽에 나무 계단 의자가 놓였다.","② 그동안 쉬는 시간마다 앉을 자리가 부족하다는 의견이 많았다.","③ 계단 의자가 생긴 뒤 도서실을 찾는 학생이 두 배로 늘었다.","④ 도서실 선생님은 계단에서 뛰지 말고 차례로 앉아 달라고 당부했다."],"title":"도서실에 계단 의자가 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#7','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C53',2,'mc','auto','「학교」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X47','K4-1-u4-X48']::text[],false,'{"seq":7,"concept":"K4-1-u4-C53","difficulty":2,"kind":"mc","stem":"「학교」를 바르게 말한 것은 무엇인가요?","options":[{"t":"소리는 [학꾜]로 나지만 적을 때는 「학교」로 적는다","correct":true},{"t":"소리 나는 대로 「학꾜」로 적는다","mis":"K4-1-u4-X47"},{"t":"된소리로 소리 나지 않는다","mis":"K4-1-u4-X48"},{"t":"[학교]로만 소리 낸다","mis":"K4-1-u4-X48"}],"explanation":["읽을 때는 [학꾜]","적을 때는?","원래대로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#8','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C54',2,'mc','auto','바른 말이 아닌 것은 무엇인가요?',ARRAY['K4-1-u4-X50']::text[],false,'{"seq":8,"concept":"K4-1-u4-C54","difficulty":2,"kind":"mc","stem":"바른 말이 아닌 것은 무엇인가요?","options":[{"t":"설겆이","correct":true},{"t":"짜장면","mis":"K4-1-u4-X50"},{"t":"삐지다","mis":"K4-1-u4-X50"},{"t":"오손도손","mis":"K4-1-u4-X50"}],"explanation":["함께 쓰는 바른 말이 있어요.","설거지가 바른 말","설겆이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#9','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C55',2,'mc','auto','「뜻을 파악하며 읽어요」를 마치며 한 말로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u4-X01']::text[],false,'{"seq":9,"concept":"K4-1-u4-C55","difficulty":2,"kind":"mc","stem":"「뜻을 파악하며 읽어요」를 마치며 한 말로 알맞지 않은 것은 무엇인가요?","options":[{"t":"「낱말의 뜻은 하나뿐이니 사전은 필요 없어.」","correct":true},{"t":"「앞뒤 문장을 보면 낱말 뜻을 가려낼 수 있어.」","mis":"K4-1-u4-X01"},{"t":"「제목 · 줄거리 · 인물의 말로 중심 생각을 찾아.」","mis":"K4-1-u4-X01"},{"t":"「주장하는 글은 문단 중심 내용을 모아 중심 생각을 정해.」","mis":"K4-1-u4-X01"}],"explanation":["배운 것을 떠올려요.","낱말 뜻은 여러 가지","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_basic#10','kor',4,1,'u4','L12','g4_1_kor_u4_L12_basic','lesson_basic','K4-1-u4-C52',3,'mc','auto','「도서실에 계단 의자가 생겼어요」의 문단별 중심 내용을 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u4-X37','K4-1-u4-X46']::text[],false,'{"seq":10,"concept":"K4-1-u4-C52","difficulty":3,"kind":"mc","stem":"「도서실에 계단 의자가 생겼어요」의 문단별 중심 내용을 바르게 정리한 것은 무엇인가요?","options":[{"t":"① 계단 의자가 놓임 → ② 앉을 자리가 부족했음 → ③ 찾는 학생이 늘어남 → ④ 바르게 쓰자는 당부","correct":true},{"t":"① 계단 의자가 놓였다는 내용 하나뿐이다","mis":"K4-1-u4-X37"},{"t":"③의 「두 배」라는 숫자 하나만 중요하다","mis":"K4-1-u4-X46"},{"t":"④ 「뛰지 말자」가 기사 전체의 중심 생각이다","mis":"K4-1-u4-X46"}],"explanation":["문단마다 하나","①~④","첫째예요."],"asset":{"type":"passage","lines":["① 이번 주 은빛초등학교 도서실 한쪽에 나무 계단 의자가 놓였다.","② 그동안 쉬는 시간마다 앉을 자리가 부족하다는 의견이 많았다.","③ 계단 의자가 생긴 뒤 도서실을 찾는 학생이 두 배로 늘었다.","④ 도서실 선생님은 계단에서 뛰지 말고 차례로 앉아 달라고 당부했다."],"title":"도서실에 계단 의자가 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#1','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C53',2,'mc','auto','된소리로 소리 나는 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K4-1-u4-X48','K4-1-u4-X47']::text[],false,'{"seq":1,"concept":"K4-1-u4-C53","difficulty":2,"kind":"mc","stem":"된소리로 소리 나는 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"접시 · 숙제 · 박수","correct":true},{"t":"나비 · 오리 · 하늘","mis":"K4-1-u4-X48"},{"t":"접시 · 노래 · 바구니","mis":"K4-1-u4-X48"},{"t":"[접씨]로 소리 나니 「접씨」로 적는다","mis":"K4-1-u4-X47"}],"explanation":["[접씨] · [숙쩨] · [박쑤]","받침 뒤 소리","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#2','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C51',2,'mc','auto','빈칸 문제를 낸 친구 가운데 놀이 방법에 맞게 낸 친구는 누구인가요?',ARRAY['K4-1-u4-X13','K4-1-u4-X45','K4-1-u4-X08']::text[],false,'{"seq":2,"concept":"K4-1-u4-C51","difficulty":2,"kind":"mc","stem":"빈칸 문제를 낸 친구 가운데 놀이 방법에 맞게 낸 친구는 누구인가요?","options":[{"t":"지안 — 「물이 ○○. / 생각이 ○○.」 답은 「깊다」이고, 뜻이 이어지니 다의어야.","correct":true},{"t":"서진 — 「물이 ○○. / 강물이 ○○.」 답은 「깊다」야.","mis":"K4-1-u4-X13"},{"t":"윤호 — 「풀을 ○○. / 문제를 ○○.」 답은 「뽑다」야.","mis":"K4-1-u4-X45"},{"t":"채아 — 「물이 ○○. / 생각이 ○○.」 답은 「깊다」이고, 글자가 같으니 동형이의어야.","mis":"K4-1-u4-X08"}],"explanation":["두 빈칸 모두","뜻이 달라야","관계도 바르게"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#3','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C52',3,'mc','auto','「도서실에 계단 의자가 생겼어요」의 중요한 낱말을 바르게 고른 것은 무엇인가요?',ARRAY['K4-1-u4-X46','K4-1-u4-X36']::text[],false,'{"seq":3,"concept":"K4-1-u4-C52","difficulty":3,"kind":"mc","stem":"「도서실에 계단 의자가 생겼어요」의 중요한 낱말을 바르게 고른 것은 무엇인가요?","options":[{"t":"도서실 · 계단 의자","correct":true},{"t":"이번 주 · 두 배","mis":"K4-1-u4-X46"},{"t":"선생님 · 당부","mis":"K4-1-u4-X46"},{"t":"나무 · 한쪽","mis":"K4-1-u4-X36"}],"explanation":["제목에 있나요?","여러 번 나오나요?","도서실 · 계단 의자"],"asset":{"type":"passage","lines":["① 이번 주 은빛초등학교 도서실 한쪽에 나무 계단 의자가 놓였다.","② 그동안 쉬는 시간마다 앉을 자리가 부족하다는 의견이 많았다.","③ 계단 의자가 생긴 뒤 도서실을 찾는 학생이 두 배로 늘었다.","④ 도서실 선생님은 계단에서 뛰지 말고 차례로 앉아 달라고 당부했다."],"title":"도서실에 계단 의자가 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#4','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C54',3,'mc','auto','함께 쓰는 바른 말에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X50','K4-1-u4-X49']::text[],false,'{"seq":4,"concept":"K4-1-u4-C54","difficulty":3,"kind":"mc","stem":"함께 쓰는 바른 말에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"「여쭈다」와 「여쭙다」는 둘 다 바른 말이다","correct":true},{"t":"「짜장면」은 틀리고 「자장면」만 바르다","mis":"K4-1-u4-X50"},{"t":"소리가 비슷하니 「설겆이」도 바른 말이다","mis":"K4-1-u4-X49"},{"t":"「덩굴」은 틀리고 「넝쿨」만 바르다","mis":"K4-1-u4-X50"}],"explanation":["둘 다 바른 짝","소리만 비슷한 말","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#5','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C53',3,'mc','auto','「걷기」와 「옷장」을 소리 내어 읽은 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X48','K4-1-u4-X47']::text[],false,'{"seq":5,"concept":"K4-1-u4-C53","difficulty":3,"kind":"mc","stem":"「걷기」와 「옷장」을 소리 내어 읽은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"[걷끼], [옫짱]","correct":true},{"t":"[걷기], [옷장]","mis":"K4-1-u4-X48"},{"t":"「걷끼」, 「옫짱」으로 적는다","mis":"K4-1-u4-X47"},{"t":"[걷기], [옫짱]","mis":"K4-1-u4-X48"}],"explanation":["받침 뒤 소리","된소리로","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#6','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C52',3,'mc','auto','「도서실에 계단 의자가 생겼어요」를 읽은 친구의 말 가운데 기사가 전하려는 생각을 잘 파악한 말은 무엇인가요?',ARRAY['K4-1-u4-X46','K4-1-u4-X31']::text[],false,'{"seq":6,"concept":"K4-1-u4-C52","difficulty":3,"kind":"mc","stem":"「도서실에 계단 의자가 생겼어요」를 읽은 친구의 말 가운데 기사가 전하려는 생각을 잘 파악한 말은 무엇인가요?","options":[{"t":"「자리가 부족했던 도서실에 계단 의자가 생겨 책 읽는 학생이 늘었다는 거구나.」","correct":true},{"t":"「계단 의자가 나무라는 게 가장 중요해.」","mis":"K4-1-u4-X46"},{"t":"「학생이 두 배로 늘었다는 숫자만 기억하면 돼.」","mis":"K4-1-u4-X46"},{"t":"「계단이 생겼으니 체육 시간에 쓰자는 거야.」","mis":"K4-1-u4-X31"}],"explanation":["작은 사실 말고","모아서","첫째예요."],"asset":{"type":"passage","lines":["① 이번 주 은빛초등학교 도서실 한쪽에 나무 계단 의자가 놓였다.","② 그동안 쉬는 시간마다 앉을 자리가 부족하다는 의견이 많았다.","③ 계단 의자가 생긴 뒤 도서실을 찾는 학생이 두 배로 늘었다.","④ 도서실 선생님은 계단에서 뛰지 말고 차례로 앉아 달라고 당부했다."],"title":"도서실에 계단 의자가 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#7','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C55',3,'mc','auto','이 단원에서 배운 것을 생활에 쓴 예로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-1-u4-X01']::text[],false,'{"seq":7,"concept":"K4-1-u4-C55","difficulty":3,"kind":"mc","stem":"이 단원에서 배운 것을 생활에 쓴 예로 알맞지 않은 것은 무엇인가요?","options":[{"t":"광고 문구의 낱말은 모두 한 가지 뜻으로만 읽는다","correct":true},{"t":"헷갈리는 낱말을 만나면 사전에서 기본형으로 찾는다","mis":"K4-1-u4-X01"},{"t":"신문 기사에서 중요한 낱말을 찾아 중심 생각을 말한다","mis":"K4-1-u4-X01"},{"t":"여러 가지로 해석되는 낱말로 짧은 시를 짓는다","mis":"K4-1-u4-X01"}],"explanation":["배운 것을 떠올려요.","광고 속 낱말은 두 뜻","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#8','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C51',4,'essay','teacher','「따뜻하다」로 빈칸 문제 두 문장을 만들고, 두 뜻이 동형이의어인지 다의어인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u4-C51","difficulty":4,"kind":"essay","stem":"「따뜻하다」로 빈칸 문제 두 문장을 만들고, 두 뜻이 동형이의어인지 다의어인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「○○ 물로 세수를 한다.」 / 「친구의 마음이 ○○.」 답은 「따뜻하다」이다. 온도가 알맞게 높다는 뜻이 남을 아끼는 마음이라는 뜻으로 넓어져 이어져 있으므로 다의어이다.","scoring_points":["빈칸 문장 두 개를 만들었는가","동형이의어인지 다의어인지 썼는가","뜻의 이어짐으로 까닭을 썼는가"]},"explanation":["두 문장","두 뜻","이어졌나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#9','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C52',4,'essay','teacher','「학교 앞에 그늘막이 생겼어요」의 중요한 낱말 두 개와 문단별 중심 내용을 정리하고, 기사가 전하려는 생각을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u4-C52","difficulty":4,"kind":"essay","stem":"「학교 앞에 그늘막이 생겼어요」의 중요한 낱말 두 개와 문단별 중심 내용을 정리하고, 기사가 전하려는 생각을 쓰세요.","answer_guide":{"answer":"예: 중요한 낱말 — 그늘막, 횡단보도. 문단별 중심 내용 — 학교 앞에 그늘막이 세워졌다 · 기다리는 동안 햇볕이 뜨거웠다 · 그늘막 아래는 온도가 낮았다 · 차례를 지켜 기다려 달라고 했다. 기사가 전하려는 생각 — 더위를 피해 안전하게 신호를 기다리자.","scoring_points":["중요한 낱말 두 개를 썼는가","문단별 중심 내용을 정리했는가","기사가 전하려는 생각을 썼는가"]},"explanation":["중요한 낱말","문단마다 하나","전하려는 생각"],"asset":{"type":"passage","lines":["① 지난주 한별초등학교 앞 횡단보도에 그늘막이 세워졌다.","② 한여름 낮에는 신호를 기다리는 동안 햇볕이 뜨거워 힘들다는 의견이 많았다.","③ 그늘막 아래 온도는 볕이 드는 곳보다 훨씬 낮게 나타났다.","④ 학교에서는 그늘막 안에서 차례를 지켜 기다려 달라고 안내했다."],"title":"학교 앞에 그늘막이 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_L12_challenge#10','kor',4,1,'u4','L12','g4_1_kor_u4_L12_challenge','lesson_challenge','K4-1-u4-C53',4,'essay','teacher','「숙제」와 「책상」을 읽을 때 어떻게 소리 나는지 쓰고, 적을 때는 어떻게 적어야 하는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u4-C53","difficulty":4,"kind":"essay","stem":"「숙제」와 「책상」을 읽을 때 어떻게 소리 나는지 쓰고, 적을 때는 어떻게 적어야 하는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「숙제」는 [숙쩨], 「책상」은 [책쌍]으로 소리 난다. 앞 글자 받침 뒤의 소리가 된소리로 나지만, 적을 때는 낱말의 원래 모양대로 「숙제」, 「책상」으로 적어야 뜻을 알아보기 쉽다.","scoring_points":["두 낱말의 소리를 바르게 썼는가","적을 때는 원래 모양대로 적는다고 썼는가","까닭을 썼는가"]},"explanation":["소리","적는 모양","까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#1','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C6',1,'mc','auto','형태만 같고 뜻이 전혀 다른 낱말을 무엇이라고 하나요?',ARRAY['K4-1-u4-X09','K4-1-u4-X20','K4-1-u4-X38']::text[],false,'{"seq":1,"concept":"K4-1-u4-C6","difficulty":1,"kind":"mc","stem":"형태만 같고 뜻이 전혀 다른 낱말을 무엇이라고 하나요?","options":[{"t":"동형이의어","correct":true},{"t":"다의어","mis":"K4-1-u4-X09"},{"t":"가리키는 말","mis":"K4-1-u4-X20"},{"t":"중심 문장","mis":"K4-1-u4-X38"}],"explanation":["형태만 같아요.","뜻은 전혀 달라요.","동형이의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#2','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C3',1,'mc','auto','「바람이 불어 마당의 풀이 누웠다.」에서 「풀」의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X03','K4-1-u4-X02']::text[],false,'{"seq":2,"concept":"K4-1-u4-C3","difficulty":1,"kind":"mc","stem":"「바람이 불어 마당의 풀이 누웠다.」에서 「풀」의 뜻은 무엇인가요?","options":[{"t":"땅에서 자라는 작은 식물","correct":true},{"t":"종이를 붙이는 끈끈한 것","mis":"K4-1-u4-X03"},{"t":"묶인 것을 끄르는 일","mis":"K4-1-u4-X03"},{"t":"어디서나 뜻이 같아 고를 수 없다","mis":"K4-1-u4-X02"}],"explanation":["마당에서 누웠어요.","바람에 눕는 것","식물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#3','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C16',1,'mc','auto','「가벼워서」를 국어사전에서 찾을 때 찾아야 할 낱말은 무엇인가요?',ARRAY['K4-1-u4-X15']::text[],false,'{"seq":3,"concept":"K4-1-u4-C16","difficulty":1,"kind":"mc","stem":"「가벼워서」를 국어사전에서 찾을 때 찾아야 할 낱말은 무엇인가요?","options":[{"t":"가볍다","correct":true},{"t":"가벼워서","mis":"K4-1-u4-X15"},{"t":"가벼워","mis":"K4-1-u4-X15"},{"t":"가벼운","mis":"K4-1-u4-X15"}],"explanation":["기본형으로","「-다」","가볍다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#4','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C24',1,'mc','auto','내가 입은 외투를 가리키며 짝에게 말할 때 알맞은 말은 무엇인가요?',ARRAY['K4-1-u4-X21','K4-1-u4-X20']::text[],false,'{"seq":4,"concept":"K4-1-u4-C24","difficulty":1,"kind":"mc","stem":"내가 입은 외투를 가리키며 짝에게 말할 때 알맞은 말은 무엇인가요?","options":[{"t":"이것","correct":true},{"t":"그것","mis":"K4-1-u4-X21"},{"t":"저것","mis":"K4-1-u4-X21"},{"t":"외투라는 이름만 쓸 수 있다","mis":"K4-1-u4-X20"}],"explanation":["나에게 가까워요.","말하는 사람 쪽","이것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#5','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C28',1,'mc','auto','「다시 올라간 깃발」 ⑤ 「이걸로 하자.」에서 「이걸」이 가리키는 것은 무엇인가요?',ARRAY['K4-1-u4-X23']::text[],false,'{"seq":5,"concept":"K4-1-u4-C28","difficulty":1,"kind":"mc","stem":"「다시 올라간 깃발」 ⑤ 「이걸로 하자.」에서 「이걸」이 가리키는 것은 무엇인가요?","options":[{"t":"서진이가 찾아온 긴 막대","correct":true},{"t":"모둠 깃발","mis":"K4-1-u4-X23"},{"t":"집에 두고 온 깃대","mis":"K4-1-u4-X23"},{"t":"교실 뒤 우산꽂이","mis":"K4-1-u4-X23"}],"explanation":["바로 앞 ④","찾아온 것은?","긴 막대예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#6','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C32',1,'mc','auto','이야기의 중심 생각을 찾을 때 살펴보지 않아도 되는 것은 무엇인가요?',ARRAY['K4-1-u4-X27']::text[],false,'{"seq":6,"concept":"K4-1-u4-C32","difficulty":1,"kind":"mc","stem":"이야기의 중심 생각을 찾을 때 살펴보지 않아도 되는 것은 무엇인가요?","options":[{"t":"인물의 이름이 몇 글자인지","correct":true},{"t":"제목","mis":"K4-1-u4-X27"},{"t":"줄거리","mis":"K4-1-u4-X27"},{"t":"인물의 말과 행동","mis":"K4-1-u4-X27"}],"explanation":["제목 · 줄거리 · 말과 행동","이름 글자 수는?","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#7','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C43',1,'mc','auto','「계단에서는 오른쪽으로 다녀요」의 중요한 낱말은 무엇인가요?',ARRAY['K4-1-u4-X36']::text[],false,'{"seq":7,"concept":"K4-1-u4-C43","difficulty":1,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」의 중요한 낱말은 무엇인가요?","options":[{"t":"계단","correct":true},{"t":"쉬는 시간","mis":"K4-1-u4-X36"},{"t":"앞사람","mis":"K4-1-u4-X36"},{"t":"방향","mis":"K4-1-u4-X36"}],"explanation":["제목에도 있고","여러 번 나와요.","계단이에요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#8','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C53',1,'mc','auto','소리 내어 읽을 때 된소리가 나는 낱말은 무엇인가요?',ARRAY['K4-1-u4-X48']::text[],false,'{"seq":8,"concept":"K4-1-u4-C53","difficulty":1,"kind":"mc","stem":"소리 내어 읽을 때 된소리가 나는 낱말은 무엇인가요?","options":[{"t":"잡지","correct":true},{"t":"나무","mis":"K4-1-u4-X48"},{"t":"구름","mis":"K4-1-u4-X48"},{"t":"바람","mis":"K4-1-u4-X48"}],"explanation":["[잡찌]","받침 뒤 소리","잡지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#9','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C8',2,'mc','auto','다음 가운데 동형이의어인 짝은 무엇인가요?',ARRAY['K4-1-u4-X09']::text[],false,'{"seq":9,"concept":"K4-1-u4-C8","difficulty":2,"kind":"mc","stem":"다음 가운데 동형이의어인 짝은 무엇인가요?","options":[{"t":"비가 내리다 / 비로 마당을 쓸다","correct":true},{"t":"운동장이 넓다 / 마음이 넓다","mis":"K4-1-u4-X09"},{"t":"끈을 풀다 / 문제를 풀다","mis":"K4-1-u4-X09"},{"t":"가방이 가볍다 / 마음이 가볍다","mis":"K4-1-u4-X09"}],"explanation":["뜻이 이어지지 않는 짝","하늘의 비 · 쓰는 비","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#10','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C10',2,'mc','auto','국어사전에서 「말」을 말¹, 말²로 따로 실은 까닭은 무엇인가요?',ARRAY['K4-1-u4-X10','K4-1-u4-X08','K4-1-u4-X16']::text[],false,'{"seq":10,"concept":"K4-1-u4-C10","difficulty":2,"kind":"mc","stem":"국어사전에서 「말」을 말¹, 말²로 따로 실은 까닭은 무엇인가요?","options":[{"t":"뜻이 이어지지 않는 서로 다른 낱말이라서","correct":true},{"t":"뜻이 이어진 한 낱말이라서","mis":"K4-1-u4-X10"},{"t":"글자 모양이 서로 달라서","mis":"K4-1-u4-X08"},{"t":"말¹만 바른 말이라서","mis":"K4-1-u4-X16"}],"explanation":["짐승과 소리","서로 다른 낱말","따로 실어요."],"asset":{"type":"passage","lines":["말¹ 사람이 타기도 하고 짐을 나르기도 하는 큰 짐승.","말² 생각이나 느낌을 소리로 나타낸 것. 예 말을 하다.","맑다 「1」 물이 깨끗하다. 「2」 소리가 깨끗하고 또렷하다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#11','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C12',2,'mc','auto','어떤 낱말이 동형이의어인지 다의어인지 말할 때 알맞은 태도는 무엇인가요?',ARRAY['K4-1-u4-X12','K4-1-u4-X08','K4-1-u4-X16']::text[],false,'{"seq":11,"concept":"K4-1-u4-C12","difficulty":2,"kind":"mc","stem":"어떤 낱말이 동형이의어인지 다의어인지 말할 때 알맞은 태도는 무엇인가요?","options":[{"t":"어떤 뜻끼리 견주는지 문장에서 살핀 뒤 말한다","correct":true},{"t":"한 번 동형이의어면 언제나 동형이의어라고 정한다","mis":"K4-1-u4-X12"},{"t":"글자만 보고 바로 정한다","mis":"K4-1-u4-X08"},{"t":"사전의 첫 번째 뜻만 보고 정한다","mis":"K4-1-u4-X16"}],"explanation":["늘 한쪽일까요?","견주는 뜻","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#12','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C20',2,'mc','auto','「깊은 바다처럼 생각도 깊게」라는 문구에서 「깊다」가 하는 일은 무엇인가요?',ARRAY['K4-1-u4-X18','K4-1-u4-X03']::text[],false,'{"seq":12,"concept":"K4-1-u4-C20","difficulty":2,"kind":"mc","stem":"「깊은 바다처럼 생각도 깊게」라는 문구에서 「깊다」가 하는 일은 무엇인가요?","options":[{"t":"물이 깊다는 뜻과 생각이 깊다는 뜻을 함께 전한다","correct":true},{"t":"물이 깊다는 뜻 하나만 전한다","mis":"K4-1-u4-X18"},{"t":"낱말을 잘못 써서 뜻이 없다","mis":"K4-1-u4-X18"},{"t":"바다로 놀러 가자는 뜻만 전한다","mis":"K4-1-u4-X03"}],"explanation":["두 뜻을 함께","바다 · 생각","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#13','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C30',2,'mc','auto','가리키는 말을 쓰면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X25','K4-1-u4-X23']::text[],false,'{"seq":13,"concept":"K4-1-u4-C30","difficulty":2,"kind":"mc","stem":"가리키는 말을 쓰면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"같은 말을 되풀이하지 않아 글이 짧고 깔끔해진다","correct":true},{"t":"글의 내용이 새롭게 바뀐다","mis":"K4-1-u4-X25"},{"t":"글이 길어져 더 자세해진다","mis":"K4-1-u4-X25"},{"t":"가리키는 내용을 몰라도 읽을 수 있다","mis":"K4-1-u4-X23"}],"explanation":["되풀이 없이","짧고 깔끔하게","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#14','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C38',2,'mc','auto','「다시 올라간 깃발」의 중심 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X32','K4-1-u4-X33','K4-1-u4-X31']::text[],false,'{"seq":14,"concept":"K4-1-u4-C38","difficulty":2,"kind":"mc","stem":"「다시 올라간 깃발」의 중심 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"친구의 실수를 탓하기보다 함께 방법을 찾으면 다시 힘을 낼 수 있다","correct":true},{"t":"민우가 깃대를 집에 두고 왔다","mis":"K4-1-u4-X32"},{"t":"우산꽂이에는 긴 막대가 있다","mis":"K4-1-u4-X33"},{"t":"운동회 날에는 일찍 일어나자","mis":"K4-1-u4-X31"}],"explanation":["있었던 일 말고","전하려는 생각","첫째예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#15','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C48',2,'mc','auto','「계단에서는 오른쪽으로 다녀요」의 ㉯ · ㉰ · ㉱가 하는 일은 무엇인가요?',ARRAY['K4-1-u4-X41','K4-1-u4-X40']::text[],false,'{"seq":15,"concept":"K4-1-u4-C48","difficulty":2,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」의 ㉯ · ㉰ · ㉱가 하는 일은 무엇인가요?","options":[{"t":"「오른쪽으로 다니자」는 생각을 받쳐 주는 까닭을 든다","correct":true},{"t":"세 문단이 각각 글 전체의 중심 생각이다","mis":"K4-1-u4-X41"},{"t":"글쓴이의 생각과 상관없는 이야기이다","mis":"K4-1-u4-X40"},{"t":"중심 생각에 반대하는 말이다","mis":"K4-1-u4-X41"}],"explanation":["첫째 · 둘째 · 셋째","받쳐 주는 말","첫째예요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#16','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C51',2,'mc','auto','「○○을 뽑다.」, 「○○로 종이를 붙이다.」 두 빈칸에 함께 들어갈 낱말과 관계를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X09','K4-1-u4-X45']::text[],false,'{"seq":16,"concept":"K4-1-u4-C51","difficulty":2,"kind":"mc","stem":"「○○을 뽑다.」, 「○○로 종이를 붙이다.」 두 빈칸에 함께 들어갈 낱말과 관계를 바르게 말한 것은 무엇인가요?","options":[{"t":"풀 — 동형이의어","correct":true},{"t":"풀 — 다의어","mis":"K4-1-u4-X09"},{"t":"잡초 — 동형이의어","mis":"K4-1-u4-X45"},{"t":"접착제 — 다의어","mis":"K4-1-u4-X45"}],"explanation":["두 빈칸 모두","땅의 풀 · 붙이는 풀","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#17','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C17',3,'mc','auto','「동생이 말을 또박또박 잘한다.」의 「말」에 알맞은 사전의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X16','K4-1-u4-X02','K4-1-u4-X15']::text[],false,'{"seq":17,"concept":"K4-1-u4-C17","difficulty":3,"kind":"mc","stem":"「동생이 말을 또박또박 잘한다.」의 「말」에 알맞은 사전의 뜻은 무엇인가요?","options":[{"t":"말² 생각이나 느낌을 소리로 나타낸 것","correct":true},{"t":"말¹ 사람이 타기도 하고 짐을 나르기도 하는 큰 짐승","mis":"K4-1-u4-X16"},{"t":"두 뜻 모두 맞다","mis":"K4-1-u4-X02"},{"t":"사전에서는 찾을 수 없다","mis":"K4-1-u4-X15"}],"explanation":["또박또박 잘한다","소리로 나타낸 것","말²예요."],"asset":{"type":"passage","lines":["말¹ 사람이 타기도 하고 짐을 나르기도 하는 큰 짐승.","말² 생각이나 느낌을 소리로 나타낸 것. 예 말을 하다.","맑다 「1」 물이 깨끗하다. 「2」 소리가 깨끗하고 또렷하다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#18','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C34',3,'mc','auto','「다시 올라간 깃발」의 줄거리를 알맞게 간추린 것은 무엇인가요?',ARRAY['K4-1-u4-X29']::text[],false,'{"seq":18,"concept":"K4-1-u4-C34","difficulty":3,"kind":"mc","stem":"「다시 올라간 깃발」의 줄거리를 알맞게 간추린 것은 무엇인가요?","options":[{"t":"깃대를 두고 와 속상해한 민우를 위해 모둠이 막대로 깃발을 다시 달았고, 민우는 웃으며 깃발을 들었다","correct":true},{"t":"선생님이 새 깃대를 사 주셔서 운동회에 나갔다","mis":"K4-1-u4-X29"},{"t":"깃발을 들기로 하고, 깃대를 두고 오고, 고개를 숙이고, 막대를 찾고, 묶고, 웃은 일을 하나도 빼지 않고 늘어놓는다","mis":"K4-1-u4-X29"},{"t":"깃대가 없어 모둠이 운동회에 나가지 못했다","mis":"K4-1-u4-X29"}],"explanation":["주요 장면만","있었던 일만","첫째예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#19','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C44',3,'mc','auto','「계단에서는 오른쪽으로 다녀요」 ㉯ · ㉰ · ㉱ 문단의 중심 내용을 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u4-X37','K4-1-u4-X38','K4-1-u4-X36']::text[],false,'{"seq":19,"concept":"K4-1-u4-C44","difficulty":3,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」 ㉯ · ㉰ · ㉱ 문단의 중심 내용을 바르게 정리한 것은 무엇인가요?","options":[{"t":"부딪치지 않는다 · 넘어지지 않는다 · 빨리 오갈 수 있다","correct":true},{"t":"부딪치지 않는다 · 계단이 붐빈다 · 쉬는 시간이 안전하다","mis":"K4-1-u4-X37"},{"t":"마주칠 일이 준다 · 미끄러질 일이 없다 · 한 방향으로 흐른다","mis":"K4-1-u4-X38"},{"t":"세 문단 모두 「계단」이 중심 내용이다","mis":"K4-1-u4-X36"}],"explanation":["문단마다 첫 문장","하나씩","첫째예요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#20','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C46',3,'mc','auto','「놀이터의 그네가 새로 칠해졌다. 미끄럼틀 옆에는 새 모래가 채워졌다. 정글짐의 녹슨 곳도 고쳤다.」의 중심 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X37','K4-1-u4-X39','K4-1-u4-X36']::text[],false,'{"seq":20,"concept":"K4-1-u4-C46","difficulty":3,"kind":"mc","stem":"「놀이터의 그네가 새로 칠해졌다. 미끄럼틀 옆에는 새 모래가 채워졌다. 정글짐의 녹슨 곳도 고쳤다.」의 중심 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"놀이터가 새롭게 고쳐지고 꾸며졌다","correct":true},{"t":"그네가 새로 칠해졌다","mis":"K4-1-u4-X37"},{"t":"중심 문장이 없으니 중심 내용을 알 수 없다","mis":"K4-1-u4-X39"},{"t":"모래","mis":"K4-1-u4-X36"}],"explanation":["세 문장을 모아요.","놀이터 이야기","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#21','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C27',3,'mc','auto','「다시 올라간 깃발」 ⑤의 「이걸」처럼 가리키는 말을 쓴 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X20','K4-1-u4-X21','K4-1-u4-X26']::text[],false,'{"seq":21,"concept":"K4-1-u4-C27","difficulty":3,"kind":"mc","stem":"「다시 올라간 깃발」 ⑤의 「이걸」처럼 가리키는 말을 쓴 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"서진이가 들고 온, 앞에서 말한 긴 막대를 다시 길게 말하지 않으려고","correct":true},{"t":"막대의 이름을 몰라서","mis":"K4-1-u4-X20"},{"t":"듣는 사람 쪽에 있는 물건이라서","mis":"K4-1-u4-X21"},{"t":"처음 보는 물건을 소개하려고","mis":"K4-1-u4-X26"}],"explanation":["④에서 나온 막대","서진이에게 가까워요.","첫째예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#22','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C53',3,'mc','auto','「낚시」를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X47','K4-1-u4-X48']::text[],false,'{"seq":22,"concept":"K4-1-u4-C53","difficulty":3,"kind":"mc","stem":"「낚시」를 바르게 말한 것은 무엇인가요?","options":[{"t":"[낙씨]로 소리 나지만 「낚시」로 적는다","correct":true},{"t":"소리 나는 대로 「낙씨」로 적는다","mis":"K4-1-u4-X47"},{"t":"된소리로 소리 나지 않는다","mis":"K4-1-u4-X48"},{"t":"[낚시]로만 읽고 적는다","mis":"K4-1-u4-X48"}],"explanation":["읽을 때 [낙씨]","적을 때는?","원래대로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#23','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C8',4,'essay','teacher','「굴」과 「깊다」로 각각 뜻이 다른 문장 두 개를 쓰고, 어느 쪽이 동형이의어이고 어느 쪽이 다의어인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u4-C8","difficulty":4,"kind":"essay","stem":"「굴」과 「깊다」로 각각 뜻이 다른 문장 두 개를 쓰고, 어느 쪽이 동형이의어이고 어느 쪽이 다의어인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「바닷가에서 굴을 땄다.」 / 「산 아래 굴 속으로 들어갔다.」 — 먹을거리와 패어 들어간 곳은 뜻이 이어지지 않으므로 동형이의어이다. 「물이 깊다.」 / 「생각이 깊다.」 — 밑바닥까지 멀다는 뜻이 생각에까지 넓어져 이어지므로 다의어이다.","scoring_points":["두 낱말로 뜻이 다른 문장을 썼는가","동형이의어와 다의어를 바르게 갈랐는가","뜻의 이어짐으로 까닭을 썼는가"]},"explanation":["굴 두 문장","깊다 두 문장","이어졌나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#24','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C36',4,'essay','teacher','「다시 올라간 깃발」의 중심 생각을 쓰고, 제목 · 줄거리 · 인물의 말과 행동에서 근거를 하나씩 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u4-C36","difficulty":4,"kind":"essay","stem":"「다시 올라간 깃발」의 중심 생각을 쓰고, 제목 · 줄거리 · 인물의 말과 행동에서 근거를 하나씩 쓰세요.","answer_guide":{"answer":"예: 중심 생각은 「친구의 실수를 탓하기보다 함께 방법을 찾으면 다시 힘을 낼 수 있다.」이다. 제목 「다시 올라간 깃발」은 깃발이 다시 올라간 일을 중요하게 여긴다. 줄거리는 깃대를 두고 온 민우를 위해 모둠이 막대로 깃발을 달아 준 이야기이다. 서진이는 「깃발만 있으면 돼.」라고 말했고, 민우는 웃으며 깃발을 높이 들었다.","scoring_points":["중심 생각을 바르게 썼는가","제목 · 줄거리 · 인물의 말과 행동에서 근거를 들었는가","근거가 글에 나온 내용인가"]},"explanation":["제목","줄거리","인물의 말과 행동"],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_a#25','kor',4,1,'u4','','g4_1_kor_u4_review_a','unit_review','K4-1-u4-C24',4,'essay','teacher','「다시 올라간 깃발」 ⑤ 「이걸로 하자.」의 「이걸」이 가리키는 것을 쓰고, 「이걸」 대신 「그걸」이라고 했다면 막대가 어디에 있는 상황인지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u4-C24","difficulty":4,"kind":"essay","stem":"「다시 올라간 깃발」 ⑤ 「이걸로 하자.」의 「이걸」이 가리키는 것을 쓰고, 「이걸」 대신 「그걸」이라고 했다면 막대가 어디에 있는 상황인지 쓰세요.","answer_guide":{"answer":"예: 「이걸」은 서진이가 찾아온 긴 막대를 가리킨다. 막대가 말하는 서진이에게 가까이 있어 「이걸」이라고 했다. 「그걸」이라고 했다면 막대가 듣는 친구 쪽에 가까이 있는 상황이다.","scoring_points":["가리키는 것을 바르게 썼는가","「이것」의 거리를 썼는가","「그것」의 상황을 바르게 썼는가"]},"explanation":["④를 봐요.","말하는 사람 쪽","듣는 사람 쪽"],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#1','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C7',1,'mc','auto','원래 뜻을 넓혀 여러 뜻으로 쓰는 낱말을 무엇이라고 하나요?',ARRAY['K4-1-u4-X09','K4-1-u4-X38','K4-1-u4-X15']::text[],false,'{"seq":1,"concept":"K4-1-u4-C7","difficulty":1,"kind":"mc","stem":"원래 뜻을 넓혀 여러 뜻으로 쓰는 낱말을 무엇이라고 하나요?","options":[{"t":"다의어","correct":true},{"t":"동형이의어","mis":"K4-1-u4-X09"},{"t":"뒷받침 문장","mis":"K4-1-u4-X38"},{"t":"기본형","mis":"K4-1-u4-X15"}],"explanation":["뜻이 넓어져요.","서로 이어져요.","다의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#2','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C14',1,'mc','auto','「풀이 굳어서 종이가 붙지 않았다.」에서 「풀」의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X03','K4-1-u4-X16']::text[],false,'{"seq":2,"concept":"K4-1-u4-C14","difficulty":1,"kind":"mc","stem":"「풀이 굳어서 종이가 붙지 않았다.」에서 「풀」의 뜻은 무엇인가요?","options":[{"t":"종이를 붙이는 끈끈한 것","correct":true},{"t":"땅에서 자라는 작은 식물","mis":"K4-1-u4-X03"},{"t":"문제의 답을 찾는 일","mis":"K4-1-u4-X03"},{"t":"사전에 처음 실린 뜻이 늘 맞다","mis":"K4-1-u4-X16"}],"explanation":["종이가 붙지 않았어요.","굳는 것은?","붙이는 풀이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#3','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C16',1,'mc','auto','「풀었다」의 뜻을 국어사전에서 찾으려면 어떤 낱말을 찾아야 하나요?',ARRAY['K4-1-u4-X15']::text[],false,'{"seq":3,"concept":"K4-1-u4-C16","difficulty":1,"kind":"mc","stem":"「풀었다」의 뜻을 국어사전에서 찾으려면 어떤 낱말을 찾아야 하나요?","options":[{"t":"풀다","correct":true},{"t":"풀었다","mis":"K4-1-u4-X15"},{"t":"풀어","mis":"K4-1-u4-X15"},{"t":"풀","mis":"K4-1-u4-X15"}],"explanation":["기본형으로","「-다」","풀다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#4','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C25',1,'mc','auto','짝이 들고 있는 우산을 가리키며 짝에게 말할 때 알맞은 말은 무엇인가요?',ARRAY['K4-1-u4-X21','K4-1-u4-X20']::text[],false,'{"seq":4,"concept":"K4-1-u4-C25","difficulty":1,"kind":"mc","stem":"짝이 들고 있는 우산을 가리키며 짝에게 말할 때 알맞은 말은 무엇인가요?","options":[{"t":"그것","correct":true},{"t":"이것","mis":"K4-1-u4-X21"},{"t":"저것","mis":"K4-1-u4-X21"},{"t":"우산","mis":"K4-1-u4-X20"}],"explanation":["짝에게 가까워요.","듣는 사람 쪽","그것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#5','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C28',1,'mc','auto','「현관에 상자가 왔다. 그것을 열어 보니 책이 들어 있었다.」에서 「그것」이 가리키는 것은 무엇인가요?',ARRAY['K4-1-u4-X23']::text[],false,'{"seq":5,"concept":"K4-1-u4-C28","difficulty":1,"kind":"mc","stem":"「현관에 상자가 왔다. 그것을 열어 보니 책이 들어 있었다.」에서 「그것」이 가리키는 것은 무엇인가요?","options":[{"t":"상자","correct":true},{"t":"현관","mis":"K4-1-u4-X23"},{"t":"책","mis":"K4-1-u4-X23"},{"t":"열어 보는 일","mis":"K4-1-u4-X23"}],"explanation":["무엇을 열었나요?","바로 앞 문장","상자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#6','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C35',1,'mc','auto','「다시 올라간 깃발」 ③ 「나 때문에 다 망쳤어.」에서 알 수 있는 민우의 마음은 무엇인가요?',ARRAY['K4-1-u4-X31','K4-1-u4-X03','K4-1-u4-X30']::text[],false,'{"seq":6,"concept":"K4-1-u4-C35","difficulty":1,"kind":"mc","stem":"「다시 올라간 깃발」 ③ 「나 때문에 다 망쳤어.」에서 알 수 있는 민우의 마음은 무엇인가요?","options":[{"t":"모둠에 미안하고 속상한 마음","correct":true},{"t":"깃발을 들기 싫은 마음","mis":"K4-1-u4-X31"},{"t":"모둠 친구들을 탓하는 마음","mis":"K4-1-u4-X03"},{"t":"키가 작아 깃발을 못 든다는 마음","mis":"K4-1-u4-X30"}],"explanation":["「나 때문에」","고개를 숙였어요.","미안하고 속상해요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#7','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C47',1,'mc','auto','「계단에서는 오른쪽으로 다녀요」에서 글쓴이가 하고 싶은 말을 다시 한번 밝힌 문단은 무엇인가요?',ARRAY['K4-1-u4-X40']::text[],false,'{"seq":7,"concept":"K4-1-u4-C47","difficulty":1,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」에서 글쓴이가 하고 싶은 말을 다시 한번 밝힌 문단은 무엇인가요?","options":[{"t":"㉲","correct":true},{"t":"㉯","mis":"K4-1-u4-X40"},{"t":"㉰","mis":"K4-1-u4-X40"},{"t":"㉱","mis":"K4-1-u4-X40"}],"explanation":["마지막 문단","「다녀요」","㉲예요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#8','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C53',1,'mc','auto','「학생」을 소리 내어 읽은 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X48','K4-1-u4-X47']::text[],false,'{"seq":8,"concept":"K4-1-u4-C53","difficulty":1,"kind":"mc","stem":"「학생」을 소리 내어 읽은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"[학쌩]","correct":true},{"t":"[학생]","mis":"K4-1-u4-X48"},{"t":"[하생]","mis":"K4-1-u4-X48"},{"t":"「학쌩」으로 적고 읽는다","mis":"K4-1-u4-X47"}],"explanation":["받침 뒤 소리","된소리로","[학쌩]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#9','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C8',2,'mc','auto','다음 가운데 다의어인 짝은 무엇인가요?',ARRAY['K4-1-u4-X06']::text[],false,'{"seq":9,"concept":"K4-1-u4-C8","difficulty":2,"kind":"mc","stem":"다음 가운데 다의어인 짝은 무엇인가요?","options":[{"t":"물이 깊다 / 생각이 깊다","correct":true},{"t":"굴을 따다 / 굴 속에 들어가다","mis":"K4-1-u4-X06"},{"t":"빨래를 말리다 / 싸움을 말리다","mis":"K4-1-u4-X06"},{"t":"풀을 뽑다 / 풀로 붙이다","mis":"K4-1-u4-X06"}],"explanation":["뜻이 이어진 짝","물 → 생각","깊다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#10','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C11',2,'mc','auto','국어사전에서 「맑다」를 한 낱말 안에 「1」, 「2」로 실은 까닭은 무엇인가요?',ARRAY['K4-1-u4-X11','K4-1-u4-X16','K4-1-u4-X08']::text[],false,'{"seq":10,"concept":"K4-1-u4-C11","difficulty":2,"kind":"mc","stem":"국어사전에서 「맑다」를 한 낱말 안에 「1」, 「2」로 실은 까닭은 무엇인가요?","options":[{"t":"뜻이 서로 이어진 다의어라서","correct":true},{"t":"뜻이 이어지지 않는 동형이의어라서","mis":"K4-1-u4-X11"},{"t":"「1」만 맞는 뜻이라서","mis":"K4-1-u4-X16"},{"t":"두 낱말의 글자가 달라서","mis":"K4-1-u4-X08"}],"explanation":["물 → 소리","이어진 뜻","다의어예요."],"asset":{"type":"passage","lines":["말¹ 사람이 타기도 하고 짐을 나르기도 하는 큰 짐승.","말² 생각이나 느낌을 소리로 나타낸 것. 예 말을 하다.","맑다 「1」 물이 깨끗하다. 「2」 소리가 깨끗하고 또렷하다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#11','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C19',2,'mc','auto','「동생은 높은 선반의 그릇을 꺼내다 놀라 목소리가 높아졌다.」에 대해 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X17','K4-1-u4-X07','K4-1-u4-X18']::text[],false,'{"seq":11,"concept":"K4-1-u4-C19","difficulty":2,"kind":"mc","stem":"「동생은 높은 선반의 그릇을 꺼내다 놀라 목소리가 높아졌다.」에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"한 문장 안에서도 「높다」의 뜻이 자리마다 다르다","correct":true},{"t":"한 문장 안이니 두 「높다」의 뜻은 같다","mis":"K4-1-u4-X17"},{"t":"두 「높다」는 뜻이 서로 이어지지 않는다","mis":"K4-1-u4-X07"},{"t":"뒤의 「높다」는 잘못 쓴 말이다","mis":"K4-1-u4-X18"}],"explanation":["선반이 높다","목소리가 높다","자리마다 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#12','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C21',2,'mc','auto','광고에 여러 가지로 해석되는 낱말을 쓰는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X19']::text[],false,'{"seq":12,"concept":"K4-1-u4-C21","difficulty":2,"kind":"mc","stem":"광고에 여러 가지로 해석되는 낱말을 쓰는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"짧은 말로 두 가지를 함께 전하고 오래 기억에 남아서","correct":true},{"t":"낱말의 뜻을 없애려고","mis":"K4-1-u4-X19"},{"t":"읽는 사람이 헷갈려 그냥 넘기게 하려고","mis":"K4-1-u4-X19"},{"t":"글자 수를 늘리려고","mis":"K4-1-u4-X19"}],"explanation":["재미 · 전달 · 기억","뜻을 없앨까요?","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#13','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C31',2,'mc','auto','「우리 반에 새 화분이 생겼다. 새 화분에는 해바라기가 심겨 있다.」를 가리키는 말로 바르게 고친 것은 무엇인가요?',ARRAY['K4-1-u4-X26','K4-1-u4-X23']::text[],false,'{"seq":13,"concept":"K4-1-u4-C31","difficulty":2,"kind":"mc","stem":"「우리 반에 새 화분이 생겼다. 새 화분에는 해바라기가 심겨 있다.」를 가리키는 말로 바르게 고친 것은 무엇인가요?","options":[{"t":"우리 반에 새 화분이 생겼다. 그 화분에는 해바라기가 심겨 있다.","correct":true},{"t":"우리 반에 그것이 생겼다. 새 화분에는 해바라기가 심겨 있다.","mis":"K4-1-u4-X26"},{"t":"우리 반에 새 화분이 생겼다. 그 반에는 해바라기가 심겨 있다.","mis":"K4-1-u4-X23"},{"t":"우리 반에 그것이 생겼다. 그것에는 해바라기가 심겨 있다.","mis":"K4-1-u4-X26"}],"explanation":["처음은 그대로","다시 나올 때","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#14','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C39',2,'mc','auto','친구가 「다시 올라간 깃발」 ②만 보고 「준비물은 전날 챙기자.」를 중심 생각으로 골랐어요. 알맞게 말해 준 것은 무엇인가요?',ARRAY['K4-1-u4-X33','K4-1-u4-X30','K4-1-u4-X31']::text[],false,'{"seq":14,"concept":"K4-1-u4-C39","difficulty":2,"kind":"mc","stem":"친구가 「다시 올라간 깃발」 ②만 보고 「준비물은 전날 챙기자.」를 중심 생각으로 골랐어요. 알맞게 말해 준 것은 무엇인가요?","options":[{"t":"「작은 장면 하나만 보지 말고 제목 · 줄거리 · 인물의 말을 모아야 해.」","correct":true},{"t":"「맞아. 깃대를 두고 온 장면이 가장 중요해.」","mis":"K4-1-u4-X33"},{"t":"「민우 이름이 먼저 나왔으니 민우가 중심 생각이야.」","mis":"K4-1-u4-X30"},{"t":"「나도 준비물을 잃어버린 적이 있으니 그게 맞아.」","mis":"K4-1-u4-X31"}],"explanation":["한 장면만?","모두 모아요.","첫째예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#15','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C48',2,'mc','auto','친구가 「계단에서는 오른쪽으로 다녀요」의 중심 생각을 「계단이 막히지 않는다.」라고 했어요. 알맞게 고쳐 준 말은 무엇인가요?',ARRAY['K4-1-u4-X41','K4-1-u4-X39']::text[],false,'{"seq":15,"concept":"K4-1-u4-C48","difficulty":2,"kind":"mc","stem":"친구가 「계단에서는 오른쪽으로 다녀요」의 중심 생각을 「계단이 막히지 않는다.」라고 했어요. 알맞게 고쳐 준 말은 무엇인가요?","options":[{"t":"「그건 까닭 가운데 하나야. 까닭들이 받쳐 주는 생각이 중심 생각이야.」","correct":true},{"t":"「맞아. 마지막 까닭이 중심 생각이야.」","mis":"K4-1-u4-X41"},{"t":"「넘어지지 않는다가 중심 생각이야.」","mis":"K4-1-u4-X41"},{"t":"「중심 생각이 한 문장으로 안 쓰여 있으니 없어.」","mis":"K4-1-u4-X39"}],"explanation":["까닭 하나","받쳐 주는 생각","첫째예요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#16','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C51',2,'mc','auto','「소리가 ○○.」, 「산이 ○○.」 두 빈칸에 함께 들어갈 낱말은 무엇인가요?',ARRAY['K4-1-u4-X45']::text[],false,'{"seq":16,"concept":"K4-1-u4-C51","difficulty":2,"kind":"mc","stem":"「소리가 ○○.」, 「산이 ○○.」 두 빈칸에 함께 들어갈 낱말은 무엇인가요?","options":[{"t":"높다","correct":true},{"t":"시끄럽다","mis":"K4-1-u4-X45"},{"t":"가파르다","mis":"K4-1-u4-X45"},{"t":"맑다","mis":"K4-1-u4-X45"}],"explanation":["두 빈칸 모두","소리가 높다 · 산이 높다","높다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#17','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C17',3,'mc','auto','「노래하는 목소리가 참 맑다.」의 「맑다」에 알맞은 사전의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X16','K4-1-u4-X03','K4-1-u4-X02']::text[],false,'{"seq":17,"concept":"K4-1-u4-C17","difficulty":3,"kind":"mc","stem":"「노래하는 목소리가 참 맑다.」의 「맑다」에 알맞은 사전의 뜻은 무엇인가요?","options":[{"t":"「2」 소리가 깨끗하고 또렷하다","correct":true},{"t":"「1」 물이 깨끗하다","mis":"K4-1-u4-X16"},{"t":"말² 생각이나 느낌을 소리로 나타낸 것","mis":"K4-1-u4-X03"},{"t":"「맑다」는 뜻이 하나뿐이다","mis":"K4-1-u4-X02"}],"explanation":["목소리","소리가 깨끗해요.","「2」예요."],"asset":{"type":"passage","lines":["말¹ 사람이 타기도 하고 짐을 나르기도 하는 큰 짐승.","말² 생각이나 느낌을 소리로 나타낸 것. 예 말을 하다.","맑다 「1」 물이 깨끗하다. 「2」 소리가 깨끗하고 또렷하다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#18','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C35',3,'mc','auto','「다시 올라간 깃발」 ④~⑤ 서진이의 말과 행동에서 알 수 있는 서진이의 생각은 무엇인가요?',ARRAY['K4-1-u4-X31','K4-1-u4-X03','K4-1-u4-X30']::text[],false,'{"seq":18,"concept":"K4-1-u4-C35","difficulty":3,"kind":"mc","stem":"「다시 올라간 깃발」 ④~⑤ 서진이의 말과 행동에서 알 수 있는 서진이의 생각은 무엇인가요?","options":[{"t":"탓하기보다 지금 할 수 있는 방법을 찾자","correct":true},{"t":"민우가 잘못했으니 혼나야 한다","mis":"K4-1-u4-X31"},{"t":"깃발 없이 나가자","mis":"K4-1-u4-X03"},{"t":"서진이는 키가 커서 막대를 잘 찾는다","mis":"K4-1-u4-X30"}],"explanation":["막대를 찾아왔어요.","「깃발만 있으면 돼」","방법을 찾자"],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#19','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C45',3,'mc','auto','「계단에서는 오른쪽으로 다녀요」 ㉱에서 뒷받침 문장이 하는 일은 무엇인가요?',ARRAY['K4-1-u4-X38','K4-1-u4-X37','K4-1-u4-X41']::text[],false,'{"seq":19,"concept":"K4-1-u4-C45","difficulty":3,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」 ㉱에서 뒷받침 문장이 하는 일은 무엇인가요?","options":[{"t":"「빨리 오갈 수 있다」는 중심 문장을 까닭을 들어 받쳐 준다","correct":true},{"t":"문단에서 가장 하고 싶은 말을 한다","mis":"K4-1-u4-X38"},{"t":"㉱와 상관없는 새 이야기를 한다","mis":"K4-1-u4-X37"},{"t":"글 전체의 중심 생각을 밝힌다","mis":"K4-1-u4-X41"}],"explanation":["받쳐 주는 말","한 방향으로 흐르니","첫째예요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#20','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C46',3,'mc','auto','「텃밭 소식」 문단의 중심 내용을 정한 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X37','K4-1-u4-X39','K4-1-u4-X36']::text[],false,'{"seq":20,"concept":"K4-1-u4-C46","difficulty":3,"kind":"mc","stem":"「텃밭 소식」 문단의 중심 내용을 정한 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"상추 · 고추 · 방울토마토 이야기를 모아 「텃밭의 채소가 잘 자란다」로 정리했다","correct":true},{"t":"첫 문장만 보고 「상추가 자란다」로 정했다","mis":"K4-1-u4-X37"},{"t":"「~하자」라는 문장이 없어 정할 수 없다고 했다","mis":"K4-1-u4-X39"},{"t":"가장 많이 나온 낱말 하나만 적었다","mis":"K4-1-u4-X36"}],"explanation":["한 문장으로 쓰여 있지 않아요.","모아서","첫째예요."],"asset":{"type":"passage","lines":["우리 반 텃밭에서는 상추가 잎을 넓게 펼쳤다.","고추에는 하얀 꽃이 피었다.","방울토마토는 벌써 빨갛게 익었다."],"title":"텃밭 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#21','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C29',3,'mc','auto','「아침마다 물을 한 컵 마시고, 창문을 열어 바람을 들인다. 이것은 할머니께 배운 습관이다.」에서 「이것」이 가리키는 내용은 무엇인가요?',ARRAY['K4-1-u4-X24','K4-1-u4-X23']::text[],false,'{"seq":21,"concept":"K4-1-u4-C29","difficulty":3,"kind":"mc","stem":"「아침마다 물을 한 컵 마시고, 창문을 열어 바람을 들인다. 이것은 할머니께 배운 습관이다.」에서 「이것」이 가리키는 내용은 무엇인가요?","options":[{"t":"물을 한 컵 마시고 창문을 열어 바람을 들이는 것","correct":true},{"t":"물을 한 컵 마시는 것 하나","mis":"K4-1-u4-X24"},{"t":"창문을 여는 것 하나","mis":"K4-1-u4-X24"},{"t":"할머니","mis":"K4-1-u4-X23"}],"explanation":["앞 문장 모두","두 가지를 함께","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#22','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C54',3,'mc','auto','함께 쓰는 바른 말이 아닌 짝은 무엇인가요?',ARRAY['K4-1-u4-X50']::text[],false,'{"seq":22,"concept":"K4-1-u4-C54","difficulty":3,"kind":"mc","stem":"함께 쓰는 바른 말이 아닌 짝은 무엇인가요?","options":[{"t":"설거지 — 설겆이","correct":true},{"t":"자장면 — 짜장면","mis":"K4-1-u4-X50"},{"t":"넝쿨 — 덩굴","mis":"K4-1-u4-X50"},{"t":"삐치다 — 삐지다","mis":"K4-1-u4-X50"}],"explanation":["둘 다 바른 말인가요?","설겆이는?","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#23','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C12',4,'essay','teacher','「김」이 동형이의어가 되기도 하고 한 낱말 안의 여러 뜻이 되기도 하는 까닭을 예를 들어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u4-C12","difficulty":4,"kind":"essay","stem":"「김」이 동형이의어가 되기도 하고 한 낱말 안의 여러 뜻이 되기도 하는 까닭을 예를 들어 쓰세요.","answer_guide":{"answer":"예: 「김을 굽다」의 김과 「김이 오르다」의 김은 뜻이 이어지지 않아 동형이의어이다. 그런데 「김이 오르다」와 「유리에 김이 서리다」의 김은 뜻이 이어져 있다. 어떤 뜻끼리 견주는지에 따라 달라지기 때문에 「김」을 늘 한쪽으로 정할 수 없다.","scoring_points":["동형이의어가 되는 예를 들었는가","뜻이 이어지는 예를 들었는가","견주는 뜻에 따라 달라진다고 썼는가"]},"explanation":["먹는 김 · 오르는 김","오르는 김 · 서린 김","늘 한쪽은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#24','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C48',4,'essay','teacher','「계단에서는 오른쪽으로 다녀요」의 문단별 중심 내용을 정리하고, 글 전체의 중심 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u4-C48","difficulty":4,"kind":"essay","stem":"「계단에서는 오른쪽으로 다녀요」의 문단별 중심 내용을 정리하고, 글 전체의 중심 생각을 쓰세요.","answer_guide":{"answer":"예: ㉮ — 계단이 붐벼 안전한 방법을 묻는다. ㉯ — 부딪치지 않는다. ㉰ — 넘어지지 않는다. ㉱ — 빨리 오갈 수 있다. ㉲ — 계단에서는 오른쪽으로 다니자. 중심 생각은 「계단에서는 오른쪽으로 다니자.」이다.","scoring_points":["문단별 중심 내용을 정리했는가","까닭과 중심 생각을 가렸는가","중심 생각을 바르게 썼는가"]},"explanation":["문단마다 하나","까닭 셋","중심 생각"],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_b#25','kor',4,1,'u4','','g4_1_kor_u4_review_b','unit_review','K4-1-u4-C53',4,'essay','teacher','「국수」와 「옷장」이 어떻게 소리 나는지 쓰고, 소리와 적는 모양이 다른 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u4-C53","difficulty":4,"kind":"essay","stem":"「국수」와 「옷장」이 어떻게 소리 나는지 쓰고, 소리와 적는 모양이 다른 까닭을 쓰세요.","answer_guide":{"answer":"예: 「국수」는 [국쑤], 「옷장」은 [옫짱]으로 소리 난다. 앞 글자 받침 뒤의 소리가 된소리로 나기 때문에 소리가 달라지지만, 적을 때는 낱말의 원래 모양을 지켜 「국수」, 「옷장」으로 적는다.","scoring_points":["두 낱말의 소리를 바르게 썼는가","받침 뒤 된소리를 짚었는가","원래 모양대로 적는다고 썼는가"]},"explanation":["[국쑤] · [옫짱]","된소리","원래 모양"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#1','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C6',1,'mc','auto','「말을 타다.」와 「말을 하다.」의 「말」은 무엇인가요?',ARRAY['K4-1-u4-X09','K4-1-u4-X02','K4-1-u4-X08']::text[],false,'{"seq":1,"concept":"K4-1-u4-C6","difficulty":1,"kind":"mc","stem":"「말을 타다.」와 「말을 하다.」의 「말」은 무엇인가요?","options":[{"t":"뜻이 이어지지 않는 동형이의어","correct":true},{"t":"뜻이 이어진 다의어","mis":"K4-1-u4-X09"},{"t":"뜻이 같은 한 낱말","mis":"K4-1-u4-X02"},{"t":"글자가 다른 두 낱말","mis":"K4-1-u4-X08"}],"explanation":["짐승과 소리","이어지나요?","동형이의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#2','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C3',1,'mc','auto','「산 아래 굴 속은 어두컴컴했다.」에서 「굴」의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X03','K4-1-u4-X02']::text[],false,'{"seq":2,"concept":"K4-1-u4-C3","difficulty":1,"kind":"mc","stem":"「산 아래 굴 속은 어두컴컴했다.」에서 「굴」의 뜻은 무엇인가요?","options":[{"t":"땅이나 바위가 깊이 패어 들어간 곳","correct":true},{"t":"바닷가 바위에 붙어 사는 먹을거리","mis":"K4-1-u4-X03"},{"t":"사람이 다니는 곳","mis":"K4-1-u4-X03"},{"t":"「굴」은 뜻이 하나뿐이다","mis":"K4-1-u4-X02"}],"explanation":["「속은 어두컴컴」","들어갈 수 있는 곳","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#3','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C16',1,'mc','auto','「깊어서」를 국어사전에서 찾을 때 알맞은 모양은 무엇인가요?',ARRAY['K4-1-u4-X15']::text[],false,'{"seq":3,"concept":"K4-1-u4-C16","difficulty":1,"kind":"mc","stem":"「깊어서」를 국어사전에서 찾을 때 알맞은 모양은 무엇인가요?","options":[{"t":"깊다","correct":true},{"t":"깊어서","mis":"K4-1-u4-X15"},{"t":"깊어","mis":"K4-1-u4-X15"},{"t":"깊은","mis":"K4-1-u4-X15"}],"explanation":["기본형으로","「-다」","깊다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#4','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C26',1,'mc','auto','운동장 건너편 나무 위의 새집을 둘이 함께 바라보며 가리킬 때 알맞은 말은 무엇인가요?',ARRAY['K4-1-u4-X21','K4-1-u4-X20']::text[],false,'{"seq":4,"concept":"K4-1-u4-C26","difficulty":1,"kind":"mc","stem":"운동장 건너편 나무 위의 새집을 둘이 함께 바라보며 가리킬 때 알맞은 말은 무엇인가요?","options":[{"t":"저것","correct":true},{"t":"이것","mis":"K4-1-u4-X21"},{"t":"그것","mis":"K4-1-u4-X21"},{"t":"새집","mis":"K4-1-u4-X20"}],"explanation":["둘 다에게서 멀어요.","건너편","저것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#5','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C28',1,'mc','auto','「할머니께서 목도리를 떠 주셨다. 나는 그것을 날마다 두르고 다닌다.」에서 「그것」이 가리키는 것은 무엇인가요?',ARRAY['K4-1-u4-X23']::text[],false,'{"seq":5,"concept":"K4-1-u4-C28","difficulty":1,"kind":"mc","stem":"「할머니께서 목도리를 떠 주셨다. 나는 그것을 날마다 두르고 다닌다.」에서 「그것」이 가리키는 것은 무엇인가요?","options":[{"t":"할머니께서 떠 주신 목도리","correct":true},{"t":"할머니","mis":"K4-1-u4-X23"},{"t":"날마다","mis":"K4-1-u4-X23"},{"t":"뜨개질하는 방법","mis":"K4-1-u4-X23"}],"explanation":["무엇을 두르나요?","바로 앞 문장","목도리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#6','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C33',1,'mc','auto','제목 「다시 올라간 깃발」에서 짐작할 수 있는 것은 무엇인가요?',ARRAY['K4-1-u4-X28','K4-1-u4-X29']::text[],false,'{"seq":6,"concept":"K4-1-u4-C33","difficulty":1,"kind":"mc","stem":"제목 「다시 올라간 깃발」에서 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"깃발이 못 올라갈 뻔했다가 다시 올라간 일이 중요하다","correct":true},{"t":"제목은 이야기와 상관이 없다","mis":"K4-1-u4-X28"},{"t":"깃발의 색깔이 가장 중요하다","mis":"K4-1-u4-X28"},{"t":"운동회가 열리지 않았다","mis":"K4-1-u4-X29"}],"explanation":["「다시」","무엇이 올라갔나요?","첫째예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#7','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C44',1,'mc','auto','「계단에서는 오른쪽으로 다녀요」 ㉰ 문단의 중심 내용은 무엇인가요?',ARRAY['K4-1-u4-X37','K4-1-u4-X39']::text[],false,'{"seq":7,"concept":"K4-1-u4-C44","difficulty":1,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」 ㉰ 문단의 중심 내용은 무엇인가요?","options":[{"t":"오른쪽으로 다니면 넘어지지 않는다","correct":true},{"t":"오른쪽으로 다니면 부딪치지 않는다","mis":"K4-1-u4-X37"},{"t":"계단이 막히지 않는다","mis":"K4-1-u4-X37"},{"t":"㉰에는 중심 내용이 없다","mis":"K4-1-u4-X39"}],"explanation":["㉰의 첫 문장","둘째 까닭","넘어지지 않아요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#8','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C54',1,'mc','auto','「소고기」와 함께 쓸 수 있는 바른 말은 무엇인가요?',ARRAY['K4-1-u4-X49','K4-1-u4-X50']::text[],false,'{"seq":8,"concept":"K4-1-u4-C54","difficulty":1,"kind":"mc","stem":"「소고기」와 함께 쓸 수 있는 바른 말은 무엇인가요?","options":[{"t":"쇠고기","correct":true},{"t":"소괴기","mis":"K4-1-u4-X49"},{"t":"「소고기」만 바른 말이라 함께 쓸 말이 없다","mis":"K4-1-u4-X50"},{"t":"쇠괴기","mis":"K4-1-u4-X49"}],"explanation":["둘 다 바른 말","소리만 비슷한 말은?","쇠고기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#9','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C8',2,'mc','auto','「끈을 풀다 / 문제를 풀다」를 동형이의어라고 한 친구에게 알맞게 고쳐 준 말은 무엇인가요?',ARRAY['K4-1-u4-X08','K4-1-u4-X07','K4-1-u4-X09']::text[],false,'{"seq":9,"concept":"K4-1-u4-C8","difficulty":2,"kind":"mc","stem":"「끈을 풀다 / 문제를 풀다」를 동형이의어라고 한 친구에게 알맞게 고쳐 준 말은 무엇인가요?","options":[{"t":"「묶인 것을 끄르는 뜻이 어려운 것의 답을 찾는 뜻으로 넓어졌으니 다의어야.」","correct":true},{"t":"「글자가 같으니 동형이의어가 맞아.」","mis":"K4-1-u4-X08"},{"t":"「두 뜻은 아무 상관이 없어.」","mis":"K4-1-u4-X07"},{"t":"「뜻이 이어지면 동형이의어야.」","mis":"K4-1-u4-X09"}],"explanation":["뜻이 이어졌나요?","넓어진 뜻","다의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#10','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C18',2,'mc','auto','국어사전에 「가볍다」가 「1」, 「2」로 실려 있다면 「가볍다」는 무엇인가요?',ARRAY['K4-1-u4-X11','K4-1-u4-X20','K4-1-u4-X02']::text[],false,'{"seq":10,"concept":"K4-1-u4-C18","difficulty":2,"kind":"mc","stem":"국어사전에 「가볍다」가 「1」, 「2」로 실려 있다면 「가볍다」는 무엇인가요?","options":[{"t":"다의어","correct":true},{"t":"동형이의어","mis":"K4-1-u4-X11"},{"t":"가리키는 말","mis":"K4-1-u4-X20"},{"t":"뜻이 하나인 낱말","mis":"K4-1-u4-X02"}],"explanation":["한 낱말 안에","「1」 「2」","다의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#11','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C12',2,'mc','auto','「냄비에서 김이 오른다.」와 「유리창에 김이 서렸다.」의 「김」을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X12','K4-1-u4-X03','K4-1-u4-X02']::text[],false,'{"seq":11,"concept":"K4-1-u4-C12","difficulty":2,"kind":"mc","stem":"「냄비에서 김이 오른다.」와 「유리창에 김이 서렸다.」의 「김」을 바르게 말한 것은 무엇인가요?","options":[{"t":"오르는 김과 서린 김은 뜻이 이어져 있다","correct":true},{"t":"「김」은 늘 동형이의어이니 이 둘도 동형이의어이다","mis":"K4-1-u4-X12"},{"t":"둘 다 바다에서 나는 먹을거리이다","mis":"K4-1-u4-X03"},{"t":"글자가 같으니 뜻도 똑같다","mis":"K4-1-u4-X02"}],"explanation":["오르는 김 → 서린 김","이어져 있어요.","늘 한쪽은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#12','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C22',2,'mc','auto','「가볍다」를 살려 지은 문구로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X13','K4-1-u4-X18','K4-1-u4-X19']::text[],false,'{"seq":12,"concept":"K4-1-u4-C22","difficulty":2,"kind":"mc","stem":"「가볍다」를 살려 지은 문구로 알맞은 것은 무엇인가요?","options":[{"t":"「가벼운 가방, 가벼운 마음으로 소풍 가요!」","correct":true},{"t":"「가벼운 가방, 가벼운 공책을 챙겨요!」","mis":"K4-1-u4-X13"},{"t":"「소풍 가방을 챙겨요!」","mis":"K4-1-u4-X18"},{"t":"「가볍다는 말은 광고에 쓰면 안 돼요!」","mis":"K4-1-u4-X19"}],"explanation":["무게와 마음","두 뜻을 함께","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#13','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C31',2,'mc','auto','가리키는 말로 바꾸어 쓸 때 알맞은 방법은 무엇인가요?',ARRAY['K4-1-u4-X26','K4-1-u4-X25']::text[],false,'{"seq":13,"concept":"K4-1-u4-C31","difficulty":2,"kind":"mc","stem":"가리키는 말로 바꾸어 쓸 때 알맞은 방법은 무엇인가요?","options":[{"t":"처음 나온 말은 그대로 두고, 다시 나올 때 가리키는 말로 바꾼다","correct":true},{"t":"처음 나오는 말부터 가리키는 말로 바꾼다","mis":"K4-1-u4-X26"},{"t":"글에 나오는 낱말을 모두 가리키는 말로 바꾼다","mis":"K4-1-u4-X26"},{"t":"가리키는 말은 글에 쓰지 않는다","mis":"K4-1-u4-X25"}],"explanation":["처음은 그대로","다시 나올 때","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#14','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C36',2,'mc','auto','「다시 올라간 깃발」의 중심 생각을 찾을 때 함께 살필 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X27','K4-1-u4-X33','K4-1-u4-X30']::text[],false,'{"seq":14,"concept":"K4-1-u4-C36","difficulty":2,"kind":"mc","stem":"「다시 올라간 깃발」의 중심 생각을 찾을 때 함께 살필 것으로 알맞은 것은 무엇인가요?","options":[{"t":"제목, 깃발을 함께 묶은 줄거리, 서진이의 말과 민우의 웃음","correct":true},{"t":"민우가 숙인 고개 하나","mis":"K4-1-u4-X27"},{"t":"우산꽂이가 놓인 자리","mis":"K4-1-u4-X33"},{"t":"모둠 친구들의 이름","mis":"K4-1-u4-X30"}],"explanation":["제목 · 줄거리 · 말과 행동","모두 모아요.","첫째예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#15','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C50',2,'mc','auto','「계단에서는 오른쪽으로 다녀요」를 읽고 정한 다짐으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X44']::text[],false,'{"seq":15,"concept":"K4-1-u4-C50","difficulty":2,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」를 읽고 정한 다짐으로 알맞은 것은 무엇인가요?","options":[{"t":"계단에서는 오른쪽으로 천천히 다니겠다","correct":true},{"t":"계단에서 빨리 뛰어 내려가겠다","mis":"K4-1-u4-X44"},{"t":"쉬는 시간에 책을 읽겠다","mis":"K4-1-u4-X44"},{"t":"계단의 수를 세어 보겠다","mis":"K4-1-u4-X44"}],"explanation":["중심 생각에서 나온 다짐","오른쪽으로","첫째예요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#16','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C52',2,'mc','auto','「학교 앞에 그늘막이 생겼어요」의 문단별 중심 내용을 모아 정한 기사의 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X46','K4-1-u4-X33']::text[],false,'{"seq":16,"concept":"K4-1-u4-C52","difficulty":2,"kind":"mc","stem":"「학교 앞에 그늘막이 생겼어요」의 문단별 중심 내용을 모아 정한 기사의 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"더위를 피해 안전하게 신호를 기다리자","correct":true},{"t":"그늘막은 지난주에 세워졌다","mis":"K4-1-u4-X46"},{"t":"그늘막 아래는 온도가 낮다","mis":"K4-1-u4-X46"},{"t":"횡단보도를 빨리 건너자","mis":"K4-1-u4-X33"}],"explanation":["작은 사실 말고","모아서","첫째예요."],"asset":{"type":"passage","lines":["① 지난주 한별초등학교 앞 횡단보도에 그늘막이 세워졌다.","② 한여름 낮에는 신호를 기다리는 동안 햇볕이 뜨거워 힘들다는 의견이 많았다.","③ 그늘막 아래 온도는 볕이 드는 곳보다 훨씬 낮게 나타났다.","④ 학교에서는 그늘막 안에서 차례를 지켜 기다려 달라고 안내했다."],"title":"학교 앞에 그늘막이 생겼어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#17','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C17',3,'mc','auto','「설거지를 마치니 마음이 가볍다.」의 「가볍다」에 알맞은 사전의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X16','K4-1-u4-X03']::text[],false,'{"seq":17,"concept":"K4-1-u4-C17","difficulty":3,"kind":"mc","stem":"「설거지를 마치니 마음이 가볍다.」의 「가볍다」에 알맞은 사전의 뜻은 무엇인가요?","options":[{"t":"「2」 마음이 홀가분하다","correct":true},{"t":"「1」 무게가 적다","mis":"K4-1-u4-X16"},{"t":"풀² 종이 같은 것을 붙이는 데 쓰는 끈끈한 것","mis":"K4-1-u4-X03"},{"t":"사전 첫 뜻이니 「1」이다","mis":"K4-1-u4-X16"}],"explanation":["무엇이 가볍나요?","마음","「2」예요."],"asset":{"type":"passage","lines":["풀¹ 땅에서 자라는, 줄기가 연한 작은 식물. 예 풀을 뽑다.","풀² 종이 같은 것을 붙이는 데 쓰는 끈끈한 것. 예 풀로 붙이다.","가볍다 「1」 무게가 적다. 「2」 마음이 홀가분하다."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#18','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C36',3,'mc','auto','「다시 올라간 깃발」 ⑦ 민우가 깃발을 가장 높이 든 행동이 중심 생각을 찾는 데 주는 도움은 무엇인가요?',ARRAY['K4-1-u4-X30','K4-1-u4-X03','K4-1-u4-X27']::text[],false,'{"seq":18,"concept":"K4-1-u4-C36","difficulty":3,"kind":"mc","stem":"「다시 올라간 깃발」 ⑦ 민우가 깃발을 가장 높이 든 행동이 중심 생각을 찾는 데 주는 도움은 무엇인가요?","options":[{"t":"친구들 덕분에 다시 힘을 냈다는 것을 보여 준다","correct":true},{"t":"민우의 키가 크다는 것을 알려 준다","mis":"K4-1-u4-X30"},{"t":"깃발이 무겁다는 것만 알려 준다","mis":"K4-1-u4-X03"},{"t":"행동은 중심 생각과 상관이 없다","mis":"K4-1-u4-X27"}],"explanation":["③과 견줘요.","숙인 고개 → 높이 든 깃발","다시 힘을 냈어요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#19','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C44',3,'mc','auto','「책상 서랍을 정리해요」 ㉱ 문단의 중심 내용으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X38','K4-1-u4-X37']::text[],false,'{"seq":19,"concept":"K4-1-u4-C44","difficulty":3,"kind":"mc","stem":"「책상 서랍을 정리해요」 ㉱ 문단의 중심 내용으로 알맞은 것은 무엇인가요?","options":[{"t":"서랍을 정리하면 공부에 집중할 수 있다","correct":true},{"t":"책상 둘레가 깨끗하면 마음이 차분해진다","mis":"K4-1-u4-X38"},{"t":"물건을 빨리 찾을 수 있다","mis":"K4-1-u4-X37"},{"t":"서랍을 오 분 만에 정리하자","mis":"K4-1-u4-X37"}],"explanation":["㉱의 첫 문장","셋째 까닭","집중할 수 있어요."],"asset":{"type":"passage","lines":["㉮ 책상 서랍 속이 뒤죽박죽인 친구가 많아요. 서랍을 정리하면 어떤 점이 좋을까요?","㉯ 첫째, 물건을 빨리 찾을 수 있어요. 자리를 정해 두면 찾느라 시간을 쓰지 않아요.","㉰ 둘째, 물건을 잃어버리지 않아요. 서랍이 깔끔하면 없어진 물건이 바로 보여요.","㉱ 셋째, 공부에 집중할 수 있어요. 책상 둘레가 깨끗하면 마음도 차분해져요.","㉲ 오늘부터 책상 서랍을 정리해 보세요. 쉬는 시간 오 분이면 충분해요."],"title":"책상 서랍을 정리해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#20','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C49',3,'mc','auto','이야기와 주장하는 글의 중심 생각 찾기를 바르게 말한 친구는 누구인가요?',ARRAY['K4-1-u4-X42','K4-1-u4-X43']::text[],false,'{"seq":20,"concept":"K4-1-u4-C49","difficulty":3,"kind":"mc","stem":"이야기와 주장하는 글의 중심 생각 찾기를 바르게 말한 친구는 누구인가요?","options":[{"t":"지안 — 「이야기는 인물의 말과 행동을, 주장하는 글은 문단별 중심 내용을 꼭 살펴.」","correct":true},{"t":"서진 — 「두 글 모두 인물의 말만 보면 돼.」","mis":"K4-1-u4-X42"},{"t":"윤호 — 「주장하는 글에는 인물이 없으니 중심 생각도 없어.」","mis":"K4-1-u4-X42"},{"t":"채아 — 「이야기는 글자 수를 세면 돼.」","mis":"K4-1-u4-X43"}],"explanation":["글의 종류에 따라","살피는 자리","지안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#21','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C28',3,'mc','auto','「자전거가 주는 도움」에서 가리키는 말과 그것이 가리키는 내용을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u4-X23','K4-1-u4-X20','K4-1-u4-X22']::text[],false,'{"seq":21,"concept":"K4-1-u4-C28","difficulty":3,"kind":"mc","stem":"「자전거가 주는 도움」에서 가리키는 말과 그것이 가리키는 내용을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"「이것」 — 몸이 튼튼해지고 빠르게 다녀오는 것","correct":true},{"t":"「이것」 — 공기를 맑게 지켜 주는 것","mis":"K4-1-u4-X23"},{"t":"「이것」 — 자전거라는 이름","mis":"K4-1-u4-X20"},{"t":"글에서는 가리키는 말을 쓸 수 없다","mis":"K4-1-u4-X22"}],"explanation":["「이것」 바로 앞","도움 두 가지","첫째예요."],"asset":{"type":"passage","lines":["자전거는 우리에게 여러 가지 도움을 준다.","자전거를 타면 몸이 튼튼해진다.","가까운 곳은 빠르게 다녀올 수도 있다.","자전거가 주는 도움은 이것만이 아니다.","매연이 나오지 않아 공기도 맑게 지켜 준다."],"title":"자전거가 주는 도움"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#22','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C53',3,'mc','auto','된소리로 소리 나는 낱말만 모은 것은 무엇인가요?',ARRAY['K4-1-u4-X48','K4-1-u4-X47']::text[],false,'{"seq":22,"concept":"K4-1-u4-C53","difficulty":3,"kind":"mc","stem":"된소리로 소리 나는 낱말만 모은 것은 무엇인가요?","options":[{"t":"덮개 · 목소리 · 잡지","correct":true},{"t":"노래 · 덮개 · 하늘","mis":"K4-1-u4-X48"},{"t":"오리 · 구름 · 바다","mis":"K4-1-u4-X48"},{"t":"[덥깨]로 소리 나니 「덥깨」로 적는다","mis":"K4-1-u4-X47"}],"explanation":["[덥깨] · [목쏘리] · [잡찌]","받침 뒤 소리","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#23','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C16',4,'essay','teacher','「화단 정리하는 날」 ⑤의 「풀어」를 국어사전에서 찾는 방법을 쓰고, 이 문장에 알맞은 뜻을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u4-C16","difficulty":4,"kind":"essay","stem":"「화단 정리하는 날」 ⑤의 「풀어」를 국어사전에서 찾는 방법을 쓰고, 이 문장에 알맞은 뜻을 쓰세요.","answer_guide":{"answer":"예: 「풀어」의 기본형인 「풀다」로 사전을 찾는다. 이 문장에서는 묶인 매듭을 끄른다는 뜻이다. 앞에 「매듭이 단단해」라는 말이 있기 때문이다.","scoring_points":["기본형으로 찾는다고 썼는가","「풀다」라고 바르게 썼는가","문장에 알맞은 뜻을 썼는가"]},"explanation":["기본형","풀다","매듭을 끄르다"],"asset":{"type":"passage","lines":["① 토요일에 지안이는 아빠와 화단의 풀을 뽑았다.","② 뽑은 풀은 바구니에 담아 담장 옆에 두었다.","③ 오후에는 화단에 꽂을 이름표를 만들려고 풀을 꺼냈다.","④ 색종이에 풀을 바르고 나무 막대에 붙였다.","⑤ 막대를 묶은 끈은 매듭이 단단해 아빠가 풀어 주셨다.","⑥ 일을 다 마치고 나니 마음이 가벼웠다."],"title":"화단 정리하는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#24','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C49',4,'essay','teacher','이야기와 주장하는 글에서 중심 생각을 찾는 방법이 어떻게 다른지 쓰고, 그렇게 다른 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u4-C49","difficulty":4,"kind":"essay","stem":"이야기와 주장하는 글에서 중심 생각을 찾는 방법이 어떻게 다른지 쓰고, 그렇게 다른 까닭을 쓰세요.","answer_guide":{"answer":"예: 이야기는 제목, 줄거리, 인물의 말과 행동을 모아 중심 생각을 찾고, 주장하는 글은 중요한 낱말과 문단별 중심 내용, 글쓴이의 생각이 드러난 첫 문단과 마지막 문단을 살핀다. 이야기는 인물과 사건으로 생각을 전하고, 주장하는 글은 까닭을 들어 생각을 밝히기 때문이다.","scoring_points":["이야기에서 살필 것을 썼는가","주장하는 글에서 살필 것을 썼는가","다른 까닭을 썼는가"]},"explanation":["이야기","주장하는 글","왜 다를까요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_c#25','kor',4,1,'u4','','g4_1_kor_u4_review_c','unit_review','K4-1-u4-C54',4,'essay','teacher','함께 쓰는 바른 말의 짝 두 가지를 쓰고, 「설겆이」가 바른 말이 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u4-C54","difficulty":4,"kind":"essay","stem":"함께 쓰는 바른 말의 짝 두 가지를 쓰고, 「설겆이」가 바른 말이 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 자장면 — 짜장면, 넝쿨 — 덩굴. 「설겆이」는 「설거지」와 소리가 비슷하지만 바른 말은 「설거지」 하나뿐이어서 바른 말이 아니다.","scoring_points":["함께 쓰는 짝 두 가지를 썼는가","설거지가 바른 말이라고 썼는가","소리가 비슷하다고 다 바른 말은 아니라고 썼는가"]},"explanation":["둘 다 바른 짝","설거지","소리만 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#1','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C7',1,'mc','auto','「물이 맑다.」와 「목소리가 맑다.」의 「맑다」는 무엇인가요?',ARRAY['K4-1-u4-X06','K4-1-u4-X07','K4-1-u4-X02']::text[],false,'{"seq":1,"concept":"K4-1-u4-C7","difficulty":1,"kind":"mc","stem":"「물이 맑다.」와 「목소리가 맑다.」의 「맑다」는 무엇인가요?","options":[{"t":"뜻이 이어진 다의어","correct":true},{"t":"뜻이 이어지지 않는 동형이의어","mis":"K4-1-u4-X06"},{"t":"뜻이 서로 아무 상관이 없는 두 낱말","mis":"K4-1-u4-X07"},{"t":"어디에 쓰여도 뜻이 같은 낱말","mis":"K4-1-u4-X02"}],"explanation":["깨끗한 물","깨끗한 소리","다의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#2','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C14',1,'mc','auto','「아빠와 바닷가에서 굴을 따서 바구니에 담았다.」에서 「굴」의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X03','K4-1-u4-X02']::text[],false,'{"seq":2,"concept":"K4-1-u4-C14","difficulty":1,"kind":"mc","stem":"「아빠와 바닷가에서 굴을 따서 바구니에 담았다.」에서 「굴」의 뜻은 무엇인가요?","options":[{"t":"바닷가 바위에 붙어 사는 먹을거리","correct":true},{"t":"땅이나 바위가 깊이 패어 들어간 곳","mis":"K4-1-u4-X03"},{"t":"산속의 좁은 길","mis":"K4-1-u4-X03"},{"t":"「굴」은 어디서나 뜻이 같다","mis":"K4-1-u4-X02"}],"explanation":["따서 담았어요.","바닷가","먹을거리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#3','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C16',1,'mc','auto','「열면」을 국어사전에서 찾을 때 알맞은 모양은 무엇인가요?',ARRAY['K4-1-u4-X15']::text[],false,'{"seq":3,"concept":"K4-1-u4-C16","difficulty":1,"kind":"mc","stem":"「열면」을 국어사전에서 찾을 때 알맞은 모양은 무엇인가요?","options":[{"t":"열다","correct":true},{"t":"열면","mis":"K4-1-u4-X15"},{"t":"열어","mis":"K4-1-u4-X15"},{"t":"연","mis":"K4-1-u4-X15"}],"explanation":["기본형으로","「-다」","열다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#4','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C26',1,'mc','auto','「저것」을 쓰는 때로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X21','K4-1-u4-X20']::text[],false,'{"seq":4,"concept":"K4-1-u4-C26","difficulty":1,"kind":"mc","stem":"「저것」을 쓰는 때로 알맞은 것은 무엇인가요?","options":[{"t":"말하는 사람과 듣는 사람 모두에게서 멀리 있을 때","correct":true},{"t":"말하는 사람에게 가까울 때","mis":"K4-1-u4-X21"},{"t":"듣는 사람에게 가까울 때","mis":"K4-1-u4-X21"},{"t":"물건의 이름을 모를 때만","mis":"K4-1-u4-X20"}],"explanation":["이 · 그 · 저","저는 멀리","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#5','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C28',1,'mc','auto','가리키는 말이 가리키는 내용은 대부분 어디에 있나요?',ARRAY['K4-1-u4-X23']::text[],false,'{"seq":5,"concept":"K4-1-u4-C28","difficulty":1,"kind":"mc","stem":"가리키는 말이 가리키는 내용은 대부분 어디에 있나요?","options":[{"t":"가리키는 말의 바로 앞","correct":true},{"t":"글의 제목","mis":"K4-1-u4-X23"},{"t":"글의 맨 끝","mis":"K4-1-u4-X23"},{"t":"다른 책","mis":"K4-1-u4-X23"}],"explanation":["앞뒤 문장","대부분은","바로 앞이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#6','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C34',1,'mc','auto','「다시 올라간 깃발」에서 실제로 있었던 일은 무엇인가요?',ARRAY['K4-1-u4-X29']::text[],false,'{"seq":6,"concept":"K4-1-u4-C34","difficulty":1,"kind":"mc","stem":"「다시 올라간 깃발」에서 실제로 있었던 일은 무엇인가요?","options":[{"t":"모둠 친구들이 깃발을 막대에 함께 묶었다","correct":true},{"t":"선생님이 새 깃대를 사 주셨다","mis":"K4-1-u4-X29"},{"t":"민우가 집에 가서 깃대를 가져왔다","mis":"K4-1-u4-X29"},{"t":"서진이가 민우를 꾸짖었다","mis":"K4-1-u4-X29"}],"explanation":["이야기에 나왔나요?","⑥을 봐요.","첫째예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#7','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C48',1,'mc','auto','「계단에서는 오른쪽으로 다녀요」의 중심 생각은 무엇인가요?',ARRAY['K4-1-u4-X41','K4-1-u4-X31']::text[],false,'{"seq":7,"concept":"K4-1-u4-C48","difficulty":1,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」의 중심 생각은 무엇인가요?","options":[{"t":"계단에서는 오른쪽으로 다니자","correct":true},{"t":"계단은 쉬는 시간에 붐빈다","mis":"K4-1-u4-X41"},{"t":"오른쪽으로 다니면 빨리 오갈 수 있다","mis":"K4-1-u4-X41"},{"t":"쉬는 시간을 늘리자","mis":"K4-1-u4-X31"}],"explanation":["까닭 셋이 받쳐 주는 생각","마지막 문단","오른쪽으로 다니자"],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#8','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C54',1,'mc','auto','「짜장면」을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X50','K4-1-u4-X49']::text[],false,'{"seq":8,"concept":"K4-1-u4-C54","difficulty":1,"kind":"mc","stem":"「짜장면」을 바르게 말한 것은 무엇인가요?","options":[{"t":"「자장면」과 함께 쓰는 바른 말이다","correct":true},{"t":"틀린 말이라 쓰면 안 된다","mis":"K4-1-u4-X50"},{"t":"「자장면」만 바른 말이다","mis":"K4-1-u4-X50"},{"t":"소리가 비슷한 말은 모두 바른 말이다","mis":"K4-1-u4-X49"}],"explanation":["둘 다 바른 말","자장면 · 짜장면","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#9','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C8',2,'mc','auto','두 낱말이 동형이의어인지 다의어인지 가를 때 따져야 할 것은 무엇인가요?',ARRAY['K4-1-u4-X08','K4-1-u4-X09']::text[],false,'{"seq":9,"concept":"K4-1-u4-C8","difficulty":2,"kind":"mc","stem":"두 낱말이 동형이의어인지 다의어인지 가를 때 따져야 할 것은 무엇인가요?","options":[{"t":"두 뜻 사이에 이어짐이 있는지","correct":true},{"t":"두 낱말의 소리가 같은지","mis":"K4-1-u4-X08"},{"t":"두 낱말의 받침이 같은지","mis":"K4-1-u4-X08"},{"t":"뜻이 이어지면 동형이의어로 정하기","mis":"K4-1-u4-X09"}],"explanation":["글자와 소리는 둘 다 같아요.","뜻의 이어짐","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#10','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C18',2,'mc','auto','국어사전에 굴¹, 굴²처럼 실린 낱말은 무엇인가요?',ARRAY['K4-1-u4-X10','K4-1-u4-X15']::text[],false,'{"seq":10,"concept":"K4-1-u4-C18","difficulty":2,"kind":"mc","stem":"국어사전에 굴¹, 굴²처럼 실린 낱말은 무엇인가요?","options":[{"t":"동형이의어","correct":true},{"t":"다의어","mis":"K4-1-u4-X10"},{"t":"기본형이 아닌 낱말","mis":"K4-1-u4-X15"},{"t":"잘못 실린 낱말","mis":"K4-1-u4-X10"}],"explanation":["번호를 붙여 따로","서로 다른 낱말","동형이의어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#11','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C19',2,'mc','auto','「빵집에 가는 길」을 읽은 친구의 말로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X17','K4-1-u4-X18','K4-1-u4-X03']::text[],false,'{"seq":11,"concept":"K4-1-u4-C19","difficulty":2,"kind":"mc","stem":"「빵집에 가는 길」을 읽은 친구의 말로 알맞은 것은 무엇인가요?","options":[{"t":"「앞의 김은 빵에서 나는 흰 기운이고, 뒤의 김은 봉지에 든 먹을거리야.」","correct":true},{"t":"「한 이야기에 나왔으니 두 김은 같은 뜻이야.」","mis":"K4-1-u4-X17"},{"t":"「김이 두 번 나와서 하나는 잘못 쓴 거야.」","mis":"K4-1-u4-X18"},{"t":"「두 김 모두 빵에서 나는 흰 기운이야.」","mis":"K4-1-u4-X03"}],"explanation":["③과 ⑤","자리마다 다른 뜻","첫째예요."],"asset":{"type":"passage","lines":["① 학교가 끝나고 할머니와 빵집에 가는 길이었다.","② 골목이 좁은 길이라 우리는 나란히 걷지 못했다.","③ 빵집 문을 열자 따뜻한 김이 확 끼쳤다.","④ \"갓 구운 빵이라 아직 김이 나네.\" 주인아저씨가 웃으셨다.","⑤ 할머니는 빵과 함께 김 한 봉지도 담으셨다.","⑥ \"이 빵집을 어떻게 아셨어요?\" \"좋은 길은 물어물어 찾는 거란다.\"","⑦ 집으로 돌아오는 길에 나는 빵 봉지를 꼭 안았다."],"title":"빵집에 가는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#12','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C20',2,'mc','auto','「마음의 문을 열어요」라는 학급 표어를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X18','K4-1-u4-X03']::text[],false,'{"seq":12,"concept":"K4-1-u4-C20","difficulty":2,"kind":"mc","stem":"「마음의 문을 열어요」라는 학급 표어를 바르게 말한 것은 무엇인가요?","options":[{"t":"문을 여는 뜻을 넓혀 마음을 터놓자는 뜻을 함께 전한다","correct":true},{"t":"교실 문을 활짝 열어 두자는 뜻만 전한다","mis":"K4-1-u4-X18"},{"t":"「열다」를 잘못 쓴 표어이다","mis":"K4-1-u4-X18"},{"t":"마음에는 문이 없으니 뜻이 없다","mis":"K4-1-u4-X03"}],"explanation":["문을 열다 → 마음을 열다","넓어진 뜻","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#13','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C30',2,'mc','auto','「우리 모둠 화분」 ④에서 「이것」 대신 「날마다 화분에 물을 주고 흙을 살피는 일」을 다시 쓰면 어떻게 되나요?',ARRAY['K4-1-u4-X25']::text[],false,'{"seq":13,"concept":"K4-1-u4-C30","difficulty":2,"kind":"mc","stem":"「우리 모둠 화분」 ④에서 「이것」 대신 「날마다 화분에 물을 주고 흙을 살피는 일」을 다시 쓰면 어떻게 되나요?","options":[{"t":"같은 말이 되풀이되어 글이 길고 덜 매끄러워진다","correct":true},{"t":"글의 뜻이 반대로 바뀐다","mis":"K4-1-u4-X25"},{"t":"더 짧고 깔끔해진다","mis":"K4-1-u4-X25"},{"t":"서진이가 한 일이 달라진다","mis":"K4-1-u4-X25"}],"explanation":["③의 말이 또 나와요.","되풀이","첫째예요."],"asset":{"type":"passage","lines":["① 교실 뒤 선반에 작은 화분이 세 개 놓여 있다.","② 화분마다 우리 모둠이 심은 강낭콩이 자란다.","③ 서진이는 날마다 화분에 물을 주고 흙을 살핀다.","④ 이것은 서진이가 스스로 맡은 일이다.","⑤ 지난주에는 떡잎 사이로 본잎이 나왔다.","⑥ 우리 모둠은 그것을 보고 다 함께 기뻐했다."],"title":"우리 모둠 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#14','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C38',2,'mc','auto','「다시 올라간 깃발」의 줄거리와 중심 생각을 바르게 나눈 것은 무엇인가요?',ARRAY['K4-1-u4-X32','K4-1-u4-X31']::text[],false,'{"seq":14,"concept":"K4-1-u4-C38","difficulty":2,"kind":"mc","stem":"「다시 올라간 깃발」의 줄거리와 중심 생각을 바르게 나눈 것은 무엇인가요?","options":[{"t":"줄거리 — 깃대가 없어 막대로 대신했다 / 중심 생각 — 함께 방법을 찾으면 다시 힘을 낼 수 있다","correct":true},{"t":"줄거리와 중심 생각은 같은 말이다","mis":"K4-1-u4-X32"},{"t":"줄거리 — 함께 힘을 내자 / 중심 생각 — 깃대를 두고 왔다","mis":"K4-1-u4-X32"},{"t":"중심 생각 — 운동회는 재미있다","mis":"K4-1-u4-X31"}],"explanation":["있었던 일","전하려는 생각","첫째예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#15','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C45',2,'mc','auto','「계단에서는 오른쪽으로 다녀요」 ㉯의 중심 문장은 무엇인가요?',ARRAY['K4-1-u4-X38','K4-1-u4-X37']::text[],false,'{"seq":15,"concept":"K4-1-u4-C45","difficulty":2,"kind":"mc","stem":"「계단에서는 오른쪽으로 다녀요」 ㉯의 중심 문장은 무엇인가요?","options":[{"t":"첫째, 부딪치지 않아요.","correct":true},{"t":"모두 오른쪽으로 다니면 마주칠 일이 줄어요.","mis":"K4-1-u4-X38"},{"t":"두 문장 모두 뒷받침 문장이다","mis":"K4-1-u4-X38"},{"t":"㉯에는 중심 문장이 두 개다","mis":"K4-1-u4-X37"}],"explanation":["하고 싶은 말","첫 문장","첫째예요."],"asset":{"type":"passage","lines":["㉮ 쉬는 시간 계단은 오르내리는 친구들로 붐벼요. 어떻게 하면 안전할까요?","㉯ 첫째, 부딪치지 않아요. 모두 오른쪽으로 다니면 마주칠 일이 줄어요.","㉰ 둘째, 넘어지지 않아요. 앞사람을 피하려고 몸을 돌리다 미끄러질 일이 없어요.","㉱ 셋째, 빨리 오갈 수 있어요. 한 방향으로 흐르니 계단이 막히지 않아요.","㉲ 계단에서는 오른쪽으로 다녀요. 우리 모두가 지키면 쉬는 시간이 더 안전해져요."],"title":"계단에서는 오른쪽으로 다녀요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#16','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C52',2,'mc','auto','신문 기사가 전하려는 생각을 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u4-X46','K4-1-u4-X43','K4-1-u4-X36']::text[],false,'{"seq":16,"concept":"K4-1-u4-C52","difficulty":2,"kind":"mc","stem":"신문 기사가 전하려는 생각을 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"제목과 본문에 함께 나오는 중요한 낱말과 문단별 중심 내용을 모은다","correct":true},{"t":"기사에 나온 숫자 하나를 고른다","mis":"K4-1-u4-X46"},{"t":"사진의 크기를 본다","mis":"K4-1-u4-X43"},{"t":"가장 마지막 낱말을 고른다","mis":"K4-1-u4-X36"}],"explanation":["중요한 낱말","문단별 중심 내용","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#17','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C17',3,'mc','auto','「이 문제를 푸는 길을 드디어 찾았다.」의 「길」에 알맞은 사전의 뜻은 무엇인가요?',ARRAY['K4-1-u4-X16','K4-1-u4-X03']::text[],false,'{"seq":17,"concept":"K4-1-u4-C17","difficulty":3,"kind":"mc","stem":"「이 문제를 푸는 길을 드디어 찾았다.」의 「길」에 알맞은 사전의 뜻은 무엇인가요?","options":[{"t":"「2」 일을 해내는 방법","correct":true},{"t":"「1」 사람이 다니는 곳","mis":"K4-1-u4-X16"},{"t":"「3」 어떤 일을 하는 도중","mis":"K4-1-u4-X03"},{"t":"김¹ 물이 끓을 때 생기는 흰 기운","mis":"K4-1-u4-X03"}],"explanation":["문제를 푸는 「무엇」?","방법","「2」예요."],"asset":{"type":"passage","lines":["김¹ 물이 끓을 때 생기는 흰 기운. 예 김이 오르다.","김² 바다에서 나는, 얇게 말려 먹는 것. 예 김을 굽다.","길 「1」 사람이 다니는 곳. 「2」 일을 해내는 방법. 「3」 어떤 일을 하는 도중."],"title":"국어사전"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#18','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C37',3,'mc','auto','「다시 올라간 깃발」의 중심 생각을 말한 친구 가운데 글에 근거한 말은 무엇인가요?',ARRAY['K4-1-u4-X31','K4-1-u4-X33','K4-1-u4-X28']::text[],false,'{"seq":18,"concept":"K4-1-u4-C37","difficulty":3,"kind":"mc","stem":"「다시 올라간 깃발」의 중심 생각을 말한 친구 가운데 글에 근거한 말은 무엇인가요?","options":[{"t":"지우 — 「서진이가 탓하지 않고 막대를 찾아와서 민우가 다시 웃었으니, 함께 방법을 찾자는 거야.」","correct":true},{"t":"지안 — 「우리 반도 운동회에서 이겼으니 열심히 하면 이긴다는 거야.」","mis":"K4-1-u4-X31"},{"t":"윤호 — 「우산꽂이가 나왔으니 우산을 잘 챙기자는 거야.」","mis":"K4-1-u4-X33"},{"t":"채아 — 「제목에 깃발이 있으니 깃발이 중심 생각이야.」","mis":"K4-1-u4-X28"}],"explanation":["글에 나온 말과 행동","서진 · 민우","지우예요."],"asset":{"type":"passage","lines":["① 운동회 날 아침, 서진이네 모둠은 모둠 깃발을 들고 나가기로 했다.","② 그런데 깃발을 맡은 민우가 깃대를 집에 두고 왔다.","③ 민우는 고개를 숙이고 \"나 때문에 다 망쳤어.\"라고 말했다.","④ 서진이가 교실 뒤 우산꽂이에서 긴 막대를 찾아왔다.","⑤ \"이걸로 하자. 깃발만 있으면 돼.\"","⑥ 모둠 친구들이 깃발을 막대에 함께 묶었다.","⑦ 민우는 다시 웃으며 깃발을 가장 높이 들었다."],"title":"다시 올라간 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#19','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C45',3,'mc','auto','문단의 짜임을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X37','K4-1-u4-X38','K4-1-u4-X39']::text[],false,'{"seq":19,"concept":"K4-1-u4-C45","difficulty":3,"kind":"mc","stem":"문단의 짜임을 바르게 말한 것은 무엇인가요?","options":[{"t":"한 문단에는 중심 문장 하나와 그것을 받쳐 주는 뒷받침 문장들이 있다","correct":true},{"t":"한 문단에는 중심 내용이 여러 개 있다","mis":"K4-1-u4-X37"},{"t":"뒷받침 문장이 문단에서 가장 하고 싶은 말이다","mis":"K4-1-u4-X38"},{"t":"문단에는 늘 중심 문장이 한 문장으로 쓰여 있다","mis":"K4-1-u4-X39"}],"explanation":["중심 문장 하나","뒷받침 문장들","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#20','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C49',3,'mc','auto','「다시 올라간 깃발」과 「계단에서는 오른쪽으로 다녀요」에서 중심 생각을 찾을 때 꼭 살필 것을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u4-X42','K4-1-u4-X43','K4-1-u4-X27']::text[],false,'{"seq":20,"concept":"K4-1-u4-C49","difficulty":3,"kind":"mc","stem":"「다시 올라간 깃발」과 「계단에서는 오른쪽으로 다녀요」에서 중심 생각을 찾을 때 꼭 살필 것을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"「다시 올라간 깃발」 — 인물의 말과 행동 / 「계단에서는 오른쪽으로 다녀요」 — 문단별 중심 내용","correct":true},{"t":"「다시 올라간 깃발」 — 첫째 · 둘째 · 셋째 까닭 / 「계단에서는 오른쪽으로 다녀요」 — 인물의 행동","mis":"K4-1-u4-X42"},{"t":"둘 다 사진만 본다","mis":"K4-1-u4-X43"},{"t":"둘 다 마지막 문장 하나만 본다","mis":"K4-1-u4-X27"}],"explanation":["이야기","주장하는 글","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#21','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C29',3,'mc','auto','「우리 모둠 화분」 ④의 「이것」과 ⑥의 「그것」을 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u4-X23','K4-1-u4-X24','K4-1-u4-X22']::text[],false,'{"seq":21,"concept":"K4-1-u4-C29","difficulty":3,"kind":"mc","stem":"「우리 모둠 화분」 ④의 「이것」과 ⑥의 「그것」을 바르게 말한 것은 무엇인가요?","options":[{"t":"「이것」은 물 주고 흙 살피는 일을, 「그것」은 본잎이 나온 일을 가리킨다","correct":true},{"t":"둘 다 화분을 가리킨다","mis":"K4-1-u4-X23"},{"t":"「이것」은 물 주는 일 하나만 가리킨다","mis":"K4-1-u4-X24"},{"t":"둘 다 바로 앞에 보이는 물건만 가리킨다","mis":"K4-1-u4-X22"}],"explanation":["③과 ⑤","앞 내용","첫째예요."],"asset":{"type":"passage","lines":["① 교실 뒤 선반에 작은 화분이 세 개 놓여 있다.","② 화분마다 우리 모둠이 심은 강낭콩이 자란다.","③ 서진이는 날마다 화분에 물을 주고 흙을 살핀다.","④ 이것은 서진이가 스스로 맡은 일이다.","⑤ 지난주에는 떡잎 사이로 본잎이 나왔다.","⑥ 우리 모둠은 그것을 보고 다 함께 기뻐했다."],"title":"우리 모둠 화분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#22','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C55',3,'mc','auto','「뜻을 파악하며 읽어요」에서 배운 것을 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u4-X01','K4-1-u4-X25','K4-1-u4-X31']::text[],false,'{"seq":22,"concept":"K4-1-u4-C55","difficulty":3,"kind":"mc","stem":"「뜻을 파악하며 읽어요」에서 배운 것을 바르게 정리한 것은 무엇인가요?","options":[{"t":"낱말의 뜻을 앞뒤 문장과 사전으로 가려 읽고, 글의 종류에 맞는 방법으로 중심 생각을 찾는다","correct":true},{"t":"낱말의 뜻은 하나뿐이니 중심 생각만 찾으면 된다","mis":"K4-1-u4-X01"},{"t":"가리키는 말은 글에 쓰지 않는 것이 좋다","mis":"K4-1-u4-X25"},{"t":"중심 생각은 글에 없는 내 생각으로 정한다","mis":"K4-1-u4-X31"}],"explanation":["낱말의 뜻","중심 생각","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#23','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C21',4,'essay','teacher','「마음의 문을 열어요」 같은 표어에 여러 가지로 해석되는 낱말을 쓰면 좋은 점 두 가지를 쓰고, 「따뜻하다」를 살린 표어를 하나 지으세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u4-C21","difficulty":4,"kind":"essay","stem":"「마음의 문을 열어요」 같은 표어에 여러 가지로 해석되는 낱말을 쓰면 좋은 점 두 가지를 쓰고, 「따뜻하다」를 살린 표어를 하나 지으세요.","answer_guide":{"answer":"예: 짧은 말로 두 가지 뜻을 함께 전할 수 있고, 재미있어 오래 기억에 남는다. 표어 — 「따뜻한 교실, 따뜻한 마음으로 함께해요!」","scoring_points":["좋은 점 두 가지를 썼는가","「따뜻하다」로 표어를 지었는가","두 뜻이 표어에 함께 드러나는가"]},"explanation":["전달 · 기억","따뜻한 교실","따뜻한 마음"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#24','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C46',4,'essay','teacher','중심 문장이 따로 없는 문단에서 중심 내용을 찾는 방법을 쓰고, 「텃밭 소식」의 중심 내용을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u4-C46","difficulty":4,"kind":"essay","stem":"중심 문장이 따로 없는 문단에서 중심 내용을 찾는 방법을 쓰고, 「텃밭 소식」의 중심 내용을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 중심 문장이 잘 안 보이면 문장들이 공통으로 말하는 내용을 모아 정리한다. 「텃밭 소식」의 중심 내용은 「우리 반 텃밭의 채소들이 잘 자라고 있다.」이다.","scoring_points":["내용을 모아 정리한다고 썼는가","중심 내용을 한 문장으로 썼는가","세 문장을 모두 아우르는가"]},"explanation":["모아서","공통된 내용","한 문장"],"asset":{"type":"passage","lines":["우리 반 텃밭에서는 상추가 잎을 넓게 펼쳤다.","고추에는 하얀 꽃이 피었다.","방울토마토는 벌써 빨갛게 익었다."],"title":"텃밭 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u4_review_d#25','kor',4,1,'u4','','g4_1_kor_u4_review_d','unit_review','K4-1-u4-C51',4,'essay','teacher','낱말 알아맞히기 놀이 문제를 하나 내세요. 빈칸이 있는 문장 두 개와 답을 쓰고, 두 뜻이 동형이의어인지 다의어인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u4-C51","difficulty":4,"kind":"essay","stem":"낱말 알아맞히기 놀이 문제를 하나 내세요. 빈칸이 있는 문장 두 개와 답을 쓰고, 두 뜻이 동형이의어인지 다의어인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「○○을 타고 들판을 달렸다.」 / 「친구와 ○○을 주고받았다.」 답은 「말」이다. 짐승과 소리로 나타낸 것은 뜻이 이어지지 않으므로 동형이의어이다.","scoring_points":["빈칸 문장 두 개와 답을 썼는가","두 빈칸에 모두 들어맞는가","동형이의어인지 다의어인지 까닭과 함께 썼는가"]},"explanation":["두 문장","답","관계와 까닭"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
